        function updateAuctionNewsToggleStatus() {
            const status = document.getElementById('auctionNewsToggleStatus');
            if (status) {
                const vis = _getAuctionNewsVisible();
                status.textContent = vis ? '全网开启' : '全网关闭';
                status.style.color = vis ? 'rgba(74,222,128,0.9)' : 'rgba(239,68,68,0.9)';
            }
        }
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', updateAuctionNewsToggleStatus);
        } else {
            updateAuctionNewsToggleStatus();
        }

        // 轻量、独立地拉取「全网拍卖快讯开关」——与每日新闻缓存解耦，
        // 管理员当天切换后，网页端（含无 token 的纯浏览器用户）也能在数十秒内生效，
        // 不必等到次日缓存过期。优先读公开仓库 news.json（无 token 也能读、无 API 限流），
        // 该文件由管理员切换时经 saveAuctionNewsToRepo 同步写入；若缺失则回退到权威公告 Gist。
        async function fetchAuctionNewsSwitch() {
            let data = null;
            try {
                const r = await fetch(NEWS_URL, { headers: { 'Accept': 'application/json' }, cache: 'no-store' });
                if (r.ok) {
                    const d = await r.json().catch(() => null);
                    if (d && typeof d.auctionNews !== 'undefined') data = d;
                }
            } catch (e) { /* 忽略，走 Gist 兜底 */ }
            if (!data) {
                const token = getGistToken();
                if (token) {
                    try {
                        const url = await getNewsGistUrl();
                        const resp = await fetch(url, {
                            headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` }
                        });
                        if (resp.ok) {
                            const g = await resp.json();
                            const c = g.files && g.files['news.json'] && g.files['news.json'].content;
                            if (c) {
                                const d = JSON.parse(c);
                                if (typeof d.auctionNews !== 'undefined') data = d;
                            }
                        }
                    } catch (e) { /* 忽略 */ }
                }
            }
            if (data && typeof data.auctionNews !== 'undefined') {
                const changed = currentConfig.auctionNews !== data.auctionNews;
                currentConfig.auctionNews = data.auctionNews;
                try { localStorage.setItem('tdjl_auctionNews_cfg', JSON.stringify(currentConfig.auctionNews)); } catch (e) {}
                if (changed) {
                    updateAuctionNewsToggleStatus();
                    updateMarqueeWithBroadcast();
                    const modal = document.getElementById('newsListModal');
                    if (modal && modal.style.display === 'flex') showNewsListModal();
                }
            }
        }

        function showNewsListModal() {
            const modal = document.getElementById('newsListModal');
            const content = document.getElementById('newsListContent');
            modal.style.display = 'flex';

            const now = new Date();
            const activeItems = newsItems.filter(item => {
                if (item.active_time && new Date(item.active_time) > now) return false;
                if (item.expire_time && new Date(item.expire_time) <= now) return false;
                return true;
            });

            // 普通公告HTML
            let normalHtml = '';
            if (activeItems.length === 0) {
                normalHtml = '<div style="color:rgba(255,255,255,0.4);text-align:center;padding:20px;">暂无公告</div>';
            } else {
                normalHtml = activeItems.map((item, index) => {
                    const category = item.category || '';
                    const name = item.name || '无标题';
                    const contentText = stripGithubUrls(item.content || '');
                    const author = item.author || '';
                    const time = item.publish_time || '';

                    const categoryColors = {
                        '公告': '#ffd700',
                        '活动': '#4ade80',
                        '更新': '#60a5fa',
                        '通知': '#f472b6',
                        '其他': '#a78bfa'
                    };
                    const catColor = categoryColors[category] || '#a78bfa';

                    return `
                        <div style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.08);border-radius:10px;padding:15px;margin-bottom:10px;${index === 0 ? 'border-left:3px solid ' + catColor + ';' : ''}">
                            <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
                                ${category ? `<span style="background:${catColor};color:#000;padding:2px 8px;border-radius:4px;font-size:0.75rem;font-weight:bold;">${category}</span>` : ''}
                                <span style="color:#ffd700;font-size:0.95rem;font-weight:500;">${name}</span>
                            </div>
                            ${contentText ? `<div style="color:rgba(255,255,255,0.8);font-size:0.9rem;line-height:1.6;margin-bottom:8px;">${contentText}</div>` : ''}
                            <div style="color:rgba(255,255,255,0.35);font-size:0.75rem;">
                                ${author && author !== '无名' ? author : ''}${author && time ? ' · ' : ''}${time ? time.substring(0, 16) : ''}
                            </div>
                        </div>
                    `;
                }).join('');
            }

            // 拍卖快讯HTML
            let auctionHtml = '';
            const isAdminUser = checkIsAdmin();
            if (auctionBroadcastQueue.length === 0) {
                auctionHtml = '<div style="color:rgba(255,255,255,0.4);text-align:center;padding:20px;">暂无拍卖快讯</div>';
            } else {
                auctionHtml = auctionBroadcastQueue.map(item => {
                    const timeAgo = Math.floor((Date.now() - item.addedAt) / 60000);
                    const timeStr = timeAgo < 1 ? '刚刚' : timeAgo < 60 ? `${timeAgo}分钟前` : timeAgo < 1440 ? `${Math.floor(timeAgo / 60)}小时前` : `${Math.floor(timeAgo / 1440)}天前`;
                    const dateStr = new Date(item.addedAt).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
                    const deleteBtn = isAdminUser ? `<button onclick="adminDeleteAuctionBroadcast('${item.id}')" style="background:rgba(239,68,68,0.2);border:1px solid rgba(239,68,68,0.3);color:#ef4444;font-size:0.7rem;padding:2px 8px;border-radius:4px;cursor:pointer;margin-left:auto;white-space:nowrap;">删除</button>` : '';
                    return `
                        <div style="background:rgba(255,107,107,0.06);border:1px solid rgba(255,107,107,0.15);border-radius:8px;padding:10px 14px;margin-bottom:8px;">
                            <div style="display:flex;align-items:flex-start;gap:6px;">
                                <div style="color:rgba(255,255,255,0.85);font-size:0.85rem;line-height:1.5;flex:1;">${stripGithubUrls(item.text)}</div>
                                ${deleteBtn}
                            </div>
                            <div style="color:rgba(255,255,255,0.3);font-size:0.7rem;margin-top:4px;">${timeStr} · ${dateStr}</div>
                        </div>
                    `;
                }).join('');
            }

            // 需求咨询HTML（需求墙消息）- 样式与需求墙renderMessages完全一致
            let wallHtml = '';
            const nowMs = Date.now();
            const wallNicknameInput = document.getElementById('messageNickname');
            const wallCurrentNickname = wallNicknameInput?.value.trim() || localStorage.getItem('TFJL_UserName') || '';
            const wallAdminNicks = ['gyq', 'GYQ', '龙行'];
            const wallIsAdmin = wallAdminNicks.some(nick => wallCurrentNickname.toLowerCase() === nick.toLowerCase());

            // 过滤消息（与renderMessages一致：只有设置了expireMinutes的才过期）
            const validWallMsgs = (wallMessages || []).filter(msg => {
                if (msg.expireMinutes && msg.expireMinutes > 0) {
                    const expireTime = msg.expireMinutes * 60 * 1000;
                    return (nowMs - (msg.time || 0)) < expireTime;
                }
                return true;
            });
            const recentWallMsgs = validWallMsgs.slice(0, 20);

            if (recentWallMsgs.length === 0) {
                wallHtml = '<div style="color:rgba(255,255,255,0.5);font-size:0.85rem;text-align:center;padding:20px;">暂无需求咨询，快去需求墙发布吧！</div>';
            } else {
                wallHtml = recentWallMsgs.map((msg, index) => {
                    const timeAgo = formatMessageTime(msg.time);
                    let contentHtml = escapeHtml(msg.content);
                    // 非分享消息：可见文本里若有 GitHub 地址一律剥离，不引导用户去 GitHub
                    if (!msg.scriptUrl) contentHtml = stripGithubUrls(contentHtml);

                    // 判断是否可以删除（发布者可删自己的，管理员可删所有）
                    const isOwner = (msg.author || '').toLowerCase() === wallCurrentNickname.toLowerCase();
                    const canDelete = isOwner || wallIsAdmin;

                    // 过期标签
                    const expireLabel = msg.expireMinutes ? `<span style="color:#ff9800;font-size:0.7rem;margin-left:5px;" title="${formatDuration(msg.expireMinutes)}后过期">⏱️${formatDuration(msg.expireMinutes)}</span>` : '';

                    // 脚本分享按钮（与renderMessages一致）
                    if (msg.scriptUrl) {
                        const urlFileName = msg.scriptUrl.split('/').pop() || '';
                        const isJsonFile = urlFileName.toLowerCase().endsWith('.json');
                        const isBackup = msg.shareType === 'backup' || msg.scriptUrl.includes('backup') || contentHtml.includes('备份') || contentHtml.includes('项目') || isJsonFile;

                        if (isBackup) {
                            contentHtml = contentHtml.replace(
                                msg.scriptUrl,
                                `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                                    <a href="javascript:void(0)" onclick="previewScriptFile('${msg.scriptUrl}')" style="color:#e0e0e0;text-decoration:underline;cursor:pointer;background:rgba(224,224,224,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">👁️ 预览</a>
                                    <a href="javascript:void(0)" onclick="downloadScript('${msg.scriptUrl}')" style="color:#4fc3f7;text-decoration:underline;cursor:pointer;background:rgba(79,195,247,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📥 下载</a>
                                    <a href="javascript:void(0)" onclick="importBackupFromWall('${msg.scriptUrl}')" style="color:#ff9800;text-decoration:underline;cursor:pointer;background:rgba(255,152,0,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📦 导入备份</a>
                                </div>`
                            );
                        } else {
                            contentHtml = contentHtml.replace(
                                msg.scriptUrl,
                                `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                                    <a href="javascript:void(0)" onclick="previewScriptFile('${msg.scriptUrl}')" style="color:#e0e0e0;text-decoration:underline;cursor:pointer;background:rgba(224,224,224,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">👁️ 预览</a>
                                    <a href="javascript:void(0)" onclick="downloadScript('${msg.scriptUrl}')" style="color:#4fc3f7;text-decoration:underline;cursor:pointer;background:rgba(79,195,247,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📥 下载</a>
                                    <a href="javascript:void(0)" onclick="importScriptToTxtFiles('${msg.scriptUrl}')" style="color:#4caf50;text-decoration:underline;cursor:pointer;background:rgba(76,175,80,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📄 智能导入</a>
                                </div>`
                            );
                        }
                    }

                    const deleteBtn = canDelete ? `<a href="javascript:void(0)" onclick="deleteWallMsgInModal(${index})" style="color:#ff6b6b;cursor:pointer;margin-left:10px;font-size:0.7rem;" title="${isOwner ? '删除我的消息' : '管理员删除'}">🗑️</a>` : '';

                    return `<div style="background:rgba(255,255,255,0.05);border-radius:8px;padding:10px 12px;font-size:0.85rem;margin-bottom:8px;">
                        <div style="color:#fff;margin-bottom:6px;line-height:1.5;">${contentHtml}</div>
                        <div style="color:rgba(255,255,255,0.5);font-size:0.75rem;">${escapeHtml(msg.author || '匿名')} · ${timeAgo}${expireLabel}${deleteBtn}</div>
                    </div>`;
                }).join('');
            }

            // 拍卖快讯显示开关（全网云端）：关闭后公告弹窗只显示普通公告+需求咨询
            const auctionVis = _getAuctionNewsVisible();
            const auctionCol = auctionVis
                ? `<div style="flex:1;overflow-y:auto;max-height:65vh;padding:0 5px;border-right:1px solid rgba(255,107,107,0.15);">
                        <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(255,107,107,0.2);">
                            <span style="color:#ff6b6b;font-size:0.9rem;font-weight:600;">🔨 拍卖快讯</span>
                            <span style="color:rgba(255,255,255,0.4);font-size:0.7rem;margin-left:auto;">${auctionBroadcastQueue.length}条</span>
                        </div>
                        ${auctionHtml}
                    </div>`
                : '';
            content.innerHTML = `
                <div style="display:flex;gap:10px;min-height:300px;">
                    <div style="flex:1;overflow-y:auto;max-height:65vh;padding-right:5px;${auctionVis ? 'border-right:1px solid rgba(255,215,0,0.15);' : ''}">
                        <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(255,215,0,0.2);">
                            <span style="color:#ffd700;font-size:0.9rem;font-weight:600;">📢 普通公告</span>
                            <span style="color:rgba(255,255,255,0.4);font-size:0.7rem;margin-left:auto;">${activeItems.length}条</span>
                        </div>
                        ${normalHtml}
                    </div>
                    ${auctionCol}
                    <div style="flex:1;overflow-y:auto;max-height:65vh;padding-left:5px;">
                        <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid rgba(255,152,0,0.2);">
                            <span style="color:#ff9800;font-size:0.9rem;font-weight:600;">💡 需求咨询</span>
                            <span style="color:rgba(255,255,255,0.4);font-size:0.7rem;margin-left:auto;">${recentWallMsgs.length}条</span>
                        </div>
                        ${wallHtml}
                    </div>
                </div>
            `;
        }

        function closeNewsListModal() {
            document.getElementById('newsListModal').style.display = 'none';
        }

        // 从全部公告弹窗中删除需求墙消息（删除后刷新弹窗）
        async function deleteWallMsgInModal(index) {
            await deleteMessage(index);
            // 删除完成后刷新弹窗（如果还开着）
            const modal = document.getElementById('newsListModal');
            if (modal && modal.style.display === 'flex') {
                showNewsListModal();
            }
        }

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') closeNewsListModal();
        });

        document.addEventListener('click', (e) => {
            const modal = document.getElementById('newsListModal');
            if (e.target === modal) closeNewsListModal();
        });
        
        // 更新实时时间
        function updateCurrentTime() {
            const now = new Date();
            const year = now.getFullYear();
            const month = String(now.getMonth() + 1).padStart(2, '0');
            const day = String(now.getDate()).padStart(2, '0');
            const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
            const weekday = weekdays[now.getDay()];
            const timeStr = now.toLocaleTimeString('zh-CN', { 
                hour: '2-digit', 
                minute: '2-digit', 
                second: '2-digit',
                hour12: false
            });
            const timeText = document.getElementById('timeText');
            if (timeText) {
                timeText.textContent = `${year}-${month}-${day} ${weekday} ${timeStr}`;
            }
        }
        
        // 初始化实时时间
        function initCurrentTime() {
            updateCurrentTime();
            // 每秒更新一次
            setInterval(updateCurrentTime, 1000);
        }
        
        // 随机颜色数组
        const marqueeColors = [
            '#ffd700',  // 金色
            '#ff6b6b',  // 红色
            '#4ecdc4',  // 青色
            '#45b7d1',  // 蓝色
            '#96ceb4',  // 绿色
            '#ffeaa7',  // 浅黄
            '#fd79a8',  // 粉色
            '#a29bfe',  // 紫色
            '#74b9ff',  // 浅蓝
            '#55efc4',  // 薄荷绿
        ];
        
        // 获取随机颜色
        function getRandomMarqueeColor() {
            return marqueeColors[Math.floor(Math.random() * marqueeColors.length)];
        }
        
        // 重启公告滚动动画：按文本长度动态计算时长，保持恒定滚动速度，
        // 避免文本从短变长时位移基准突变导致"飞快"。每次文本变化都应调用以重置动画。
        let _lastMarqueeText = null;
        function restartMarquee(force) {
            const marqueeEl = document.getElementById('newsMarquee');
            if (!marqueeEl) return;
            const text = marqueeEl.textContent;
            if (!force && text === _lastMarqueeText) return; // 文本未变则不重置（避免每分钟跳回起点）
            _lastMarqueeText = text;
            const SPEED = 45; // px/s，恒定滚动速度
            const W = marqueeEl.scrollWidth; // 含 paddingLeft:100%
            const duration = Math.max(8, W / SPEED); // 至少 8 秒，避免极短文本过快
            marqueeEl.style.animation = 'none';
            void marqueeEl.offsetWidth; // 触发重排，重置动画进度
            marqueeEl.style.animation = 'marqueeScroll ' + duration.toFixed(1) + 's linear infinite';
        }

              // 初始化滚动公告
        function initMarquee() {
            initCurrentTime();
            
            const titleEl = document.getElementById('mainTitle');
            if (titleEl && currentConfig.title) {
                titleEl.textContent = ' ' + currentConfig.title + ' ';
            }
            
            const marqueeText = getNewsMarqueeText();
            const marqueeEl = document.getElementById('newsMarquee');
            if (marqueeEl) {
                marqueeEl.style.paddingLeft = '0';
                marqueeEl.textContent = marqueeText;
                
                setTimeout(() => {
                    marqueeEl.style.paddingLeft = '100%';
                    restartMarquee(true);
                }, 100);
                
                setInterval(() => {
                    // 有拍卖播报且全网/本地开关均未关闭时不改变颜色，保持红色
                    if (_globalBroadcastEnabled && _getAuctionNewsVisible() && auctionBroadcastQueue.length > 0) return;
                    const newColor = getRandomMarqueeColor();
                    marqueeEl.style.color = newColor;
                    marqueeEl.style.textShadow = `0 0 10px ${newColor}, 0 0 20px ${newColor}`;
                }, 3000);
            }
        }

        let activeTimeCheckInterval = null;
        function startActiveTimeCheck() {
            if (activeTimeCheckInterval) clearInterval(activeTimeCheckInterval);
            activeTimeCheckInterval = setInterval(() => {
                const hasTimeChange = newsItems.some(item => {
                    if (item.active_time && new Date(item.active_time) > new Date()) return true;
                    if (item.expire_time && new Date(item.expire_time) <= new Date()) return true;
                    return false;
                });
                if (hasTimeChange) {
                    // 有拍卖播报且全网/本地开关均未关闭时不覆盖，由播报系统管理
                    if (_globalBroadcastEnabled && _getAuctionNewsVisible() && auctionBroadcastQueue.length > 0) return;
                    const marqueeEl = document.getElementById('newsMarquee');
                    if (marqueeEl) {
                        marqueeEl.textContent = getNewsMarqueeText();
                        restartMarquee(); // 文本可能变化，按需重置动画（保持速度恒定）
                    }
                }
            }, 60000);
        }
        
        
        
        // ==================== 刷新公告和标题 ====================
        async function refreshNewsAndTitle() {
            const marqueeEl = document.getElementById('newsMarquee');
            const titleEl = document.getElementById('mainTitle');
            
            const backupNewsItems = [...newsItems];
            const backupTitle = currentConfig.title;
            
            // 有拍卖播报时只刷新数据，不覆盖公告显示
            const hasBroadcast = auctionBroadcastQueue.length > 0;
            if (!hasBroadcast) {
                marqueeEl.textContent = '正在刷新...';
                marqueeEl.style.animation = 'none';
            }
            
            try {
                const freshNews = await fetchNewsFromGitHub();
                newsItems = freshNews;
                
                // 同时刷新拍卖快讯
                try {
                    const broadcasts = await fetchAuctionBroadcastsFromGist();
                    auctionBroadcastQueue = broadcasts;
                } catch (e) {
                    console.warn('刷新拍卖快讯失败:', e);
                }

                // 同时预加载需求墙消息（供公告栏滚动显示）
                try {
                    if (wallMessages.length === 0) {
                        await fetchMessages();
                    }
                } catch (e) {
                    console.warn('预加载需求墙失败:', e);
                }
                
                if (titleEl && currentConfig.title) {
                    titleEl.textContent = ' ' + currentConfig.title + ' ';
                }
                
                saveConfigToCache(currentConfig);
                localStorage.setItem(NEWS_CACHE_KEY, JSON.stringify(newsItems));
                localStorage.setItem(NEWS_CACHE_TIME_KEY, new Date().toISOString());
                
                if (hasBroadcast) {
                    // 有拍卖播报时，更新播报显示即可
                    updateMarqueeWithBroadcast();
                } else {
                    initMarquee();
                }
            } catch (error) {
                console.error('刷新公告失败:', error);
                if (backupNewsItems.length > 0) {
                    newsItems = backupNewsItems;
                } else {
                    newsItems = [...DEFAULT_NEWS];
                }
                currentConfig.title = backupTitle || DEFAULT_CONFIG.title;
                if (!hasBroadcast) {
                    marqueeEl.textContent = '网络不可用，显示缓存数据';
                    setTimeout(() => {
                        marqueeEl.textContent = getNewsMarqueeText();
                        restartMarquee(true);
                    }, 1500);
                }
            }
        }
        
        // ==================== 智能版本切换系统 ====================
        const ONLINE_VERSION_URL = 'https://gyq-svip.github.io/tfjl-web/';
        let isOnlineVersionAvailable = false;
        let isCurrentVersionOnline = false;
        let versionCheckInterval = null;
        
        function initVersionSwitch() {
            // APP(Tauri)内不需要在线版/离线版切换提示，直接跳过
            if (window.__TAURI__ || window.__TAURI_INTERNALS__) return;
            isCurrentVersionOnline = checkIfOnlineVersion();
            checkOnlineVersionAvailability();
            versionCheckInterval = setInterval(checkOnlineVersionAvailability, 30000);
        }
        
        function checkIfOnlineVersion() {
            // 在线版本判断：部署时 HARDCODED_TOKEN 占位符会被替换为真实 token（ghp_ 前缀），有则视为在线版
            const HARDCODED_TOKEN = 'YOUR_GITHUB_TOKEN_HERE';
            return HARDCODED_TOKEN && HARDCODED_TOKEN.length > 20 && HARDCODED_TOKEN.startsWith('ghp_');
        }
        
        async function checkOnlineVersionAvailability() {
            const btn = document.getElementById('versionSwitchBtn');
            if (!btn) return;
            
            try {
                const controller = new AbortController();
                const timeoutId = setTimeout(() => controller.abort(), 3000);
                
                const response = await fetch(ONLINE_VERSION_URL, {
                    method: 'HEAD',
                    mode: 'no-cors',
                    signal: controller.signal
                });
                
                clearTimeout(timeoutId);
                isOnlineVersionAvailable = true;
                updateVersionSwitchButton();
                
            } catch (error) {
                isOnlineVersionAvailable = false;
                updateVersionSwitchButton();
            }
        }
        
        function updateVersionSwitchButton() {
            const btn = document.getElementById('versionSwitchBtn');
            if (!btn) return;
            // APP(Tauri)内永不显示在线版切换图标
            if (window.__TAURI__ || window.__TAURI_INTERNALS__) { btn.style.display = 'none'; return; }
            
            if (isCurrentVersionOnline) {
                // 在线版：始终隐藏版本切换按钮（不再支持下载离线版）
                btn.style.display = 'none';
            } else {
                if (isOnlineVersionAvailable) {
                    btn.style.display = 'flex';
                    btn.innerHTML = '🌐';
                    btn.style.background = 'rgba(0,188,212,0.8)';
                    btn.title = '在线版可用，点击切换';
                } else {
                    btn.style.display = 'none';
                }
            }
        }
        
        function handleVersionSwitch() {
            if (isCurrentVersionOnline) {
                if (!isOnlineVersionAvailable) {
                    alert('当前网络异常，部分功能可能受限。请检查网络后刷新页面。');
                } else {
                    checkOnlineVersionAvailability();
                }
            } else {
                if (isOnlineVersionAvailable) {
                    window.location.href = ONLINE_VERSION_URL;
                }
            }
        }
        

        
        // 页面加载时初始化
        window.onload = async function() {

            // 🔴 强制升级门禁：低于最低版本的桌面端必须先升级（网页版不拦截；断网/缺配置放行）
            try {
                if (await checkVersionGate()) return; // 已弹拦截页，终止后续初始化（含 Gist 数据加载）
            } catch (e) {
                console.warn('[gate] 门禁检查异常，放行:', e);
            }

            // 启动即从本地磁盘恢复昵称（独立于安装目录，重启/更新/卸载重装都不丢），须早于 initMessageWall 等读取逻辑
            await restoreNicknameFromDisk();

            // 应用管理员对浮动控制台可见性的设置（默认隐藏）
            // 🔴 forceOpen=false：启动恢复按 tdjl_consoleOpen 记忆还原上次展开/收起，
            //    修复「收起后刷新/重启又自动展开」（此前无条件 applyConsoleVisibility(true) 顶掉收起态）。
            try {
                applyConsoleVisibility(localStorage.getItem(CONSOLE_VISIBILITY_KEY) === '1', false);
            } catch (e) {}
            
            // 初始化版本号显示 & 自动检查更新（非阻塞）
            initVersionDisplay();
            autoCheckUpdate();
            
            // 初始化消息墙 & 网络监听（非阻塞，不拖慢首屏）
            initMessageWall();
            setupNetworkListener();
            // 注册托盘常驻心跳到 Rust（桌面版；窗口隐藏后 WebView 冻结也能持续在线）
            registerHeartbeatWithRust();

            // —— 首屏核心：尽早加载王城低配版，不排队等待下面的网络统计请求 ——
            try {
                await initIndexedDB();
                // 任何非「王城低配版」的固定启动项都视为残留，统一默认启动王城低配版
                const fixedProject = localStorage.getItem('tdjl_startupProject');
                if (fixedProject && fixedProject !== '' && fixedProject !== '王城低配版') {
                    console.warn('[默认项目] 清除残留固定启动项「' + fixedProject + '」，统一默认启动王城低配版');
                    localStorage.removeItem('tdjl_startupProject');
                }
                // 默认：所有人打开即展示「深海 / 王城低配版」
                await ensureDefaultProjectLoaded();
            } catch (e) {
                console.warn('自动加载项目失败:', e);
            }

            // —— 以下网络统计/快讯请求改为后台非阻塞，不再阻塞首屏 ——
            // 加载全局拍卖快讯开关状态
            loadGlobalBroadcastStatus().catch(()=>{});

            // 初始化统计数据：始终优先从Gist获取最新数据，失败用缓存
            (async () => {
                try {
                    const fresh = await fetchCounterFromGist();
                    if (fresh) { counterData = fresh; saveCounterToCache(counterData); }
                    else { counterData = loadCounterFromCache() || getDefaultCounter(); }
                } catch (error) {
                    console.warn('从Gist获取失败，尝试使用缓存:', error);
                    counterData = loadCounterFromCache() || getDefaultCounter();
                }
                // 🔴 D 盘兜底：缓存为空或拿到的仍是默认值时，尝试用本机备份恢复（Gist 被清空场景）
                if (!counterData || (counterData.total_visits === 0 && counterData.total_downloads === 0 && !counterData.script_downloads)) {
                    try {
                        const disk = await restoreStatsFromDisk();
                        if (disk && (disk.total_visits || disk.total_downloads || (disk.script_downloads && Object.keys(disk.script_downloads).length))) {
                            counterData = disk;
                            saveCounterToCache(counterData);
                            console.warn('✅ 已从 D 盘兜底恢复统计快照');
                        }
                    } catch (e) { /* 忽略 */ }
                }
                updateStatsBar();
                // 🔴 修复：等统计数据（counterData）从 Gist 初始化完成后再记录访问，
                // 避免页面刚加载时 isOnline() 尚未判定为 true 而把访问丢进待同步队列（旧版队列不记时段分布）
                await recordVisit().catch((error) => { console.error('❌ 记录访问失败:', error); });
                // 🔴 启动计数器周期性自调度保活（带随机抖动，错开全网相位，缓解 Gist 写限流）
                startCounterSelfKeepalive();
            })();

            // 启动图片清理定时任务
            startImageCleanup();

            // 加载配置和新闻
            (async () => {
                try { await loadConfig(); await loadNews(); }
                catch (error) { console.error('❌ 加载配置和新闻失败:', error); }
                // 独立拉取全网拍卖快讯开关（绕过每日新闻缓存，确保管理员当天切换即时生效）
                fetchAuctionNewsSwitch().catch(() => {});
                setInterval(() => { if (document.hidden) return; fetchAuctionNewsSwitch().catch(() => {}); }, 30000);
            })();

            // 从Gist加载拍卖快讯（先确保开关状态已加载，避免竞态导致关闭后仍显示）
            (async () => {
                try {
                    await loadGlobalBroadcastStatus().catch(()=>{});
                    const broadcasts = await fetchAuctionBroadcastsFromGist();
                    if (broadcasts && broadcasts.length > 0) {
                        auctionBroadcastQueue = broadcasts;
                    }
                    updateMarqueeWithBroadcast(); // 内部已按 _globalBroadcastEnabled 决定显示拍卖/普通公告
                } catch (error) { console.warn('加载拍卖快讯失败:', error); }
            })();

            // 预加载需求墙消息
            (async () => {
                try { if (wallMessages.length === 0) await fetchMessages(); }
                catch (error) { console.warn('预加载需求墙消息失败:', error); }
                try { checkReputationGain(); } catch (e) {}
            })();

            // 声望变化检测（在线实时"声望上涨"浮条，近似实时：每 30s 比对）
            try { checkReputationGain(); } catch (e) {}
            setInterval(() => { if (document.hidden) return; try { checkReputationGain(); } catch (e) {} }, 30000);

            // 检查登录状态
            if (localStorage.getItem('TFJL_LoggedIn') === 'true') {
                document.getElementById('passwordOverlay').style.display = 'none';
                document.getElementById('mainContent').classList.add('visible');
                
                // 检查是否是纯拍卖模式，如果是则自动打开拍卖行
                if (localStorage.getItem('TFJL_AuctionOnlyMode') === 'true') {
                    setTimeout(() => {
                        openChatRoomEntry();
                    }, 300);
                }
            }
            updateStatsBar();
        };

        // 确保「深海 / 王城低配版」默认项目已加载：本地缓存(IndexedDB) > 远程拉取并缓存 > 内置默认项目
        // 远程 projects/wangcheng-dipin.json 由开发者统一维护（含截图，体积较大），所有用户首次打开即拉取缓存到本地，
        // 之后默认启动展示此项目，无需联网。
        const DEFAULT_PROJECT_REMOTE = './projects/wangcheng-dipin.json';
        const DEFAULT_PROJECT_META_REMOTE = './projects/wangcheng-dipin.meta.json';
        const DEFAULT_PROJECT_CACHE_KEY = 'tdjl_defaultProjectExportDate';
        const DEFAULT_PROJECT_INIT_KEY = 'tdjl_defaultProjectInitialized'; // 首次安装拉取远端并缓存后置位，之后启动永不联网重拉

        async function ensureDefaultProjectLoaded() {
            const DEFAULT_CAT = '深海';
            const DEFAULT_NAME = '王城低配版';

            // 1. 本地缓存优先（瞬间展示，无需联网）；但若远端默认项目已更新（exportDate 更新），则后台重拉覆盖，保证老用户也能自动拿到新皮肤
            try {
                const all = await loadProjectListFromDB();
                const local = all.find(p => p.name === DEFAULT_NAME && (p.category || '默认分类') === DEFAULT_CAT)
                               || all.find(p => p.name === DEFAULT_NAME);
                if (local && hasRealCards(local)) {
                    await loadProjectFromDB(DEFAULT_NAME).catch(() => {});
                    refreshProjectSelectors();
                    if (window._hideLoadingScreen) window._hideLoadingScreen();
                    console.log('[默认项目] 从本地缓存加载:', DEFAULT_NAME);
                    // 标记为已初始化：首次/升级后仅此一次，之后启动不再联网（保证删除持久、启动快、省服务器资源）
                    try { localStorage.setItem(DEFAULT_PROJECT_INIT_KEY, '1'); } catch (e) {}
                    // 后台比对远端 exportDate：若新版则静默重拉并覆盖本地缓存（用户先看到旧版，毫秒级后被新版替换）
                    _maybeRefreshDefaultProject(DEFAULT_CAT, DEFAULT_NAME);
                    // 兜底：默认项目启动即渲染，皮肤索引可能尚未就绪；等皮肤同步完成后重刷融合卡皮肤，确保融合显示
                    if (typeof window._ensureSynced === 'function') {
                        window._ensureSynced().then(() => {
                            if (typeof refreshAllFusionSkins === 'function') refreshAllFusionSkins().catch(() => {});
                        }).catch(() => {});
                    }
                    return;
                }
            } catch (e) { console.warn('[默认项目] 读本地缓存失败:', e); }

            // 2. 本地没有默认项目
            let initialized = false;
            try { initialized = localStorage.getItem(DEFAULT_PROJECT_INIT_KEY) === '1'; } catch (e) {}
            if (initialized) {
                // 已初始化过却找不到 → 说明用户删除了默认项目，不再联网重拉；回退到第一个项目/空白
                console.log('[默认项目] 默认项目已被删除，回退到第一个项目/空白（不联网重拉）');
                await loadFirstProjectOrBlank();
                return;
            }
            // 首次安装：拉取远端并缓存（本次联网后永不重复拉取）
            await fetchAndCacheDefaultProject(DEFAULT_CAT, DEFAULT_NAME);
        }

        function hasRealCards(p) {
            return !!(p && (
                (Array.isArray(p.myHandCards) && p.myHandCards.length) ||
                (Array.isArray(p.teammateHandCards) && p.teammateHandCards.length) ||
                (Array.isArray(p.myPlacedCards) && p.myPlacedCards.length) ||
                (Array.isArray(p.teammatePlacedCards) && p.myPlacedCards.length)
            ));
        }

        async function fetchAndCacheDefaultProject(cat, name) {
            try {
                const resp = await fetch(DEFAULT_PROJECT_REMOTE);
                if (!resp.ok) throw new Error('HTTP ' + resp.status);
                const data = await resp.json();
                const proj = data.project || data;
                proj.name = name;
                proj.category = cat;
                proj.timestamp = new Date().toISOString();
                try { localStorage.setItem(DEFAULT_PROJECT_CACHE_KEY, data.exportDate || ''); } catch (e) {}
                await saveProjectToDB(name, cat, proj).catch(() => {});
                await loadProjectFromDB(name).catch(() => {});
                refreshProjectSelectors();
                if (window._hideLoadingScreen) window._hideLoadingScreen();
                console.log('[默认项目] 已从远程拉取并缓存:', name);
                // 兜底：首次拉取即渲染，皮肤索引可能未就绪，等同步后重刷融合卡
                if (typeof window._ensureSynced === 'function') {
                    window._ensureSynced().then(() => { if (typeof refreshAllFusionSkins === 'function') refreshAllFusionSkins().catch(() => {}); }).catch(() => {});
                }
            } catch (e) {
                console.warn('[默认项目] 远程拉取失败，回退内置默认项目:', e);
                if (DEFAULT_PROJECT && DEFAULT_PROJECT.name) {
                    await loadProjectFromDB(DEFAULT_PROJECT.name).catch(() => {});
                    refreshProjectSelectors();
                    if (window._hideLoadingScreen) window._hideLoadingScreen();
                }
            }
        }

        // 后台静默检查远端默认项目是否有更新：比对远程 exportDate 与本地缓存的 exportDate，
        // 若远程更新则重拉并覆盖本地缓存（老用户强刷即可自动拿到新皮肤，无需手动清 IndexedDB）。
        // 仅当默认项目确实被本地缓存命中（不是首次安装、不是被删除）时才比对，避免与首装/删除回退逻辑冲突。
        async function _maybeRefreshDefaultProject(cat, name) {
            try {
                const localExport = localStorage.getItem(DEFAULT_PROJECT_CACHE_KEY) || '';
                // 🔧 轻量更新检查：只拉几字节的 meta 文件比对 exportDate，避免每次启动下载 10MB 全量 json（占用带宽+主线程解析，拖慢皮肤同步）
                const metaResp = await fetch(DEFAULT_PROJECT_META_REMOTE, { cache: 'no-cache' });
                if (!metaResp.ok) return;
                const meta = await metaResp.json();
                const remoteExport = meta.exportDate || '';
                if (!remoteExport) return;
                // 远程更新（字典序比较 ISO 时间字符串，新日期更大）则重拉覆盖
                if (localExport && localExport >= remoteExport) {
                    console.log('[默认项目] 远端无更新，跳过重拉');
                    return;
                }
                console.log('[默认项目] 远端有更新，后台重拉覆盖本地缓存');
                const resp = await fetch(DEFAULT_PROJECT_REMOTE, { cache: 'no-cache' });
                if (!resp.ok) return;
                const data = await resp.json();
                const proj = data.project || data;
                proj.name = name;
                proj.category = cat;
                proj.timestamp = new Date().toISOString();
                try { localStorage.setItem(DEFAULT_PROJECT_CACHE_KEY, remoteExport); } catch (e) {}
                await saveProjectToDB(name, cat, proj).catch(() => {});
                // 仅当当前展示的正是默认项目时才重新加载并刷新界面
                if (typeof currentProjectName !== 'undefined' && currentProjectName === name) {
                    await loadProjectFromDB(name).catch(() => {});
                    refreshProjectSelectors();
                    if (typeof updateAllCardLevelBadges === 'function') updateAllCardLevelBadges();
                    // 兜底：皮肤索引可能尚未就绪，等同步完成后重刷融合卡皮肤
                    if (typeof window._ensureSynced === 'function') {
                        window._ensureSynced().then(() => { if (typeof refreshAllFusionSkins === 'function') refreshAllFusionSkins().catch(() => {}); }).catch(() => {});
                    }
                }
            } catch (e) {
                console.warn('[默认项目] 后台更新检查失败（不影响使用）:', e);
            }
        }

        // 默认项目被删除/不存在时：打开用户的第一个项目（按创建时间最久的优先）；若无任何项目则空白
        async function loadFirstProjectOrBlank() {
            try {
                const all = await loadProjectListFromDB();
                if (!all || !all.length) {
                    console.log('[默认项目] 无任何项目，空白展示');
                    if (window._hideLoadingScreen) window._hideLoadingScreen();
                    refreshProjectSelectors();
                    return;
                }
                const sorted = all.slice().sort((a, b) => (a.timestamp || '').localeCompare(b.timestamp || ''));
                const first = sorted[0];
                await loadProjectFromDB(first.name).catch(() => {});
                refreshProjectSelectors();
                if (window._hideLoadingScreen) window._hideLoadingScreen();
                console.log('[默认项目] 已回退打开用户第一个项目:', first.name);
            } catch (e) {
                if (window._hideLoadingScreen) window._hideLoadingScreen();
                console.warn('[默认项目] 回退打开失败:', e);
            }
        }

        
        // ==================== 统计功能 ====================
        
        // 获取今天的日期字符串
        function getTodayString() {
            const now = new Date();
            return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        }
        
        // 获取当前时间字符串
        function getCurrentTimeString() {
            // 存 ISO（可解析，便于后续显示相对时间），展示交给 _relTime
            return new Date().toISOString();
        }
        // 北京时间格式化（固定 GMT+8，不依赖用户机器时区，避免「时间对不上」困惑）
        function _fmtBJTime(iso) {
            const d = new Date(iso);
            if (isNaN(d.getTime())) return iso;
            try {
                return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(d) + ' (北京)';
            } catch (e) {
                return d.toLocaleString('zh-CN');
            }
        }
        // 相对时间 + 绝对北京时间，如「3分钟前 · 2026-08-27 14:05:02 (北京)」
        function _relTime(iso) {
            const d = new Date(iso);
            if (isNaN(d.getTime())) return iso; // 旧数据（非 ISO）兜底显示原串
            const diff = Date.now() - d.getTime();
            const abs = _fmtBJTime(iso);
            if (diff < 60000) return '刚刚 · ' + abs;
            if (diff < 3600000) return Math.floor(diff / 60000) + '分钟前 · ' + abs;
            if (diff < 86400000) return Math.floor(diff / 3600000) + '小时前 · ' + abs;
            return Math.floor(diff / 86400000) + '天前 · ' + abs;
        }
        
        // 从缓存加载统计数据
        function loadCounterFromCache() {
            const cached = localStorage.getItem(COUNTER_CACHE_KEY);
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('解析统计缓存失败:', e);
                }
            }
            return null;
        }
        
        // 保存统计数据到缓存
        // 清理异常数据（修复历史累加bug导致的超大数值）
        function sanitizeCounterData(data) {
            if (!data || !data.daily_stats) return data;
            for (const date in data.daily_stats) {
                const s = data.daily_stats[date];
                if (s.hourly_visits) {
                    for (let h = 0; h < 24; h++) {
                        if (s.hourly_visits[h] > 10000) s.hourly_visits[h] = 0;
                    }
                }
                if (s.visits > 100000) s.visits = 0;
                if (s.new_users > 100000) s.new_users = 0;
            }
            return data;
        }

        // ==================== 按设备记录每日访问明细（修复多端访问数被 Math.max 低估） ====================
        // 每个设备只更新自己的条目；合并时按设备取最大值（幂等、可重复合并）；当日访问总数 = 各设备之和
        function mergeDailyDeviceVisits(data, src) {
            if (!src || !src.daily_device_visits) return;
            if (!data.daily_device_visits) data.daily_device_visits = {};
            for (const date in src.daily_device_visits) {
                if (!data.daily_device_visits[date]) data.daily_device_visits[date] = {};
                const sm = src.daily_device_visits[date];
                for (const id in sm) {
                    const s = sm[id] || {};
                    const t = data.daily_device_visits[date][id] || { v: 0, a: 0, w: 0 };
                    t.v = Math.max(t.v, s.v || 0);
                    t.a = Math.max(t.a, s.a || 0);
                    t.w = Math.max(t.w, s.w || 0);
                    data.daily_device_visits[date][id] = t;
                }
            }
            for (const date in data.daily_device_visits) {
                recomputeDailyVisitsOn(data, date);
            }
        }
        // 由设备明细重算某日访问总数（跨设备求和）；无明细的日期保持原值不动（兼容历史数据）
        function recomputeDailyVisitsOn(data, date) {
            if (!data.daily_stats) data.daily_stats = {};
            if (!data.daily_stats[date]) data.daily_stats[date] = { visits: 0, app_visits: 0, web_visits: 0, downloads: 0, new_users: 0, new_app_users: 0, new_web_users: 0, hourly_visits: new Array(24).fill(0) };
            const map = data.daily_device_visits && data.daily_device_visits[date];
            // 🔴 无明细（合并/待同步路径未写入 daily_device_visits）时，保留已直接累计的 visits，绝不归零
            if (!map) return;
            let v = 0, a = 0, w = 0;
            for (const id in map) { v += map[id].v || 0; a += map[id].a || 0; w += map[id].w || 0; }
            // 🔴 用 Math.max 而非覆盖：既保留跨设备求和结果，又不会把已直接累加的访问数压低
            data.daily_stats[date].visits = Math.max(data.daily_stats[date].visits || 0, v);
            data.daily_stats[date].app_visits = Math.max(data.daily_stats[date].app_visits || 0, a);
            data.daily_stats[date].web_visits = Math.max(data.daily_stats[date].web_visits || 0, w);
        }

        // 累计总访问按设备汇总（与每日访问同思路，避免多端 Math.max 低估）
        function mergeDeviceVisits(target, src) {
            if (!src || !src.device_visits) return;
            if (!target.device_visits || typeof target.device_visits !== 'object') target.device_visits = {};
            for (const id in src.device_visits) {
                const s = src.device_visits[id] || 0;
                if ((target.device_visits[id] || 0) < s) target.device_visits[id] = s;
            }
        }
        function recomputeTotalVisits(data) {
            if (!data) return;
            if (!data.device_visits || typeof data.device_visits !== 'object') data.device_visits = {};
            let sum = 0;
            for (const id in data.device_visits) sum += (data.device_visits[id] || 0);
            data.total_visits = sum;
        }
        // 历史数据无 device_visits 时，用既有 total_visits 作基线(_legacy)，避免累计数变小
        function ensureDeviceVisitsBaseline(data) {
            if (!data) return;
            if (!data.device_visits || typeof data.device_visits !== 'object') data.device_visits = {};
            if (Object.keys(data.device_visits).length === 0 && (data.total_visits || 0) > 0) {
                data.device_visits['_legacy'] = data.total_visits;
            }
        }

        // 在线用户条目统一为对象 { t: 最后活跃时间戳, nick: 昵称, src: 'app'|'web' }（旧数据可能为纯数字时间戳，需兼容）
        function _olTs(v) { return (v && typeof v === 'object') ? (v.t || 0) : (typeof v === 'number' ? v : 0); }
        function _olRec(nick, src, bg) { const r = { t: Date.now(), nick: (nick || '').toString().slice(0, 24), src: src === 'app' ? 'app' : 'web' }; if (bg) r.bg = 1; return r; }
        function _myNick() { return (localStorage.getItem('TFJL_UserName') || '').trim(); }
        // s1.0.107：桌面 App（含最小化到托盘）持续心跳，也应算在线。
        // 窗口隐藏后 WebView 会节流定时器（最低约 1 次/分钟），故 src==='app' 的条目判定窗口放宽到 15 分钟；
        // 网页端仍用 5 分钟窗口，保持"关掉标签就下线"的准确性。
        const APP_ONLINE_GRACE = 900000;
        function _olIsApp(v) { return !!(v && typeof v === 'object' && v.src === 'app'); }
        function _olTimeoutFor(rec, base) { const b = base || 1800000; return _olIsApp(rec) ? Math.max(b, APP_ONLINE_GRACE) : b; }
        function _olAlive(rec, base, now) { const ts = _olTs(rec); if (!ts) return false; return ((now || Date.now()) - ts) <= _olTimeoutFor(rec, base); }
        // 合并在线用户：按设备取"最新活跃时间戳"的并集（解决多设备同步互相覆盖、在线数漏算），并保留昵称/来源
        function mergeOnlineUsers(target, src) {
            if (!src || !src.online_users) return;
            if (!target.online_users || typeof target.online_users !== 'object') target.online_users = {};
            for (const id in src.online_users) {
                const s = src.online_users[id];
                const ts = _olTs(s);
                if (ts === 0) continue;
                const tgt = target.online_users[id];
                const exTs = _olTs(tgt);
                if (!tgt || ts >= exTs) {
                    const sRec = (s && typeof s === 'object') ? s : null;
                    const tRec = (tgt && typeof tgt === 'object') ? tgt : null;
                    const _mRec = {
                        t: ts,
                        nick: (sRec && sRec.nick) || (tRec && tRec.nick) || '',
                        src: (sRec && sRec.src) || (tRec && tRec.src) || ''
                    };
                    if (sRec && sRec.bg) _mRec.bg = 1;
                    target.online_users[id] = _mRec;
                }
            }
        }

        // 最后离线记录（s1.0.84）：用户从在线名单过期/主动隐藏时，记入 offline_history（仅管理员可见，30天自动清除，绝不公开给普通用户）
        let _windowHidden = false; // 桌面端隐藏到托盘时为 true（s1.0.107 起仍持续心跳、仍算在线，仅作"后台运行"标记）
        const OFFLINE_KEEP_DAYS = 30;
        const OFFLINE_MAX = 500;
        function _offlineCutoff() { return Date.now() - OFFLINE_KEEP_DAYS * 86400000; }
        function recordOffline(id, rec) {
            try {
                if (!counterData || !counterData.online_users) return;
                if (!counterData.offline_history) counterData.offline_history = [];
                const ts = _olTs(rec);
                if (ts === 0) return;
                const r = (rec && typeof rec === 'object') ? rec : null;
                const arr = counterData.offline_history.filter(e => e.id !== id);
                arr.push({ id: id, nick: (r && r.nick) || '', src: (r && r.src) === 'app' ? 'app' : 'web', lastSeen: ts, offlineAt: Date.now() });
                counterData.offline_history = arr.filter(e => e.offlineAt >= _offlineCutoff()).slice(-OFFLINE_MAX);
            } catch (e) {}
        }
        function pruneExpiredOnline(record) {
            if (!counterData || !counterData.online_users) return;
            const now = Date.now();
            const timeout = counterData.online_timeout || 1800000;
            for (const id in counterData.online_users) {
                if (!_olAlive(counterData.online_users[id], timeout, now)) {
                    if (record) recordOffline(id, counterData.online_users[id]);
                    delete counterData.online_users[id];
                }
            }
        }
        function cleanupOfflineHistory() {
            try {
                if (!counterData || !counterData.offline_history) return;
                counterData.offline_history = counterData.offline_history.filter(e => e.offlineAt >= _offlineCutoff()).slice(-OFFLINE_MAX);
            } catch (e) {}
        }
        function mergeOfflineHistory(target, src) {
            if (!src || !Array.isArray(src.offline_history)) return;
            if (!target.offline_history) target.offline_history = [];
            const map = {};
            target.offline_history.forEach(e => { if (e && e.id) map[e.id] = e; });
            src.offline_history.forEach(e => {
                if (!e || !e.id) return;
                const cur = map[e.id];
                if (!cur || (e.offlineAt || 0) >= (cur.offlineAt || 0)) map[e.id] = e;
            });
            const arr = Object.values(map).filter(e => e.offlineAt >= _offlineCutoff()).slice(-OFFLINE_MAX);
            arr.sort((a, b) => b.offlineAt - a.offlineAt);
            target.offline_history = arr;
        }
        // 桌面端：窗口隐藏（最小化到托盘）不再视为下线——托盘挂机仍在后台跑心跳，仍计入在线（s1.0.107）
        function setupWindowHiddenDetection() {
            if (!window.__TAURI__) return;
            document.addEventListener('visibilitychange', function () {
                _windowHidden = (document.visibilityState === 'hidden');
                // 隐藏/恢复瞬间都补一次心跳并同步：托盘期间定时器会被 WebView 节流，先把最新时间戳写上去
                keepSelfOnlineLocal();
                if (isOnline()) syncCounterToGist();
            });
        }

        function saveCounterToCache(data) {
            // 保存前先清理异常数据
            data = sanitizeCounterData(data);
            localStorage.setItem(COUNTER_CACHE_KEY, JSON.stringify(data));
            localStorage.setItem(COUNTER_CACHE_TIME_KEY, new Date().toISOString());
            // D 盘兜底双写（仅 App / Tauri 环境；Gist 被清空时能从本机恢复）
            backupStatsToDisk();
        }
        
        // 从缓存加载待同步队列
        function loadPendingSync() {
            const cached = localStorage.getItem('TFJL_Pending_Sync');
            if (cached) {
                try {
                    return JSON.parse(cached);
                } catch (e) {
                    console.error('解析待同步队列失败:', e);
                }
            }
            return [];
        }
        
        // 保存待同步队列到缓存
        function savePendingSync(queue) {
            localStorage.setItem('TFJL_Pending_Sync', JSON.stringify(queue));
        }
        
        // ==================== 统计合并 / 本地磁盘兜底 ====================
        // 🔴 全字段最大值合并（防止任何字段被空/旧数据覆盖丢失，尤其是 script_downloads）
        function mergeCounters(target, src) {
            if (!target || typeof target !== 'object') target = {};
            if (!src || typeof src !== 'object') return target;
            // 🔴 累计总访问按设备汇总（求和），避免多端 Math.max 把跨设备访问数压成单端最大值
            mergeDeviceVisits(target, src); ensureDeviceVisitsBaseline(target); recomputeTotalVisits(target);
            target.total_downloads = Math.max(target.total_downloads || 0, src.total_downloads || 0);
            target.total_users = Math.max(target.total_users || 0, src.total_users || 0);
            // unique_users / active_today_users：取并集
            if (Array.isArray(src.unique_users)) {
                if (!Array.isArray(target.unique_users)) target.unique_users = [];
                src.unique_users.forEach(id => { if (!target.unique_users.includes(id)) target.unique_users.push(id); });
            }
            target.total_users = target.unique_users ? target.unique_users.length : (target.total_users || 0);
            // 🔴 今日活跃用户：同天取并集；跨天则以后写入的一方（active_date 较新）整组覆盖，
            // 绝不可把"昨天"的活跃设备并入"今天"，否则每日重置失效、数值永久累积（表现为一直卡在某个数，且今日 visits=0 却显示几十个活跃用户）
            if (Array.isArray(src.active_today_users)) {
                if (!Array.isArray(target.active_today_users)) target.active_today_users = [];
                const _td = target.active_date, _sd = src.active_date;
                if (_td && _sd && _td !== _sd) {
                    const _srcNewer = _sd > _td;
                    const _win = _srcNewer ? src : target;
                    target.active_today_users = Array.isArray(_win.active_today_users) ? _win.active_today_users.slice() : [];
                    target.active_date = _win.active_date;
                } else {
                    src.active_today_users.forEach(id => { if (!target.active_today_users.includes(id)) target.active_today_users.push(id); });
                }
            }
            target.active_today = target.active_today_users ? target.active_today_users.length : (target.active_today || 0);
            // 🔴 script_downloads：并集 key + 每 key 取最大值（之前漏合并，是脚本下载统计莫名变空的真凶）
            if (src.script_downloads && typeof src.script_downloads === 'object') {
                if (!target.script_downloads || typeof target.script_downloads !== 'object') target.script_downloads = {};
                for (const k in src.script_downloads) {
                    target.script_downloads[k] = Math.max(target.script_downloads[k] || 0, src.script_downloads[k] || 0);
                }
            }
            // sources：逐字段最大值
            if (src.sources && typeof src.sources === 'object') {
                if (!target.sources) target.sources = {};
                for (const k in src.sources) target.sources[k] = Math.max(target.sources[k] || 0, src.sources[k] || 0);
            }
            // user_sources：并集
            if (src.user_sources && typeof src.user_sources === 'object') {
                if (!target.user_sources) target.user_sources = {};
                for (const uid in src.user_sources) { if (!target.user_sources[uid]) target.user_sources[uid] = src.user_sources[uid]; }
            }
            // daily_stats：逐日最大值（visits/downloads/new_users/来源/hourly）
            if (src.daily_stats && typeof src.daily_stats === 'object') {
                if (!target.daily_stats || typeof target.daily_stats !== 'object') target.daily_stats = {};
                for (const date in src.daily_stats) {
                    const sd = src.daily_stats[date];
                    if (!sd || typeof sd !== 'object') continue;
                    if (!target.daily_stats[date]) {
                        target.daily_stats[date] = JSON.parse(JSON.stringify(sd));
                    } else {
                        const td = target.daily_stats[date];
                        td.visits = Math.max(td.visits || 0, sd.visits || 0);
                        td.downloads = Math.max(td.downloads || 0, sd.downloads || 0);
                        td.new_users = Math.max(td.new_users || 0, sd.new_users || 0);
                        td.app_visits = Math.max(td.app_visits || 0, sd.app_visits || 0);
                        td.web_visits = Math.max(td.web_visits || 0, sd.web_visits || 0);
                        td.new_app_users = Math.max(td.new_app_users || 0, sd.new_app_users || 0);
                        td.new_web_users = Math.max(td.new_web_users || 0, sd.new_web_users || 0);
                        if (Array.isArray(sd.hourly_visits)) {
                            if (!Array.isArray(td.hourly_visits)) td.hourly_visits = new Array(24).fill(0);
                            for (let h = 0; h < 24; h++) td.hourly_visits[h] = Math.max(td.hourly_visits[h] || 0, sd.hourly_visits[h] || 0);
                        }
                    }
                }
            }
            // 🔴 合并按设备的每日访问明细，并由明细重算当日访问总数（求和，避免 Math.max 低估）
            mergeDailyDeviceVisits(target, src);
            // 离线记录：按设备取较新离线时间并集，30天自动清除
            mergeOfflineHistory(target, src);
            return target;
        }

        // 本地磁盘兜底：把统计快照写到 D 盘（仅 App / Tauri 环境），Gist 被清空时能从本机恢复
        const STATS_BACKUP_PATH = 'D:\\withfriends\\塔防精灵助手数据\\tfjl-stats.json';
        function _statsInvoke(cmd, args) {
            const fn = (window.__TAURI_INTERNALS__ && typeof window.__TAURI_INTERNALS__.invoke === 'function') ? window.__TAURI_INTERNALS__.invoke
                : (window.__TAURI__ && window.__TAURI__.core && typeof window.__TAURI__.core.invoke === 'function') ? window.__TAURI__.core.invoke
                : (window.__TAURI__ && typeof window.__TAURI__.invoke === 'function') ? window.__TAURI__.invoke : null;
            return fn ? fn(cmd, args) : Promise.reject(new Error('NOT_TAURI'));
        }
        async function backupStatsToDisk() {
            try { if (counterData) await _statsInvoke('write_text_file', { filePath: STATS_BACKUP_PATH, content: JSON.stringify(counterData, null, 2) }); }
            catch (e) { /* 非 Tauri / 写失败静默 */ }
        }
        async function restoreStatsFromDisk() {
            try {
                const txt = await _statsInvoke('read_text_file_auto', { filePath: STATS_BACKUP_PATH });
                if (!txt) return null;
                const d = JSON.parse(txt);
                return (d && typeof d === 'object') ? d : null;
            } catch (e) { return null; }
        }
        // 最近一次成功同步到的远端快照：写之前再并一遍，确保绝不回退已确认的数据
        let lastGoodCounter = null;

        // 获取默认统计数据结构
        function getDefaultCounter() {
            const today = getTodayString();
            return {
                total_visits: 0,
                device_visits: {},  // { [deviceId]: 累计访问数 }，用于跨设备求和累计总访问（避免 Math.max 低估）
                total_users: 0,
                unique_users: [],
                total_downloads: 0,
                active_today: 0,
                active_today_users: [],
                active_today_app: 0,
                active_today_web: 0,
                active_today_app_users: [],
                active_today_web_users: [],
                active_date: today,
                online_users: {},
                online_timeout: 1800000,
                offline_history: [],  // 最近离线记录（仅管理员可见，30天自动清除，绝不公开给普通用户）
                sources: { app_visits: 0, web_visits: 0, new_app_users: 0, new_web_users: 0, app_users: 0, web_users: 0 },
                user_sources: {},  // 每个用户的注册平台：{ deviceId: 'app' | 'web' }
                daily_stats: {
                    [today]: {
                        visits: 0,
                        app_visits: 0,
                        web_visits: 0,
                        downloads: 0,
                        new_users: 0,
                        new_app_users: 0,
                        new_web_users: 0
                    }
                },
                script_downloads: {},  // { "脚本名": 次数, ... }
                daily_device_visits: {},  // { [date]: { [deviceId]: { v: 访问数, a: APP访问, w: 网页访问 } } }，用于跨设备访问数求和
                last_updated: getCurrentTimeString()
            };
        }
        
        // 检查网络状态
        function isOnline() {
            return navigator.onLine;
        }
        
        // 从Gist获取统计数据
        async function fetchCounterFromGist() {
            try {
                const token = getGistToken();
                
                // 强制只用硬编码的 COUNTER_GIST_ID（铁律：counter Gist 必须归 gyq-svip 且硬编码，禁止从 localStorage/索引自动发现陌生 Gist）
                const counterGistId = COUNTER_GIST_ID;
                
                // 如果都没有，尝试从索引文件获取
                if (!counterGistId) {
                    try {
                        const indexUrl = await getIndexGistUrl();
                        const indexResponse = await fetch(indexUrl, {
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                ...(token && { 'Authorization': `token ${token}` })
                            }
                        });
                        
                        if (indexResponse.ok) {
                            const data = await indexResponse.json();
                            if (data.files && data.files['room_index.json'] && data.files['room_index.json'].content) {
                                try {
                                    const indexData = JSON.parse(data.files['room_index.json'].content);
                                    if (indexData['counter']) {
                                        counterGistId = indexData['counter'];
                                        // 缓存到 localStorage
                                        localStorage.setItem('counter_gist_id', counterGistId);
                                    }
                                } catch (e) {
                                    console.warn('解析索引文件失败');
                                }
                            }
                        }
                    } catch (e) {
                        console.warn('获取索引文件失败:', e);
                    }
                }
                
                if (counterGistId) {
                    // 从独立 Gist 加载
                    const response = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                        headers: {
                            'Accept': 'application/vnd.github.v3+json',
                            ...(token && { 'Authorization': `token ${token}` })
                        }
                    });
                    
                    if (response.ok) {
                        const data = await response.json();
                        if (data.files && data.files['counter.json'] && data.files['counter.json'].content) {
                            const content = data.files['counter.json'].content;
                            let parsed;
                            try {
                                parsed = JSON.parse(content);
                            } catch (parseErr) {
                                console.warn('⚠️ counter.json 解析失败，返回 null:', parseErr.message);
                                return null;
                            }
                            
                            // 向后兼容：转换旧数据格式
                            if (!parsed.unique_users) parsed.unique_users = [];
                            if (!parsed.active_today_users) parsed.active_today_users = [];
                            if (parsed.total_users === undefined) parsed.total_users = parsed.unique_users.length;
                            if (parsed.active_today === undefined) parsed.active_today = parsed.active_today_users.length;
                            if (parsed.total_visits === undefined) parsed.total_visits = 0;
                            ensureDeviceVisitsBaseline(parsed); recomputeTotalVisits(parsed);
                            if (parsed.total_downloads === undefined) parsed.total_downloads = 0;
                            if (!parsed.online_users) parsed.online_users = {};
                            if (!parsed.online_timeout || parsed.online_timeout === 3600000 || parsed.online_timeout === 7200000) parsed.online_timeout = 1800000;
                            if (window._applyOnlineTimeoutCfg) window._applyOnlineTimeoutCfg(parsed); // 🔴 管理员离线阈值覆盖（功能开关面板 onlineTimeoutMin）
                            if (!parsed.sources) parsed.sources = { app_visits: 0, web_visits: 0 };
                            if (parsed.sources.new_app_users === undefined) parsed.sources.new_app_users = 0;
                            if (parsed.sources.new_web_users === undefined) parsed.sources.new_web_users = 0;
                            if (parsed.sources.app_users === undefined) parsed.sources.app_users = 0;
                            if (parsed.sources.web_users === undefined) parsed.sources.web_users = 0;
                            if (!parsed.user_sources) parsed.user_sources = {};
                            
                            // ========== 历史数据迁移：旧用户统一归为网页来源 ==========
                            if (parsed.unique_users && parsed.unique_users.length > 0) {
                                let appUsers = 0, webUsers = 0;
                                let needRecalc = false;
                                for (const uid of parsed.unique_users) {
                                    if (!parsed.user_sources[uid]) {
                                        parsed.user_sources[uid] = 'web'; // 旧用户归为网页
                                        needRecalc = true;
                                    }
                                    if (parsed.user_sources[uid] === 'app') appUsers++;
                                    else webUsers++;
                                }
                                if (needRecalc || parsed.sources.app_users + parsed.sources.web_users !== parsed.unique_users.length) {
                                    parsed.sources.app_users = appUsers;
                                    parsed.sources.web_users = webUsers;
                                }
                            }
                            if (parsed.active_today_app === undefined) parsed.active_today_app = 0;
                            if (parsed.active_today_web === undefined) parsed.active_today_web = 0;
                            if (!parsed.active_today_app_users) parsed.active_today_app_users = [];
                            if (!parsed.active_today_web_users) parsed.active_today_web_users = [];
                            
                            // ========== 历史数据迁移：旧数据未区分APP/网页来源，全部归为网页 ==========
                            const srcApp = parsed.sources.app_visits || 0;
                            const srcWeb = parsed.sources.web_visits || 0;
                            const srcTotal = parsed.total_visits || 0;
                            if (srcApp + srcWeb < srcTotal) {
                                // 差额全部补到网页访问（历史数据无APP来源记录）
                                parsed.sources.web_visits = srcWeb + (srcTotal - srcApp - srcWeb);
                                // 对每日数据同样处理
                                if (parsed.daily_stats) {
                                    for (const date in parsed.daily_stats) {
                                        const ds = parsed.daily_stats[date];
                                        const dApp = ds.app_visits || 0;
                                        const dWeb = ds.web_visits || 0;
                                        const dTotal = ds.visits || 0;
                                        if (dApp + dWeb < dTotal) {
                                            ds.web_visits = dWeb + (dTotal - dApp - dWeb);
                                        }
                                        // 新增用户来源：历史数据也归为网页
                                        const nApp = ds.new_app_users || 0;
                                        const nWeb = ds.new_web_users || 0;
                                        const nTotal = ds.new_users || 0;
                                        if (nApp + nWeb < nTotal) {
                                            ds.new_web_users = nWeb + (nTotal - nApp - nWeb);
                                        }
                                    }
                                }
                            }
                            // 总计新增用户来源迁移
                            const srcNewApp = parsed.sources.new_app_users || 0;
                            const srcNewWeb = parsed.sources.new_web_users || 0;
                            const totalNewUsers = parsed.total_users || 0;
                            if (srcNewApp + srcNewWeb < totalNewUsers) {
                                parsed.sources.new_web_users = srcNewWeb + (totalNewUsers - srcNewApp - srcNewWeb);
                            }
                            
                            // 检查日期是否变化，如果新的一天则清空今日活跃用户
                            const today = getTodayString();
                            if (!parsed.active_date || parsed.active_date !== today) {
                                parsed.active_today_users = [];
                                parsed.active_today = 0;
                                parsed.active_today_app_users = [];
                                parsed.active_today_web_users = [];
                                parsed.active_today_app = 0;
                                parsed.active_today_web = 0;
                                parsed.active_date = today;
                            }
                            
                            // 清理过期的在线用户
                            const now = Date.now();
                            const timeout = parsed.online_timeout;
                            for (const id in parsed.online_users) {
                                if (!_olAlive(parsed.online_users[id], timeout, now)) {
                                    delete parsed.online_users[id];
                                }
                            }
                            
                            return parsed;
                        }
                    } else if (response.status === 404 || response.status === 403) {
                        // Gist 不存在或无权限，清除缓存
                        localStorage.removeItem('counter_gist_id');
                    }
                }
                
                // 🔴 修复（v260805-266）：获取失败（网络/限流）返回 null 而非空默认，
                // 否则调用方会用空对象覆盖远程、导致统计全丢。调用方会回退到本地缓存。
                console.warn('⚠️ 统计数据 Gist 获取失败/不存在，返回 null（调用方回退本地缓存）');
                return null;
            } catch (error) {
                console.warn('⚠️ 获取统计数据异常，返回 null（调用方回退本地缓存）:', error.message);
                return null;
            }
        }
        
        // 更新统计数据
        async function updateCounter(type, scriptName = null) {
            try {
                // 获取本地缓存作为备份
                const localData = loadCounterFromCache();
                
                // 先从Gist获取最新数据，避免覆盖其他设备的更新
                if (isOnline()) {
                    try {
                        const fresh = await fetchCounterFromGist();
                        if (fresh) {
                            // 合并本地缓存的关键数据到 Gist 数据
                            // 确保使用最大的访问数和用户数，防止数据丢失
                            if (localData) {
                                // 合并 unique_users（用户列表）
                                if (localData.unique_users && Array.isArray(localData.unique_users)) {
                                    localData.unique_users.forEach(id => {
                                        if (!fresh.unique_users.includes(id)) {
                                            fresh.unique_users.push(id);
                                        }
                                    });
                                }
                                // 合并今日活跃用户
                                if (localData.active_today_users && Array.isArray(localData.active_today_users)) {
                                    localData.active_today_users.forEach(id => {
                                        if (!fresh.active_today_users.includes(id)) {
                                            fresh.active_today_users.push(id);
                                        }
                                    });
                                }
                                // 取最大访问数和下载数（防止数据回退）
                                mergeDeviceVisits(fresh, localData); ensureDeviceVisitsBaseline(fresh); recomputeTotalVisits(fresh);
                                fresh.total_users = Math.max(fresh.total_users || 0, fresh.unique_users.length);
                                fresh.total_downloads = Math.max(fresh.total_downloads || 0, localData.total_downloads || 0);
                                fresh.active_today = fresh.active_today_users.length;
                                
                                // 合并来源统计（APP/网页，取最大值防止数据回退）
                                if (!fresh.sources) fresh.sources = { app_visits: 0, web_visits: 0 };
                                if (localData.sources) {
                                    fresh.sources.app_visits = Math.max(fresh.sources.app_visits || 0, localData.sources.app_visits || 0);
                                    fresh.sources.web_visits = Math.max(fresh.sources.web_visits || 0, localData.sources.web_visits || 0);
                                    fresh.sources.new_app_users = Math.max(fresh.sources.new_app_users || 0, localData.sources.new_app_users || 0);
                                    fresh.sources.new_web_users = Math.max(fresh.sources.new_web_users || 0, localData.sources.new_web_users || 0);
                                    // 合并平台用户数（取最大值）
                                    fresh.sources.app_users = Math.max(fresh.sources.app_users || 0, localData.sources.app_users || 0);
                                    fresh.sources.web_users = Math.max(fresh.sources.web_users || 0, localData.sources.web_users || 0);
                                }
                                
                                // 合并用户平台归属（user_sources）
                                if (localData.user_sources && typeof localData.user_sources === 'object') {
                                    if (!fresh.user_sources) fresh.user_sources = {};
                                    for (const uid in localData.user_sources) {
                                        if (!fresh.user_sources[uid]) {
                                            fresh.user_sources[uid] = localData.user_sources[uid];
                                        }
                                    }
                                    // 重新统计平台用户数
                                    let appU = 0, webU = 0;
                                    for (const uid in fresh.user_sources) {
                                        if (fresh.user_sources[uid] === 'app') appU++;
                                        else webU++;
                                    }
                                    fresh.sources.app_users = appU;
                                    fresh.sources.web_users = webU;
                                }
                                
                                // 合并今日活跃APP/网页用户
                                if (localData.active_today_app_users && Array.isArray(localData.active_today_app_users)) {
                                    if (!fresh.active_today_app_users) fresh.active_today_app_users = [];
                                    localData.active_today_app_users.forEach(id => {
                                        if (!fresh.active_today_app_users.includes(id)) {
                                            fresh.active_today_app_users.push(id);
                                        }
                                    });
                                }
                                if (localData.active_today_web_users && Array.isArray(localData.active_today_web_users)) {
                                    if (!fresh.active_today_web_users) fresh.active_today_web_users = [];
                                    localData.active_today_web_users.forEach(id => {
                                        if (!fresh.active_today_web_users.includes(id)) {
                                            fresh.active_today_web_users.push(id);
                                        }
                                    });
                                }
                                
                                // 合并每日统计数据
                                if (localData.daily_stats) {
                                    for (const date in localData.daily_stats) {
                                        if (!fresh.daily_stats[date]) {
                                            fresh.daily_stats[date] = localData.daily_stats[date];
                                        } else {
                                            // 取每日数据的最大值
                                            fresh.daily_stats[date].visits = Math.max(
                                                fresh.daily_stats[date].visits || 0,
                                                localData.daily_stats[date].visits || 0
                                            );
                                            fresh.daily_stats[date].downloads = Math.max(
                                                fresh.daily_stats[date].downloads || 0,
                                                localData.daily_stats[date].downloads || 0
                                            );
                                            fresh.daily_stats[date].new_users = Math.max(
                                                fresh.daily_stats[date].new_users || 0,
                                                localData.daily_stats[date].new_users || 0
                                            );
                                            // 合并每日APP/网页来源（取最大值防止数据回退）
                                            fresh.daily_stats[date].app_visits = Math.max(
                                                fresh.daily_stats[date].app_visits || 0,
                                                localData.daily_stats[date].app_visits || 0
                                            );
                                            fresh.daily_stats[date].web_visits = Math.max(
                                                fresh.daily_stats[date].web_visits || 0,
                                                localData.daily_stats[date].web_visits || 0
                                            );
                                            // 合并每日新增用户来源（取最大值防止数据回退）
                                            fresh.daily_stats[date].new_app_users = Math.max(
                                                fresh.daily_stats[date].new_app_users || 0,
                                                localData.daily_stats[date].new_app_users || 0
                                            );
                                            fresh.daily_stats[date].new_web_users = Math.max(
                                                fresh.daily_stats[date].new_web_users || 0,
                                                localData.daily_stats[date].new_web_users || 0
                                            );
                                            // 合并时段分布（取最大值，避免刷新累加导致数据膨胀）
                                            if (localData.daily_stats[date].hourly_visits) {
                                                if (!fresh.daily_stats[date].hourly_visits) fresh.daily_stats[date].hourly_visits = new Array(24).fill(0);
                                                for (let h = 0; h < 24; h++) {
                                                    fresh.daily_stats[date].hourly_visits[h] = Math.max(
                                                        fresh.daily_stats[date].hourly_visits[h] || 0,
                                                        localData.daily_stats[date].hourly_visits[h] || 0
                                                    );
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            // 确保fresh数据所有必要字段存在，缺失用默认值填充
                            const defaultCounter = getDefaultCounter();
                            const requiredFields = ['unique_users', 'active_today_users', 'daily_stats', 'online_users'];
                            for (const field of requiredFields) {
                                if (fresh[field] === undefined || fresh[field] === null) {
                                    fresh[field] = defaultCounter[field];
                                }
                            }
                            if (fresh.total_visits === undefined || fresh.total_visits === null) fresh.total_visits = 0;
                            if (fresh.total_users === undefined || fresh.total_users === null) fresh.total_users = fresh.unique_users ? fresh.unique_users.length : 0;
                            if (fresh.total_downloads === undefined || fresh.total_downloads === null) fresh.total_downloads = 0;
                            if (fresh.active_today === undefined || fresh.active_today === null) fresh.active_today = fresh.active_today_users ? fresh.active_today_users.length : 0;
                            if (!fresh.online_timeout) fresh.online_timeout = 3600000;
                            if (window._applyOnlineTimeoutCfg) window._applyOnlineTimeoutCfg(fresh); // 🔴 管理员离线阈值覆盖
                            if (!fresh.active_date) fresh.active_date = getTodayString();
                            // 确保 unique_users 和 active_today_users 是数组
                            if (!Array.isArray(fresh.unique_users)) fresh.unique_users = [];
                            if (!Array.isArray(fresh.active_today_users)) fresh.active_today_users = [];
                            if (typeof fresh.daily_stats !== 'object' || fresh.daily_stats === null) fresh.daily_stats = {};
                            if (typeof fresh.online_users !== 'object' || fresh.online_users === null) fresh.online_users = {};
                            if (typeof fresh.script_downloads !== 'object' || fresh.script_downloads === null) fresh.script_downloads = {};
                            
                            // 清理 daily_stats 中超过365天的旧数据
                            const allDates = Object.keys(fresh.daily_stats).sort();
                            if (allDates.length > 365) {
                                const datesToRemove = allDates.slice(0, allDates.length - 365);
                                datesToRemove.forEach(d => delete fresh.daily_stats[d]);
                            }
                            
                            // 🔴 全字段最大值合并（含 script_downloads），确保本地数据不丢任何字段
                            mergeCounters(fresh, localData);
                            counterData = fresh;
                            lastGoodCounter = JSON.parse(JSON.stringify(fresh));
                            // 修复异常数据：清理因累加bug导致的超大hourly_visits值
                            if (counterData.daily_stats) {
                                for (const date in counterData.daily_stats) {
                                    const s = counterData.daily_stats[date];
                                    if (s.hourly_visits) {
                                        for (let h = 0; h < 24; h++) {
                                            // 超过10000的肯定是bug数据，重置为0
                                            if (s.hourly_visits[h] > 10000) {
                                                s.hourly_visits[h] = 0;
                                            }
                                        }
                                    }
                                    // 修复异常大的visits
                                    if (s.visits > 100000) s.visits = 0;
                                    if (s.new_users > 100000) s.new_users = 0;
                                }
                            }
                        }
                    } catch (error) {
                        console.warn('获取最新数据失败，使用本地数据:', error);
                        // 如果获取失败但有本地数据，尝试使用本地数据
                        if (localData) {
                            counterData = localData;
                        }
                    }
                }
                
                // 如果没有数据，使用默认值或本地数据
                if (!counterData) {
                    counterData = localData || getDefaultCounter();
                }
                
                const today = getTodayString();
                const deviceId = getDeviceId();
                
                // 确保今日数据存在
                if (!counterData.daily_stats[today]) {
                    counterData.daily_stats[today] = {
                        visits: 0,
                        app_visits: 0,
                        web_visits: 0,
                        downloads: 0,
                        new_users: 0,
                        hourly_visits: new Array(24).fill(0)
                    };
                }
                if (!counterData.daily_stats[today].new_users) counterData.daily_stats[today].new_users = 0;
                if (!counterData.daily_stats[today].hourly_visits) counterData.daily_stats[today].hourly_visits = new Array(24).fill(0);
                if (counterData.daily_stats[today].app_visits === undefined) counterData.daily_stats[today].app_visits = 0;
                if (counterData.daily_stats[today].web_visits === undefined) counterData.daily_stats[today].web_visits = 0;
                // 确保 unique_users 和 active_today_users 数组存在
                if (!counterData.unique_users) counterData.unique_users = [];
                if (!counterData.active_today_users) counterData.active_today_users = [];
                if (!counterData.active_today_app_users) counterData.active_today_app_users = [];
                if (!counterData.active_today_web_users) counterData.active_today_web_users = [];
                if (!counterData.sources) counterData.sources = { app_visits: 0, web_visits: 0 };
                
                // 检查日期是否变化，如果新的一天则清空今日活跃用户
                if (!counterData.active_date || counterData.active_date !== today) {
                    counterData.active_today_users = [];
                    counterData.active_today = 0;
                    counterData.active_today_app_users = [];
                    counterData.active_today_web_users = [];
                    counterData.active_today_app = 0;
                    counterData.active_today_web = 0;
                    counterData.active_date = today;
                }
                
                // 确保在线用户对象存在
                if (!counterData.online_users) counterData.online_users = {};
                // 缩短在线判定窗口到 5 分钟，避免关掉标签页后仍长时间显示"在线"（提升在线数准确性）
                if (!counterData.online_timeout || counterData.online_timeout === 7200000 || counterData.online_timeout === 3600000) counterData.online_timeout = 1800000;
                if (window._applyOnlineTimeoutCfg) window._applyOnlineTimeoutCfg(counterData); // 🔴 管理员离线阈值覆盖（功能开关面板 onlineTimeoutMin）

                // 平台判定（提前到 switch 之前：13640 行写入 online_users 时就要用，case 'visit' 内 13654 行的旧声明会被此行屏蔽并导致 ReferenceError）
                const isApp = !!(window.__TAURI__);

                // 记录用户最后活跃时间 + 昵称/来源（用于计算在线用户 & 管理员"谁在线"日志）
                counterData.online_users[deviceId] = _olRec(_myNick(), isApp ? 'app' : 'web');

                // 清理超过时间窗口的用户
                const now = Date.now();
                const timeout = counterData.online_timeout;
                for (const id in counterData.online_users) {
                    if (!_olAlive(counterData.online_users[id], timeout, now)) {
                        delete counterData.online_users[id];
                    }
                }
                
                // 更新对应统计
                switch (type) {
                    case 'visit':
                        // 🔴 累计总访问按设备记录（避免多端 Math.max 低估）
                        if (!counterData.device_visits) counterData.device_visits = {};
                        ensureDeviceVisitsBaseline(counterData);
                        counterData.device_visits[deviceId] = (counterData.device_visits[deviceId] || 0) + 1;
                        recomputeTotalVisits(counterData);
                        // 🔴 按设备记录各自访问数：每个设备只更新自己的明细，合并时求和，避免 Math.max 把多端访问数压成单端最大值
                        if (!counterData.daily_device_visits) counterData.daily_device_visits = {};
                        if (!counterData.daily_device_visits[today]) counterData.daily_device_visits[today] = {};
                        if (!counterData.daily_device_visits[today][deviceId]) {
                            // 首次：以 0 为基值（不沿用升级前的聚合值，否则每个升级设备都会把"已含他人的累计值"当自身基值，造成雪崩式重复计数）
                            counterData.daily_device_visits[today][deviceId] = { v: 0, a: 0, w: 0 };
                        }
                        const _myEnt = counterData.daily_device_visits[today][deviceId];
                        _myEnt.v++;
                        if (isApp) _myEnt.a++; else _myEnt.w++;
                        // 累计来源口径（用于"累计 APP/网页 访问"，该指标仍取最大值合并，保持历史累计语义）
                        if (!counterData.sources) counterData.sources = { app_visits: 0, web_visits: 0 };
                        if (isApp) counterData.sources.app_visits++; else counterData.sources.web_visits++;
                        // 🔴 直接累计当日 visits 作为真理存储（不再只依赖 daily_device_visits 反算，
                        // 避免该明细在合并/待同步路径丢失时今日访问被算成 0）；随后 recompute 用 Math.max 兜底，跨设备求和仍正确
                        counterData.daily_stats[today].visits = (counterData.daily_stats[today].visits || 0) + 1;
                        if (isApp) counterData.daily_stats[today].app_visits = (counterData.daily_stats[today].app_visits || 0) + 1;
                        else counterData.daily_stats[today].web_visits = (counterData.daily_stats[today].web_visits || 0) + 1;
                        // 由设备明细重算当日访问总数（跨设备求和）
                        recomputeDailyVisitsOn(counterData, today);
                        // 记录访问时段
                        const hour = new Date().getHours();
                        if (!counterData.daily_stats[today].hourly_visits) counterData.daily_stats[today].hourly_visits = new Array(24).fill(0);
                        counterData.daily_stats[today].hourly_visits[hour]++;
                        
                        // 记录新用户（含来源/平台归属）
                        if (!counterData.unique_users.includes(deviceId)) {
                            counterData.unique_users.push(deviceId);
                            counterData.total_users = counterData.unique_users.length;
                            // 记录用户注册平台（持久化归属）
                            if (!counterData.user_sources) counterData.user_sources = {};
                            if (!counterData.user_sources[deviceId]) {
                                counterData.user_sources[deviceId] = isApp ? 'app' : 'web';
                            }
                            // 重新统计平台用户数
                            let appUserCount = 0, webUserCount = 0;
                            for (const uid in counterData.user_sources) {
                                if (counterData.user_sources[uid] === 'app') appUserCount++;
                                else webUserCount++;
                            }
                            counterData.sources.app_users = appUserCount;
                            counterData.sources.web_users = webUserCount;
                            // 总新增数（全来源）
                            counterData.daily_stats[today].new_users = (counterData.daily_stats[today].new_users || 0) + 1;
                            // 按来源区分新增
                            if (isApp) {
                                counterData.daily_stats[today].new_app_users = (counterData.daily_stats[today].new_app_users || 0) + 1;
                                counterData.sources.new_app_users = (counterData.sources.new_app_users || 0) + 1;
                            } else {
                                counterData.daily_stats[today].new_web_users = (counterData.daily_stats[today].new_web_users || 0) + 1;
                                counterData.sources.new_web_users = (counterData.sources.new_web_users || 0) + 1;
                            }
                        }
                        
                        // 记录今日活跃用户
                        if (!counterData.active_today_users.includes(deviceId)) {
                            counterData.active_today_users.push(deviceId);
                            counterData.active_today = counterData.active_today_users.length;
                        }
                        // 记录每日活跃用户数到daily_stats
                        counterData.daily_stats[today].active_users = counterData.active_today_users.length;
                        // 记录活跃用户来源
                        if (isApp) {
                            if (!counterData.active_today_app_users.includes(deviceId)) {
                                counterData.active_today_app_users.push(deviceId);
                                counterData.active_today_app = counterData.active_today_app_users.length;
                            }
                        } else {
                            if (!counterData.active_today_web_users.includes(deviceId)) {
                                counterData.active_today_web_users.push(deviceId);
                                counterData.active_today_web = counterData.active_today_web_users.length;
                            }
                        }
                        break;
                        
                    case 'download':
                        counterData.total_downloads++;
                        counterData.daily_stats[today].downloads++;
                        // 记录单个脚本的下载次数
                        if (scriptName) {
                            if (!counterData.script_downloads) counterData.script_downloads = {};
                            counterData.script_downloads[scriptName] = (counterData.script_downloads[scriptName] || 0) + 1;
                        }
                        break;
                }
                
                counterData.last_updated = getCurrentTimeString();
                
                // 保存到缓存
                saveCounterToCache(counterData);
                
                // 更新底部统计栏显示
                updateStatsBar();
                
                // 🔴 节流写回：避免在频繁刷新时每次都 PATCH 而触发 GitHub 对 gist 的隐藏写频率限流(403 rate limit)。
                // 本地已 saveCounterToCache，这里只标记脏并启动 60s 节流定时器，定时到才真正写一次 Gist。
                // 多次刷新只在 60s 窗口内写一次，大幅降低 gist 写频率（页面刚加载在线标记未就绪也不再卡死写入）。
                scheduleCounterFlush(type);
                
            } catch (error) {
                console.error('更新统计失败:', error);
            }
        }
        
        // 添加到待同步队列
        function addToPendingSync(type) {
            const queue = loadPendingSync();
            queue.push({
                type: type,
                timestamp: new Date().toISOString(),
                date: getTodayString()
            });
            savePendingSync(queue);
        }
        
        // 同步待处理数据到Gist
        async function syncPendingQueue() {
            try {
                if (!isOnline()) {
                    return;
                }
                
                const queue = loadPendingSync();
                if (queue.length === 0) {
                    return;
                }
                
                // 先获取最新的Gist数据
                const remoteData = await fetchCounterFromGist();
                if (!remoteData) {
                    return;
                }
                
                // 确保必要字段存在
                if (!remoteData.unique_users) remoteData.unique_users = [];
                if (!remoteData.active_today_users) remoteData.active_today_users = [];
                if (!remoteData.total_users) remoteData.total_users = remoteData.unique_users.length;
                if (!remoteData.active_today) remoteData.active_today = remoteData.active_today_users.length;
                if (!remoteData.online_users) remoteData.online_users = {};
                if (!remoteData.online_timeout || remoteData.online_timeout === 3600000 || remoteData.online_timeout === 7200000) remoteData.online_timeout = 1800000;
                if (window._applyOnlineTimeoutCfg) window._applyOnlineTimeoutCfg(remoteData); // 🔴 管理员离线阈值覆盖
                if (!remoteData.total_visits) remoteData.total_visits = 0;
                if (!remoteData.total_downloads) remoteData.total_downloads = 0;
                
                // 获取本地缓存，合并用户信息
                const localData = loadCounterFromCache();
                const deviceId = getDeviceId();
                
                // 合并本地 unique_users 到远程
                if (localData && localData.unique_users && Array.isArray(localData.unique_users)) {
                    localData.unique_users.forEach(id => {
                        if (!remoteData.unique_users.includes(id)) {
                            remoteData.unique_users.push(id);
                        }
                    });
                }
                
                // 更新 total_users
                remoteData.total_users = remoteData.unique_users.length;
                
                // 合并待同步的数据
                const today = getTodayString();
                
                // 清理过期的在线用户
                const now = Date.now();
                const timeout = remoteData.online_timeout;
                for (const id in remoteData.online_users) {
                    if (!_olAlive(remoteData.online_users[id], timeout, now)) {
                        delete remoteData.online_users[id];
                    }
                }
                
                // 更新当前设备在线状态（含昵称/来源）
                remoteData.online_users[deviceId] = _olRec(_myNick(), !!(window.__TAURI__) ? 'app' : 'web', _windowHidden);
                
                let hasVisit = false;
                queue.forEach(item => {
                    const syncDate = item.date || today;
                    
                    // 确保日期数据存在
                    if (!remoteData.daily_stats[syncDate]) {
                        remoteData.daily_stats[syncDate] = {
                            visits: 0,
                            downloads: 0
                        };
                    }
                    
                    // 更新统计
                    switch (item.type) {
                        case 'visit':
                            if (!remoteData.device_visits) remoteData.device_visits = {};
                ensureDeviceVisitsBaseline(remoteData);
                remoteData.device_visits[deviceId] = (remoteData.device_visits[deviceId] || 0) + 1;
                recomputeTotalVisits(remoteData);
                            remoteData.daily_stats[syncDate].visits++;
                            // 🔴 修复：待同步队列的访问也必须记录时段分布，否则离线期间的访问不会计入"今日访问时间分布"图
                            if (!remoteData.daily_stats[syncDate].hourly_visits) remoteData.daily_stats[syncDate].hourly_visits = new Array(24).fill(0);
                            const _qh = new Date().getHours();
                            remoteData.daily_stats[syncDate].hourly_visits[_qh]++;
                            hasVisit = true;
                            break;
                        case 'download':
                            remoteData.total_downloads++;
                            remoteData.daily_stats[syncDate].downloads++;
                            break;
                    }
                });
                
                // 如果有访问记录，更新今日活跃用户
                if (hasVisit) {
                    // 检查日期是否变化，如果新的一天则清空今日活跃用户
                    if (!remoteData.active_date || remoteData.active_date !== today) {
                        remoteData.active_today_users = [];
                        remoteData.active_today = 0;
                        remoteData.active_date = today;
                    }
                    
                    // 添加当前设备到今日活跃用户（如果不在）
                    if (!remoteData.active_today_users.includes(deviceId)) {
                        remoteData.active_today_users.push(deviceId);
                        remoteData.active_today = remoteData.active_today_users.length;
                    }
                }
                
                remoteData.last_updated = getCurrentTimeString();
                
                // 同步到Gist
                const success = await syncCounterDataToGist(remoteData);
                
                if (success) {
                    // 清空队列
                    savePendingSync([]);
                    // 更新本地缓存
                    saveCounterToCache(remoteData);
                    counterData = remoteData;
                    // 更新底部统计栏显示
                    updateStatsBar();
                }
                
            } catch (error) {
                console.error('同步待处理队列失败:', error);
            }
        }
         // 清空待同步队列
        function clearPendingSync() {
            localStorage.removeItem('TFJL_Pending_Sync');
        }
        
        // 🔴 计数器写回节流器：60s 内最多写一次 Gist，并感知 gist 写限流(403 rate limit)自动退避。
        // 目的：避免每次刷新都 PATCH 触发 GitHub 隐藏的 gist 写频率限流（导致需求墙/Boss减伤/在线状态等所有写 Gist 全 403）。
        let _counterFlushTimer = null;
        let _counterFlushPending = null;       // 最后一次调用时传入的 type，用于补写
        let _gistWriteBackoffUntil = 0;         // 限流退避截止时间戳(ms)
        let _lastWallPostTs = 0;                // 上一次需求墙发言时间戳(ms)，用于 30s 连续发言节流
        let _counterSelfTimer = null;           // 周期性自调度保活定时器（带随机抖动，错开全网相位）
        // 🔴 计数器写回间隔：采用与 Rust 托盘心跳一致的"递增错峰"策略——
        // 第1次≈1h、第2次≈2h、第3次≈3h、第4次起≈4h，再叠加 _getJitterCap() 的随机抖动(默认0~30分)。
        // 间隔从页面/进程启动时刻起算，登录时间不同的客户端天然错开相位，避免挂机用户批量并发触发限流。
        // 本机 localStorage 设了 tdjl_counterFlushSec(非0) 仍可强制固定间隔(调试用)。
        let _hbTick = 0; // 第几次心跳(进程内累计)
        async function _getCounterFlushInterval() {
            // 优先级：本机调试 tdjl_counterFlushSec > 远程 counterFlushSec(功能开关面板) > 默认递增错峰
            try {
                const local = localStorage.getItem('tdjl_counterFlushSec');
                if (local != null) { const ln = parseInt(local, 10); if (!isNaN(ln) && ln > 0) { return ln * 1000 + _randomJitter(await _getJitterCap()); } }
            } catch (e) {}
            let remoteSec = null;
            try {
                const cfg = await getRoomIndexConfig();
                if (typeof cfg.counterFlushSec === 'number' && cfg.counterFlushSec > 0) remoteSec = cfg.counterFlushSec;
            } catch (e) {}
            if (remoteSec != null) {
                // 用户设的节流间隔(秒) + 随机抖动打散并发，避免全网同时写触发 Gist 限流
                return remoteSec * 1000 + _randomJitter(await _getJitterCap());
            }
            // 兜底：递增错峰(1h/2h/3h/4h + 0~30 分钟随机)
            const baseMin = [60, 120, 180, 240][Math.min(_hbTick, 3)];
            const jitter = Math.floor(Math.random() * 31) * 60000; // 0~30 分钟随机
            return baseMin * 60000 + jitter;
        }
        // 🔴 随机抖动上限：把"整点对齐"的并发写打散到 interval~(interval+jitterCap) 随机相位，
        // 避免全网客户端在同一秒同时 PATCH 触发 Gist 写限流（导致需求墙/Boss减伤/在线状态全 403）。
        // 全网生效(读索引 Gist 的 counterJitterSec,单位秒),默认 600s(10分钟),范围 0~1800。
        // 0 = 关闭抖动(保持原整点对齐行为)。本机 tdjl_counterJitterSec 可强制覆盖(调试用)。仅影响统计/在线类后台写入。
        async function _getJitterCap() {
            let v = 600000; // 默认 10 分钟
            try {
                const local = localStorage.getItem('tdjl_counterJitterSec');
                if (local != null) { const ln = parseInt(local, 10); if (!isNaN(ln) && ln >= 0) { v = ln * 1000; return v; } }
            } catch (e) {}
            try {
                const cfg = await getRoomIndexConfig();
                if (typeof cfg.counterJitterSec === 'number') {
                    const n = cfg.counterJitterSec;
                    if (n >= 0 && n * 1000 <= 1800000) v = n * 1000;
                }
            } catch (e) {}
            return v;
        }
        function _randomJitter(cap) {
            if (!cap || cap <= 0) return 0;
            return Math.floor(Math.random() * cap);
        }

        function scheduleCounterFlush(type) {
            if (type) _counterFlushPending = type;
            if (_counterFlushTimer) return; // 已有定时器在跑，等它触发
            const wait = Math.max(0, _gistWriteBackoffUntil - Date.now());
            // interval 已由 _getCounterFlushInterval 计算（含 counterFlushSec 基础间隔 + 随机抖动打散并发）
            _getCounterFlushInterval().then((interval) => {
                const total = wait || interval;
                console.log('[计数器写回] 安排下次写入(第' + (_hbTick + 1) + '次): 间隔=' + interval + 'ms' + (wait ? ' (含退避' + wait + 'ms)' : ''));
                _counterFlushTimer = setTimeout(async () => {
                    _counterFlushTimer = null;
                    const flushType = _counterFlushPending || 'visit';
                    _counterFlushPending = null;
                    try {
                        await syncCounterToGist();
                        _hbTick = Math.min(_hbTick + 1, 999999); // 成功写回后才推进递增相位
                    } catch (e) {
                        // 限流(rate limit/403)时进入退避：30s 内不再写，数据仍在本地缓存不丢
                        if (e && (e.message || '').includes('rate limit')) {
                            _gistWriteBackoffUntil = Date.now() + 30000;
                            console.warn('⚠️ gist 写限流，30s 后重试(数据已本地缓存):', e.message);
                            return;
                        }
                        addToPendingSync(flushType);
                    }
                    // 🔴 省一次 Gist 写：syncCounterToGist 已把 counter.json（含 online_users 在线状态）合并写回，
                    // 这里不再重复打一次 syncCounterDataToGist，访客刷新写入频率直接减半，缓解 gist 写限流。
                }, total);
            });
        }

        // 🔴 周期性自调度保活：写成功后自动安排下一次统计/在线状态写入（带随机抖动相位），
        // 让在线数持续保活不依赖外部事件，且全网相位随机分散，避免整点对齐并发撞限流。
        // 仅在非隐藏、有 token、计数器已就绪时运行；被退避/节流暂停时由 scheduleCounterFlush 在事件触发时续上。
        async function startCounterSelfKeepalive() {
            if (_counterSelfTimer) return;
            const loop = async () => {
                const interval = await _getCounterFlushInterval(); // 已含递增基础值 + 0~30分随机
                _counterSelfTimer = setTimeout(async () => {
                    _counterSelfTimer = null;
                    if (document.hidden) { return loop(); } // 隐藏页不写，但继续错峰循环
                    if (!getGistToken() || !counterData) { return loop(); }
                    if (_gistWriteBackoffUntil > Date.now()) { return loop(); } // 限流退避中，跳过本轮
                    try { await syncCounterToGist(); _hbTick = Math.min(_hbTick + 1, 999999); }
                    catch (e) { if (e && (e.message || '').includes('rate limit')) _gistWriteBackoffUntil = Date.now() + 30000; }
                    return loop();
                }, interval);
            };
            loop();
        }
        // 页面重新可见/恢复时重启一次保活循环（防止隐藏期定时器被清后不再续）
        document.addEventListener('visibilitychange', () => {
            if (!document.hidden && !_counterSelfTimer) { startCounterSelfKeepalive(); }
        });

        // 同步统计数据到Gist（带成功返回）
        async function syncCounterDataToGist(data) {
            try {
                // 确保 content 始终有值：默认用本地聚合数据，避免 401/合并失败路径下引用未定义变量
                let content = JSON.stringify(data, null, 2);
                const token = getGistToken();
                
                // 铁律：counter Gist 必须归 gyq-svip 且硬编码，禁止从 localStorage/索引自动发现陌生 Gist
                const counterGistId = COUNTER_GIST_ID;
                
                if (counterGistId) {
                    // PATCH之前先读取远程数据，合并后再写入，防止本地小数据覆盖远程大数据
                    let remoteOk = false;
                    try {
                        const remoteResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                ...(token && { 'Authorization': `token ${token}` })
                            }
                        });
                        if (remoteResp.status === 404) {
                            remoteOk = true;
                        } else if (remoteResp.ok) {
                            const remoteJson = await remoteResp.json();
                            if (remoteJson.files && remoteJson.files['counter.json'] && remoteJson.files['counter.json'].content) {
                                try {
                                    const remoteData = JSON.parse(remoteJson.files['counter.json'].content);
                                    if (remoteData) {
                                        remoteOk = true;
                                        // 合并远程数据（全字段最大值，含 script_downloads）到待写数据
                                        mergeCounters(data, remoteData);
                                        lastGoodCounter = JSON.parse(JSON.stringify(data));
                                    }
                                } catch (parseErr) {
                                    console.warn('syncCounterDataToGist 合并远程数据失败:', parseErr);
                                }
                            }
                        }
                    } catch (fetchErr) {
                        console.warn('syncCounterDataToGist 读取远程数据失败:', fetchErr);
                    }

                    // 🔴 修复（s1.0.127）：读不到远程时不再 return 放弃，用本地快照兜底合并后写回，保住本地增量
                    if (!remoteOk) {
                        console.warn('⚠️ 读取远程统计失败（限流/网络），改用本地快照兜底合并后写回');
                        if (lastGoodCounter && typeof lastGoodCounter === 'object') {
                            mergeCounters(data, lastGoodCounter);
                        } else {
                            const localSnap = loadCounterFromCache();
                            if (localSnap) mergeCounters(data, localSnap);
                        }
                    }

                    let content = JSON.stringify(data, null, 2);
                    // 使用 PATCH 更新现有 Gist
                    const response = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                        method: 'PATCH',
                        headers: {
                            'Accept': 'application/vnd.github.v3+json',
                            'Content-Type': 'application/json',
                            'User-Agent': 'TFJL-App/1.0',
                            ...(token && { 'Authorization': `token ${token}` })
                        },
                        body: JSON.stringify({
                            files: {
                                'counter.json': {
                                    content: content
                                }
                            }
                        })
                    });
                    
                    if (response.ok) {
                        return true;
                    }
                    // 如果 PATCH 失败，按状态码处理
                    if (response.status === 404 || response.status === 403) {
                        // 铁律：永远不清除硬编码 COUNTER_GIST_ID 引用，也不自动创建陌生 Gist；明确提示并暂停
                        console.warn('[统计] counter Gist 读写失败 status=' + response.status + '，请检查 Gist 是否存在/Token 权限；暂停同步');
                        return false;
                    } else if (response.status === 401) {
                        // Token 无效/过期/无权限：停止本次同步，避免反复 401 与创建新 Gist 也失败
                        console.warn('[统计] GitHub Token 无效(401)，暂停统计同步，请检查 Token 是否有效/具备 gist 写权限');
                        return false;
                    }
                }
                
                // 如果不存在或 PATCH 失败，创建新的 Gist
                // 【双重检查】创建前先从索引文件确认是否已有counter
                if (!counterGistId && token) {
                    try {
                        const indexUrl = `https://api.github.com/gists/${GIST_ID}`;
                        const checkResp = await fetch(indexUrl, {
                            headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` }
                        });
                        if (checkResp.ok) {
                            const checkData = await checkResp.json();
                            if (checkData.files && checkData.files['room_index.json'] && checkData.files['room_index.json'].content) {
                                let checkIndex;
                                try {
                                    checkIndex = JSON.parse(checkData.files['room_index.json'].content);
                                } catch (parseErr) {
                                    console.warn('syncCounterDataToGist 双重检查：索引文件解析失败:', parseErr);
                                    checkIndex = null;
                                }
                                if (checkIndex && checkIndex['counter']) {
                                    counterGistId = checkIndex['counter'];
                                    localStorage.setItem('counter_gist_id', counterGistId);
                                    // 先尝试从已有Gist获取数据合并，防止数据丢失
                                    try {
                                        const existDataResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                                            headers: {
                                                'Accept': 'application/vnd.github.v3+json',
                                                'Authorization': `token ${token}`
                                            }
                                        });
                                        if (existDataResp.ok) {
                                            const existDataJson = await existDataResp.json();
                                            if (existDataJson.files && existDataJson.files['counter.json'] && existDataJson.files['counter.json'].content) {
                                                try {
                                                    const existingData = JSON.parse(existDataJson.files['counter.json'].content);
                                                    if (existingData) {
                                                        mergeDeviceVisits(data, existingData); ensureDeviceVisitsBaseline(data); recomputeTotalVisits(data);
                                                        data.total_downloads = Math.max(data.total_downloads || 0, existingData.total_downloads || 0);
                                                        if (existingData.unique_users && Array.isArray(existingData.unique_users)) {
                                                            existingData.unique_users.forEach(id => {
                                                                if (!data.unique_users.includes(id)) {
                                                                    data.unique_users.push(id);
                                                                }
                                                            });
                                                        }
                                                        data.total_users = data.unique_users.length;
                                                        if (existingData.daily_stats) {
                                                            for (const date in existingData.daily_stats) {
                                                                if (!data.daily_stats[date]) {
                                                                    data.daily_stats[date] = existingData.daily_stats[date];
                                                                } else {
                                                                    data.daily_stats[date].visits = Math.max(
                                                                        data.daily_stats[date].visits || 0,
                                                                        existingData.daily_stats[date].visits || 0
                                                                    );
                                                                    data.daily_stats[date].downloads = Math.max(
                                                                        data.daily_stats[date].downloads || 0,
                                                                        existingData.daily_stats[date].downloads || 0
                                                                    );
                                                                }
                                                            }
                                                        }
                                                        content = JSON.stringify(data, null, 2);
                                                    }
                                                } catch (mergeErr) {
                                                    console.warn('syncCounterDataToGist 双重检查：合并已有数据失败:', mergeErr);
                                                }
                                            }
                                        }
                                    } catch (fetchErr) {
                                        console.warn('syncCounterDataToGist 双重检查：获取已有Gist数据失败:', fetchErr);
                                    }
                                    // 用已有的Gist去PATCH
                                    const existResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                                        method: 'PATCH',
                                        headers: {
                                            'Accept': 'application/vnd.github.v3+json',
                                            'Content-Type': 'application/json',
                                            'User-Agent': 'TFJL-App/1.0',
                                            'Authorization': `token ${token}`
                                        },
                                        body: JSON.stringify({ files: { 'counter.json': { content: content } } })
                                    });
                                    if (existResp.ok) return true;
                                    console.warn('⚠️ syncCounterDataToGist 双重检查PATCH也失败，继续创建新Gist');
                                }
                            }
                        }
                    } catch (e) {
                        console.warn('syncCounterDataToGist 双重检查失败，继续创建:', e);
                    }
                }
                
                const createResponse = await fetch('https://api.github.com/gists', {
                    method: 'POST',
                    headers: {
                        'Accept': 'application/vnd.github.v3+json',
                        'Content-Type': 'application/json',
                        'User-Agent': 'TFJL-App/1.0',
                        ...(token && { 'Authorization': `token ${token}` })
                    },
                    body: JSON.stringify({
                        description: '统计数据',
                        public: false,
                        files: {
                            'counter.json': {
                                content: content
                            }
                        }
                    })
                });
                
                if (createResponse.ok) {
                    const responseData = await createResponse.json();
                    // 保存 GIST_ID 到 localStorage
                    localStorage.setItem('counter_gist_id', responseData.id);
                    // 更新索引文件（含冲突检测）
                    const conflictResult = await updateRoomIndex('counter', responseData.id);
                    if (conflictResult && conflictResult.conflict && conflictResult.existingGistId) {
                        try {
                            await fetch(`https://api.github.com/gists/${responseData.id}`, {
                                method: 'DELETE',
                                headers: { 'Authorization': `token ${token}` }
                            });
                        } catch (delErr) { console.warn('删除重复counter Gist失败:', delErr); }
                        localStorage.setItem('counter_gist_id', conflictResult.existingGistId);
                        // PATCH到已有Gist
                        await fetch(`https://api.github.com/gists/${conflictResult.existingGistId}`, {
                            method: 'PATCH',
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                'Content-Type': 'application/json',
                                'User-Agent': 'TFJL-App/1.0',
                                'Authorization': `token ${token}`
                            },
                            body: JSON.stringify({ files: { 'counter.json': { content: content } } })
                        });
                    }
                    return true;
                }
                
                const errorText = await createResponse.text();
                console.error('❌ Gist同步失败:', createResponse.status, errorText);
                return false;
            } catch (error) {
                console.error('❌ 同步统计到Gist失败:', error);
                console.error('错误详情:', error.message);
                return false;
            }
        }
        
        // 同步统计数据到Gist（异步）
        async function syncCounterToGist() {
            try {
                if (!counterData) {
                    console.warn('⚠️ 没有统计数据可同步');
                    return;
                }

                const token = getGistToken();

                // 强制只用硬编码的 COUNTER_GIST_ID（铁律：counter Gist 必须归 gyq-svip 且硬编码，禁止从 localStorage/索引自动发现陌生 Gist）
                const counterGistId = COUNTER_GIST_ID;
                
                if (counterGistId) {
                    // PATCH之前先读取远程数据，合并后再写入，防止本地小数据覆盖远程大数据
                    let remoteOk = false;
                    try {
                        const remoteResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                ...(token && { 'Authorization': `token ${token}` })
                            }
                        });
                        if (remoteResp.status === 404) {
                            // Gist 尚不存在（首次创建场景）：视为远程为空，允许后续走创建流程
                            remoteOk = true;
                        } else if (remoteResp.ok) {
                            const remoteJson = await remoteResp.json();
                            if (remoteJson.files && remoteJson.files['counter.json'] && remoteJson.files['counter.json'].content) {
                                try {
                                    const remoteData = JSON.parse(remoteJson.files['counter.json'].content);
                                        if (remoteData) {
                                            remoteOk = true;
                                            // 合并远程数据到本地（全字段最大值，含 script_downloads，防止数据回退/丢失）
                                            mergeCounters(counterData, remoteData);
                                            // 🔴 合并在线用户（按设备取最新时间戳并集），避免同步时互相覆盖导致在线数漏算
                                            mergeOnlineUsers(counterData, remoteData);
                                            lastGoodCounter = JSON.parse(JSON.stringify(counterData));
                                        }
                                } catch (parseErr) {
                                    console.warn('合并远程数据失败，使用本地数据:', parseErr);
                                }
                            }
                        }
                    } catch (fetchErr) {
                        console.warn('读取远程数据失败（网络/被墙），本次不覆盖远程统计:', fetchErr);
                    }

                    // 🔴 修复（s1.0.127）：读不到远程（限流403/无token/网络错误）时，旧逻辑直接 return 放弃写入，
                    // 导致本地累加的访问增量永远写不回 Gist，远程永久卡在旧值（如 total_visits 停在 3237）。
                    // 改为：读失败时用"上次成功快照 lastGoodCounter"或"本地缓存"兜底合并，仍尝试 PATCH 写回，
                    // 写操作限额比读宽松，至少该试一次；绝不因读失败而丢弃本地增量。
                    if (!remoteOk) {
                        console.warn('⚠️ 读取远程统计失败（限流/网络），改用本地快照兜底合并后写回');
                        // 用上次成功合并的快照做基准（保底不会比之前小），再叠加本机已累加的增量
                        if (lastGoodCounter && typeof lastGoodCounter === 'object') {
                            mergeCounters(counterData, lastGoodCounter);
                        } else {
                            const localSnap = loadCounterFromCache();
                            if (localSnap) mergeCounters(counterData, localSnap);
                        }
                    }

                    // 🔴 2026-08-29 内存修复：原先此处 JSON.stringify 整个 device_visits（可数 KB~数十 KB）写日志，
                    // 每 5 分钟一次，长期挂机日志数组会常驻大量巨长字符串。改为只打印摘要。
                    try {
                        const dvCount = counterData.device_visits ? Object.keys(counterData.device_visits).length : 0;
                        console.log('[TFJL app-core] 准备写回统计 Gist · device_visits 设备数=' + dvCount + ' · total_visits=' + counterData.total_visits + ' · remoteOk=' + remoteOk);
                    } catch (e) {
                        console.log('[TFJL app-core] 准备写回统计 Gist · total_visits=' + counterData.total_visits + ' · remoteOk=' + remoteOk);
                    }
                    let content = JSON.stringify(counterData, null, 2);
                    try {
                        // 使用 PATCH 更新现有 Gist
                        const patchResponse = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                            method: 'PATCH',
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                'Content-Type': 'application/json',
                                'User-Agent': 'TFJL-App/1.0',
                                ...(token && { 'Authorization': `token ${token}` })
                            },
                            body: JSON.stringify({
                                files: {
                                    'counter.json': {
                                        content: content
                                    }
                                }
                            })
                        });
                        
                        if (patchResponse.ok) {
                            saveCounterToCache(counterData);
                            clearPendingSync();
                            lastGoodCounter = JSON.parse(JSON.stringify(counterData));
                            updateStatsBar();
                            return;
                        }
                        
                        // 如果 PATCH 失败（404 或 403），清除缓存重新创建
                        if (patchResponse.status === 404 || patchResponse.status === 403) {
                            localStorage.removeItem('counter_gist_id');
                            counterGistId = null;
                        } else {
                            // 其它错误（含 403 限流写）：进待同步队列稍后重试，但不丢弃本地增量
                            console.warn('⚠️ PATCH 写入未成功(' + patchResponse.status + ')，转入待同步队列重试');
                            addToPendingSync('counter');
                        }
                    } catch (e) {
                        console.warn('PATCH 异常，转入待同步队列重试:', e);
                        addToPendingSync('counter');
                    }
                }
                
                // 如果不存在或 PATCH 失败，使用 POST 创建新的 Gist
                // 【双重检查】创建前先从索引文件确认是否已有counter
                if (!counterGistId && token) {
                    try {
                        const indexUrl = `https://api.github.com/gists/${GIST_ID}`;
                        const checkResp = await fetch(indexUrl, {
                            headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` }
                        });
                        if (checkResp.ok) {
                            const checkData = await checkResp.json();
                            if (checkData.files && checkData.files['room_index.json'] && checkData.files['room_index.json'].content) {
                                let checkIndex;
                                try {
                                    checkIndex = JSON.parse(checkData.files['room_index.json'].content);
                                } catch (parseErr) {
                                    console.warn('counter双重检查：索引文件解析失败:', parseErr);
                                    checkIndex = null;
                                }
                                if (checkIndex && checkIndex['counter']) {
                                    counterGistId = checkIndex['counter'];
                                    localStorage.setItem('counter_gist_id', counterGistId);
                                    // 先尝试从已有Gist获取数据合并，防止数据丢失
                                    try {
                                        const existDataResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                                            headers: {
                                                'Accept': 'application/vnd.github.v3+json',
                                                'Authorization': `token ${token}`
                                            }
                                        });
                                        if (existDataResp.ok) {
                                            const existDataJson = await existDataResp.json();
                                            if (existDataJson.files && existDataJson.files['counter.json'] && existDataJson.files['counter.json'].content) {
                                                try {
                                                    const existingData = JSON.parse(existDataJson.files['counter.json'].content);
                                                    // 合并已有数据到当前数据（取最大值，防止数据回退）
                                                    if (existingData) {
                                                        mergeDeviceVisits(counterData, existingData); ensureDeviceVisitsBaseline(counterData); recomputeTotalVisits(counterData);
                                                        counterData.total_downloads = Math.max(counterData.total_downloads || 0, existingData.total_downloads || 0);
                                                        if (existingData.unique_users && Array.isArray(existingData.unique_users)) {
                                                            existingData.unique_users.forEach(id => {
                                                                if (!counterData.unique_users.includes(id)) {
                                                                    counterData.unique_users.push(id);
                                                                }
                                                            });
                                                        }
                                                        counterData.total_users = counterData.unique_users.length;
                                                        if (existingData.daily_stats) {
                                                            for (const date in existingData.daily_stats) {
                                                                if (!counterData.daily_stats[date]) {
                                                                    counterData.daily_stats[date] = existingData.daily_stats[date];
                                                                } else {
                                                                    counterData.daily_stats[date].visits = Math.max(
                                                                        counterData.daily_stats[date].visits || 0,
                                                                        existingData.daily_stats[date].visits || 0
                                                                    );
                                                                    counterData.daily_stats[date].downloads = Math.max(
                                                                        counterData.daily_stats[date].downloads || 0,
                                                                        existingData.daily_stats[date].downloads || 0
                                                                    );
                                                                }
                                                            }
                                                        }
                                                        content = JSON.stringify(counterData, null, 2);
                                                    }
                                                } catch (mergeErr) {
                                                    console.warn('counter双重检查：合并已有数据失败:', mergeErr);
                                                }
                                            }
                                        }
                                    } catch (fetchErr) {
                                        console.warn('counter双重检查：获取已有Gist数据失败:', fetchErr);
                                    }
                                    // 用已有的Gist去PATCH
                                    const existResp = await fetch(`https://api.github.com/gists/${counterGistId}`, {
                                        method: 'PATCH',
                                        headers: {
                                            'Accept': 'application/vnd.github.v3+json',
                                            'Content-Type': 'application/json',
                                            'User-Agent': 'TFJL-App/1.0',
                                            'Authorization': `token ${token}`
                                        },
                                        body: JSON.stringify({ files: { 'counter.json': { content: content } } })
                                    });
                                    if (existResp.ok) {
                                        saveCounterToCache(counterData);
                                        clearPendingSync();
                                        updateStatsBar();
                                        return;
                                    }
                                    console.warn('⚠️ 双重检查PATCH也失败，继续创建新Gist');
                                }
                            }
                        }
                    } catch (e) {
                        console.warn('counter双重检查失败，继续创建:', e);
                    }
                }
                
                const createResponse = await fetch('https://api.github.com/gists', {
                    method: 'POST',
                    headers: {
                        'Accept': 'application/vnd.github.v3+json',
                        'Content-Type': 'application/json',
                        'User-Agent': 'TFJL-App/1.0',
                        ...(token && { 'Authorization': `token ${token}` })
                    },
                    body: JSON.stringify({
                        description: '统计数据',
                        public: false,
                        files: {
                            'counter.json': {
                                content: content
                            }
                        }
                    })
                });
                
                if (createResponse.ok) {
                    const data = await createResponse.json();
                    saveCounterToCache(counterData);
                    clearPendingSync();
                    updateStatsBar();
                    // 保存 GIST_ID 到 localStorage
                    localStorage.setItem('counter_gist_id', data.id);
                    // 更新索引文件（含冲突检测）
                    const conflictResult = await updateRoomIndex('counter', data.id);
                    if (conflictResult && conflictResult.conflict && conflictResult.existingGistId) {
                        try {
                            await fetch(`https://api.github.com/gists/${data.id}`, {
                                method: 'DELETE',
                                headers: { 'Authorization': `token ${token}` }
                            });
                        } catch (delErr) { console.warn('删除重复counter Gist失败:', delErr); }
                        localStorage.setItem('counter_gist_id', conflictResult.existingGistId);
                        await fetch(`https://api.github.com/gists/${conflictResult.existingGistId}`, {
                            method: 'PATCH',
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                'Content-Type': 'application/json',
                                'User-Agent': 'TFJL-App/1.0',
                                'Authorization': `token ${token}`
                            },
                            body: JSON.stringify({ files: { 'counter.json': { content: content } } })
                        });
                    }
                    return;
                }
                
                // 创建失败
                const errorText = await createResponse.text();
                console.warn('⚠️ 创建统计数据失败:', createResponse.status, errorText);
                addToPendingSync(counterData);
            } catch (error) {
                console.warn('⚠️ 同步统计数据异常:', error.message);
                if (counterData) {
                    addToPendingSync(counterData);
                }
            }
        }
        
        // 在线保活：刷新本机在线时间戳并同步到 Gist，同时由 syncCounterToGist 合并其他设备在线状态
        // （解决"在线数量不变/不准"：之前只在加载时上报一次，无心跳；且多设备同步互相覆盖）
        async function refreshOnlinePresence() {
            try {
                if (!counterData) return;
                if (!counterData.online_users) counterData.online_users = {};
                const deviceId = getDeviceId();
                const isApp = !!(window.__TAURI__);
                // s1.0.107：隐藏到托盘也照常上报心跳（bg=后台运行标记），不再把自己踢下线
                counterData.online_users[deviceId] = _olRec(_myNick(), isApp ? 'app' : 'web', _windowHidden);
                // 清过期并记入离线历史
                pruneExpiredOnline(true);
                cleanupOfflineHistory();
                if (isOnline()) await syncCounterToGist();   // 写回自身 + 合并远程在线
                updateStatsBar();
                if (typeof updateFloatConsole === 'function') { try { updateFloatConsole(); } catch (e) {} }
            } catch (e) { console.warn('在线保活失败:', e); }
        }

        // 仅本地轻量保活（不联网）：保持本机"在线"并刷新显示，避免隔 60s 才更新的卡顿感
        function keepSelfOnlineLocal() {
            try {
                if (!counterData) return;
                if (!counterData.online_users) counterData.online_users = {};
                const isApp = !!(window.__TAURI__);
                // s1.0.107：托盘挂机同样保活，只有真正超时才由 pruneExpiredOnline 判离线
                counterData.online_users[getDeviceId()] = _olRec(_myNick(), isApp ? 'app' : 'web', _windowHidden);
                // 仅清过期（记录离线统一由联网的 refreshOnlinePresence 负责，避免本地重复写）
                pruneExpiredOnline(false);
                updateStatsBar();
            } catch (e) {}
        }

        // 监听网络状态变化
        function setupNetworkListener() {
            // 网络恢复时自动同步
            window.addEventListener('online', () => {
                setTimeout(() => {
                    syncPendingQueue();
                    // 重新获取最新数据
                    refreshCounterData();
                }, 3000);
            });
            
            // 页面加载时检查并同步
            setTimeout(() => {
                if (isOnline()) {
                    syncPendingQueue();
                }
            }, 5000);
            
            // 定期刷新数据（每30分钟）：拉取最新统计 + 在线保活（同步自身在线并合并他人在线）
            // s1.0.112：心跳从 60s 降到 30min，大幅减少 GitHub API 调用（限流主因之一）；
            // 在线数准确性不再强求（数据分析另有记录），故同步把 online_timeout 放宽到 30min 保持一致。
            setInterval(() => {
                if (isOnline()) {
                    refreshOnlinePresence();
                    refreshCounterData();
                }
            }, 1800000);
            // 本地轻量保活（每30分钟）：仅刷新本机在线时间戳与显示，不联网
            setInterval(() => { keepSelfOnlineLocal(); }, 1800000);
            // 桌面端：隐藏到托盘即自身下线（网页端切标签不视为下线）
            setupWindowHiddenDetection();
        }
        
        // 刷新统计数据（从Gist获取最新）
        async function refreshCounterData() {
            try {
                const fresh = await fetchCounterFromGist();
                if (fresh) {
                    // s1.0.108：绝不能裸覆盖！每 60 秒轮询若直接 `counterData = fresh`，
                    // 会把本机刚记录的"今日访问/下载增量"冲掉（s1.0.107 只补了在线，漏了访问增量）。
                    // 必须先合并本地缓存（含本机会话已记录的今日时段/访问数），再覆盖。
                    const localData = loadCounterFromCache();
                    if (localData) mergeCounters(fresh, localData);
                    counterData = fresh;
                    // s1.0.107：远程数据会整体覆盖本地，若 Gist 有 CDN 缓存/尚未收到本机心跳，
                    // 自己就会从在线名单消失，出现"0 人在线"。覆盖后立刻把自己补回来。
                    keepSelfOnlineLocal();
                    saveCounterToCache(counterData);
                    updateStatsBar();
                    // s1.0.108：刷新成功说明网络/限流恢复，趁此把之前失败的待同步增量（含今日访问）补写 Gist
                    if (isOnline()) syncPendingQueue();
                }
            } catch (error) {
                console.warn('刷新统计数据失败:', error);
            }
        }
        
        // 更新底部统计栏显示
        function updateStatsBar() {
            if (!counterData) return;
            
            const runtimeEl = document.getElementById('statRuntime');
            const visitEl = document.getElementById('statVisits');
            const usersEl = document.getElementById('statUsers');
            const onlineEl = document.getElementById('statOnline');
            const downloadEl = document.getElementById('statDownloads');

            // 计算在线用户数（清理过期用户后）
            let onlineCount = 0;
            if (counterData.online_users) {
                const now = Date.now();
                const timeout = counterData.online_timeout || 1800000;
                for (const id in counterData.online_users) {
                    if (_olAlive(counterData.online_users[id], timeout, now)) {
                        onlineCount++;
                    }
                }
            }

            if (runtimeEl) runtimeEl.textContent = calculateRuntime();
            if (visitEl) visitEl.textContent = counterData.total_visits || 0;
            if (usersEl) usersEl.textContent = counterData.total_users || 0;
            if (onlineEl) onlineEl.textContent = onlineCount;
            if (downloadEl) downloadEl.textContent = counterData.total_downloads || 0;
        }
        
        // 计算网站运行时长（从2026年5月20日开始）
        function calculateRuntime() {
            const startDate = new Date('2026-05-20T00:00:00');
            const now = new Date();
            const diff = now - startDate;
            
            if (diff < 0) return '未开始';
            
            const totalMinutes = Math.floor(diff / (1000 * 60));
            const totalHours = Math.floor(totalMinutes / 60);
            const totalDays = Math.floor(totalHours / 24);
            
            const years = Math.floor(totalDays / 365);
            const remainingDays = totalDays % 365;
            const months = Math.floor(remainingDays / 30);
            const days = remainingDays % 30;
            const hours = totalHours % 24;
            
            if (years > 0) {
                return `${years}年${months}月${days}天`;
            } else if (months > 0) {
                return `${months}月${days}天${hours}时`;
            } else if (days > 0) {
                return `${days}天${hours}时`;
            } else {
                return `${hours}时${totalMinutes % 60}分`;
            }
        } 
        
        // ==================== 消息墙功能 ====================
        let wallMessages = [];
        let messageWallOpen = false;
        // 🔴 已读基准改用「消息内容指纹集合」(time_author_content)，而非绝对时间戳——
        // 消息墙跨设备共享(Gist)，各机本地时钟不一致会导致"未来消息"误判未读/红点。
        // 指纹方案与合并去重一致，彻底规避跨设备时钟问题；且自动升级强刷不重置(见 forceRefreshLatest)。
        let wallReadKeys = new Set();
        try { const arr = JSON.parse(localStorage.getItem('TFJL_WallReadKeys') || '[]'); if (Array.isArray(arr)) wallReadKeys = new Set(arr); } catch (e) {}
        function _wallMsgKey(m) { return (m.time || 0) + '_' + (m.author || '') + '_' + ((m.content || '').substring(0, 30)); }
        let messageScrollInterval = null;
        let messageFetchInterval = null;
        let msgRefreshCountdown = 30;
        let msgCountdownInterval = null;
        let pendingScriptFile = null;
        let wallScrollUserPaused = false;   // 用户主动关闭自动滚动（本地记忆，区别于鼠标移入临时暂停）
        const MESSAGE_REFRESH_INTERVAL = 30000;
        const MAX_MESSAGES = 5000;
        // ============ 需求墙消息防丢：本地 IndexedDB 兜底 + 云端备份 Gist ============
        const WALL_DB_NAME = 'TFJLWallDB';
        const WALL_STORE = 'wallMessages';
        function openWallDB() {
            return new Promise((resolve) => {
                try {
                    const req = indexedDB.open(WALL_DB_NAME, 1);
                    req.onupgradeneeded = () => { try { req.result.createObjectStore(WALL_STORE); } catch (e) {} };
                    req.onsuccess = () => resolve(req.result);
                    req.onerror = () => resolve(null);
                } catch (e) { resolve(null); }
            });
        }
        async function loadWallFromDB() {
            const db = await openWallDB();
            if (!db) return null;
            return await new Promise((resolve) => {
                try {
                    const tx = db.transaction(WALL_STORE, 'readonly');
                    const r = tx.objectStore(WALL_STORE).get('messages');
                    r.onsuccess = () => resolve(r.result || null);
                    r.onerror = () => resolve(null);
                } catch (e) { resolve(null); }
            });
        }
        async function saveWallToDB(arr) {
            const db = await openWallDB();
            if (!db) return;
            await new Promise((resolve) => {
                try {
                    const tx = db.transaction(WALL_STORE, 'readwrite');
                    tx.objectStore(WALL_STORE).put(arr, 'messages');
                    tx.oncomplete = () => resolve();
                    tx.onerror = () => resolve();
                } catch (e) { resolve(); }
            });
        }
        // 云端备份 Gist（与主 Gist 独立，主 Gist 被删时重建先从此恢复）。真实固定 id 见 room_index.json 的 backup 字段（s1.0.113 重建：原 36a871e7 已消失）
        const MESSAGES_BACKUP_GIST_ID = 'f13f1f2a054e96bdcaaa418264b92174';
        // 过期统计（判定与 renderMessages 过滤器一致）：仅 expireDays>0 且已到期的算过期——
        // 过期只是前端不显示，还原/导入仍照常写回数据；提示里注明条数，避免"还原了却看不见"的误判
        function wallCountExpiredMsgs(arr) {
            const now = Date.now();
            let n = 0;
            (arr || []).forEach(m => { if (m && m.expireDays > 0 && (now - (m.time || 0)) >= m.expireDays * 24 * 3600 * 1000) n++; });
            return n;
        }

        async function backupWallMessages(arr) {
            try {
                const token = getGistToken();
                if (!token) return;
                const content = JSON.stringify({ messages: arr }, null, 2);
                const headers = { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': 'token ' + token };
                let backupId = localStorage.getItem('messages_backup_gist_id') || MESSAGES_BACKUP_GIST_ID;
                if (backupId) {
                    const resp = await fetch('https://api.github.com/gists/' + backupId, {
                        method: 'PATCH', headers, body: JSON.stringify({ files: { 'messages.json': { content } } })
                    });
                    if (resp.ok) { console.log('[消息备份] 已备份', arr.length, '条'); return; }
                    if (resp.status !== 404) return;
                }
                const c = await fetch('https://api.github.com/gists', {
                    method: 'POST', headers, body: JSON.stringify({ description: 'TFJL 需求墙消息备份(自动)', public: true, files: { 'messages.json': { content } } })
                });
                if (c.ok) { const d = await c.json(); localStorage.setItem('messages_backup_gist_id', d.id); console.log('[消息备份] 创建备份Gist:', d.id); }
            } catch (e) { console.warn('[消息备份] 失败(不影响主保存):', e); }
        }
        async function restoreWallFromBackup() {
            try {
                // 目录式指针：优先从索引 room_index.json 的 backup 字段取备用 Gist（真实数据源，长期保活，无需 token 即可读）
                let backupId = localStorage.getItem('messages_backup_gist_id') || MESSAGES_BACKUP_GIST_ID;
                try {
                    const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json' } });
                    if (idxResp.ok) {
                        const idxData = await idxResp.json();
                        const ri = idxData.files && idxData.files['room_index.json'];
                        if (ri && ri.content) {
                            const idx = JSON.parse(ri.content);
                            if (idx.backup) { backupId = idx.backup; localStorage.setItem('messages_backup_gist_id', backupId); }
                        }
                    }
                } catch (e) {}
                if (!backupId) return null;
                const resp = await fetch('https://api.github.com/gists/' + backupId);
                if (!resp.ok) return null;
                const d = await resp.json();
                const f = d.files && d.files['messages.json'];
                if (!f || !f.content) return null;
                const parsed = JSON.parse(f.content);
                return parsed.messages || null;
            } catch (e) { return null; }
        }

        // 管理员一键还原：把备用 Gist（目录式 backup 字段）的消息合并写回当前需求墙指向的主 Gist
        async function adminRestoreFromBackup() {
            const token = getGistToken();
            if (!token) { alert('离线版暂不支持还原，请检查网络连接'); return; }
            if (!confirm('确认从备用 Gist 一键还原需求墙？\n\n将把备用 Gist 的消息合并到当前需求墙指向的主 Gist（不会删除主 Gist 中已有的新消息）。')) return;
            try {
                showToast('⏳ 正在从备用 Gist 还原...');
                // 1) 取备用 Gist ID（目录式优先：索引 backup 字段 → 常量）
                let backupId = localStorage.getItem('messages_backup_gist_id') || MESSAGES_BACKUP_GIST_ID;
                try {
                    const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json' } });
                    if (idxResp.ok) {
                        const idxData = await idxResp.json();
                        const ri = idxData.files && idxData.files['room_index.json'];
                        if (ri && ri.content) { const idx = JSON.parse(ri.content); if (idx.backup) backupId = idx.backup; }
                    }
                } catch (e) {}
                if (!backupId) { showToast('❌ 未找到备用 Gist'); return; }
                // 2) 读备用内容（public 免 token）
                const bkResp = await fetch('https://api.github.com/gists/' + backupId);
                if (!bkResp.ok) { showToast('❌ 备用 Gist 读取失败(' + bkResp.status + ')'); return; }
                const bkData = await bkResp.json();
                const bkContent = bkData.files && bkData.files['messages.json'] && bkData.files['messages.json'].content;
                if (!bkContent) { showToast('❌ 备用 Gist 无消息'); return; }
                const bkMsgs = (JSON.parse(bkContent).messages) || [];
                // 3) 解析当前主 Gist ID（索引 messages 优先 → 硬编码兜底）
                const gistDeleted = localStorage.getItem('messages_gist_deleted') === 'true';
                let mainId = (!gistDeleted && MESSAGES_GIST_ID) ? MESSAGES_GIST_ID : (localStorage.getItem('messages_gist_id') || '');
                if (!gistDeleted) {
                    try {
                        const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json' } });
                        if (idxResp.ok) {
                            const idxData = await idxResp.json();
                            const ri = idxData.files && idxData.files['room_index.json'];
                            if (ri && ri.content) { const idx = JSON.parse(ri.content); if (idx.messages) { mainId = idx.messages; localStorage.setItem('messages_gist_id', mainId); } }
                        }
                    } catch (e) {}
                }
                if (!mainId) { showToast('❌ 未确定主 Gist'); return; }
                // 4) 合并：主现有 wallMessages + 备用，去重（保留主里的新消息）
                const merged = (wallMessages || []).slice();
                const seen = new Set(merged.map(m => m.time + '_' + m.author + '_' + (m.content || '').substring(0, 30)));
                let added = 0;
                bkMsgs.forEach(m => { const k = m.time + '_' + m.author + '_' + (m.content || '').substring(0, 30); if (!seen.has(k)) { merged.push(m); seen.add(k); added++; } });
                merged.sort((a, b) => b.time - a.time);
                const finalMsgs = merged.slice(0, MAX_MESSAGES);
                // 5) 写回主 Gist（用户 token 可写主 Gist）
                const resp = await fetch('https://api.github.com/gists/' + mainId, {
                    method: 'PATCH',
                    headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': 'token ' + token },
                    body: JSON.stringify({ files: { 'messages.json': { content: JSON.stringify({ messages: finalMsgs }, null, 2) } } })
                });
                if (!resp.ok) { showToast('❌ 还原写入失败(' + resp.status + ')'); return; }
                wallMessages = finalMsgs;
                localStorage.removeItem('messages_gist_deleted');
                localStorage.removeItem('messages_gist_id');
                await saveWallToDB(finalMsgs);
                await fetchMessages();
                const expN = wallCountExpiredMsgs(finalMsgs);
                showToast('✅ 已还原：合并 ' + added + ' 条备用消息，共 ' + finalMsgs.length + ' 条' + (expN ? '（其中 ' + expN + ' 条已过期不显示）' : ''));
            } catch (e) { showToast('❌ 还原出错：' + (e.message || e)); }
        }

        // ==================== 需求墙数据备份 / 还原（通用模板，移植自拍卖系统）====================
                // ==================== Boss减伤参考（管理员可编辑，全网共享 Gist）====================

        const BOSS_RED_GIST_ID = '3d9b72b00cddf7e15ba5da5e82c4c8e9';

        const BOSS_RED_FILE = 'boss_reduction.json';

        const BOSS_RED_DESC = 'TFJL Boss减伤参考数据（共享·全网可见）';

        const BOSS_RED_SECTIONS = ['寒冰', '暗月', '漩涡', '深海'];

        const BOSS_RED_WAVE_MAX = { '寒冰': 210, '暗月': 210, '漩涡': 210, '深海': 210 };

        let bossRedCurrent = { '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} };

        let bossRedActiveSection = '寒冰';

        let bossRedActiveBoss = null;

        let bossRedAdminSection = '寒冰';

        let bossRedAdminBoss = null;



        async function bossRedGetGistId() { return BOSS_RED_GIST_ID; }



        async function bossRedLoad() {

            try {

                const token = getGistToken();

                const id = BOSS_RED_GIST_ID;

                const content = await wallReadGistFile(id, BOSS_RED_FILE, token);

                if (!content) return { '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} };

                const d = JSON.parse(content);

                return { '寒冰': d['寒冰'] || {}, '暗月': d['暗月'] || {}, '漩涡': d['漩涡'] || {}, '深海': d['深海'] || {} };

            } catch (e) { return { '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} }; }

        }



        async function bossRedSave(data) {

            const token = getGistToken();

            if (!token) throw new Error('无Token');

            const id = BOSS_RED_GIST_ID;

            const r = await fetch(`https://api.github.com/gists/${id}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: { [BOSS_RED_FILE]: { content: JSON.stringify(data, null, 2) } } }) });

            if (!r.ok) throw new Error('保存失败');

        }



        async function renderBossRed() {

            const cont = document.getElementById('calcBossContainer');

            if (!cont) return;

            try { bossRedCurrent = await bossRedLoad(); } catch (e) { bossRedCurrent = { '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} }; }

            if (!BOSS_RED_SECTIONS.includes(bossRedActiveSection)) bossRedActiveSection = '寒冰';

            let html = `<div style="margin-bottom:12px;"><button onclick="switchCalcTopTab('new')" style="background:rgba(79,195,247,0.14);color:#4fc3f7;border:1px solid rgba(79,195,247,0.35);padding:7px 12px;border-radius:8px;cursor:pointer;font-weight:600;font-size:0.82rem;">← 返回计算器</button></div>`;
            html += `<div style="display:flex;gap:4px;margin-bottom:12px;">` + BOSS_RED_SECTIONS.map(s => `<button onclick="bossRedShowSection('${s}')" id="bossRedSec_${s}" style="flex:1;padding:7px;border:none;border-radius:6px;cursor:pointer;font-size:0.8rem;${bossRedActiveSection === s ? 'background:linear-gradient(135deg,#4caf50,#2e7d32);color:white;' : 'background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.7);'}">${s}</button>`).join('') + `</div>`;

            html += `<div id="bossRedSectionBody"></div>`;

            cont.innerHTML = html;

            bossRedShowSection(bossRedActiveSection);

        }



        function bossRedShowSection(s) {

            bossRedActiveSection = s;

            BOSS_RED_SECTIONS.forEach(x => { const b = document.getElementById('bossRedSec_' + x); if (b) { b.style.background = x === s ? 'linear-gradient(135deg,#4caf50,#2e7d32)' : 'rgba(255,255,255,0.1)'; b.style.color = x === s ? 'white' : 'rgba(255,255,255,0.7)'; } });

            const body = document.getElementById('bossRedSectionBody');

            if (!body) return;

            if (s !== '深海') {

                body.innerHTML = bossRedGridHtml(s, bossRedCurrent[s] || {}, null);

            } else {

                const bosses = Object.keys(bossRedCurrent['深海'] || {});

                if (!bosses.length) { body.innerHTML = '<div style="color:rgba(255,255,255,0.4);font-size:0.82rem;text-align:center;padding:20px;">暂无Boss，请在管理员菜单 → 🛡️ Boss减伤管理 中添加</div>'; return; }

                if (!bossRedActiveBoss || !bossRedCurrent['深海'][bossRedActiveBoss]) bossRedActiveBoss = bosses[0];

                let h = `<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:10px;">` + bosses.map(b => `<button onclick="bossRedShowBoss('${b.replace(/'/g, "\\'")}')" style="padding:5px 10px;border:none;border-radius:6px;cursor:pointer;font-size:0.78rem;${bossRedActiveBoss === b ? 'background:linear-gradient(135deg,#4caf50,#2e7d32);color:#fff;' : 'background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.7);'}">${b}</button>`).join('') + `</div>`;

                h += bossRedGridHtml('深海', bossRedCurrent['深海'][bossRedActiveBoss] || {}, bossRedActiveBoss);

                body.innerHTML = h;

            }

        }



        function bossRedShowBoss(b) { bossRedActiveBoss = b; bossRedShowSection('深海'); }



        function bossRedGridHtml(section, dataMap, boss) {

            const maxBase = BOSS_RED_WAVE_MAX[section] || 210;

            let maxWave = maxBase;

            Object.keys(dataMap).forEach(k => { const n = parseInt(k, 10); if (!isNaN(n) && n > maxWave) maxWave = Math.ceil(n / 10) * 10; });

            let cells = '';

            for (let w = 10; w <= maxWave; w += 10) {

                const entry = dataMap[String(w)];

                const has = entry && entry.info && entry.info.trim();

                const bossArg = boss ? ("'" + boss.replace(/'/g, "\\'") + "'") : 'null';

                cells += `<div onmouseenter="bossRedHover(event,this,'${section}',${w},${bossArg})" onmousemove="bossRedHover(event,this,'${section}',${w},${bossArg})" onmouseleave="bossRedHideTip()" style="padding:6px 4px;border-radius:6px;text-align:center;font-size:0.72rem;cursor:default;${has ? 'background:rgba(255,215,0,0.15);border:1px solid rgba(255,215,0,0.5);color:#ffd700;' : 'background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);color:rgba(255,255,255,0.4);'}">${w}波</div>`;

            }

            return `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:6px;">${cells}</div>`;

        }



        function bossRedHover(e, cellEl, section, wave, boss) {

            const tip = document.getElementById('bossRedTooltip');

            if (!tip) return;

            const data = bossRedCurrent;

            let entry = null;

            if (boss) { entry = ((data['深海'][boss] || {})[String(wave)]) || null; }

            else { entry = (data[section] || {})[String(wave)] || null; }

            const info = (entry && entry.info && entry.info.trim()) ? entry.info : '（暂无数据，管理员可在管理员菜单添加）';

            const title = (boss ? (boss + ' ') : '') + wave + '波';

            tip.innerHTML = `<div style="color:#ffd700;font-weight:bold;margin-bottom:4px;">${title}</div><div style="white-space:pre-wrap;font-size:0.78rem;line-height:1.5;">${info.replace(/</g, '&lt;')}</div>`;

            tip.style.display = 'block';

            // 方案2：钉在对应减伤格子的固定一侧（不跟随鼠标），避免遮挡
            const r = tip.getBoundingClientRect();
            const cr = (cellEl && cellEl.getBoundingClientRect) ? cellEl.getBoundingClientRect() : { left: e.clientX, top: e.clientY, right: e.clientX, bottom: e.clientY, width: 0, height: 0 };
            const GAP = 10;
            let x = cr.right + GAP; // 默认显示在格子右侧
            let y = cr.top;
            if (x + r.width > window.innerWidth - 4) x = cr.left - r.width - GAP; // 右侧放不下→翻到左侧
            if (x < 4) x = 4;
            if (y + r.height > window.innerHeight - 4) y = window.innerHeight - r.height - 4; // 下方超出→上移
            if (y < 4) y = 4;

            tip.style.left = x + 'px'; tip.style.top = y + 'px';

        }



        function bossRedHideTip() { const t = document.getElementById('bossRedTooltip'); if (t) t.style.display = 'none'; }



        // ===== 管理员面板 =====

        function bossRedAdminShow() {

            const menu = document.getElementById('adminMenuSection');

            if (menu) menu.style.display = 'none';

            const p = document.getElementById('adminPageBossRed');

            if (p) p.style.display = 'flex';

            bossRedAdminSection = '寒冰';

            bossRedAdminBoss = null;

            bossRedRenderSectionSel();

            bossRedRenderBossSel();

        }



        function bossRedAdminClose() {

            const p = document.getElementById('adminPageBossRed');

            if (p) p.style.display = 'none';

            const menu = document.getElementById('adminMenuSection');

            if (menu) menu.style.display = 'grid';

        }



        function bossRedAdminStatus(msg, type) {

            const el = document.getElementById('bossRedAdminStatus');

            if (!el) return;

            const bg = type === 'success' ? 'rgba(74,222,128,0.2)' : type === 'error' ? 'rgba(239,68,68,0.2)' : 'rgba(255,255,255,0.1)';

            const fg = type === 'success' ? '#4ade80' : type === 'error' ? '#ef4444' : '#fff';

            el.innerHTML = `<div style="background:${bg};color:${fg};padding:8px;border-radius:6px;text-align:center;font-size:0.82rem;">${msg}</div>`;

        }



        function bossRedRenderSectionSel() {

            const wrap = document.getElementById('bossRedSectionSel');

            if (wrap) wrap.innerHTML = BOSS_RED_SECTIONS.map(s => `<button onclick="bossRedPickSection('${s}')" style="padding:6px 12px;border:none;border-radius:6px;cursor:pointer;font-size:0.8rem;${bossRedAdminSection === s ? 'background:linear-gradient(135deg,#4caf50,#2e7d32);color:#fff;' : 'background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.7);'}">${s}</button>`).join('');

            const isDeep = bossRedAdminSection === '深海';

            const bw = document.getElementById('bossRedBossWrap');

            if (bw) bw.style.display = isDeep ? 'block' : 'none';

            const wl = document.getElementById('bossRedWaveLabel');

            if (wl) wl.textContent = isDeep ? '③ 波次' : '② 波次';

        }



        function bossRedPickSection(s) { bossRedAdminSection = s; bossRedAdminBoss = null; bossRedRenderSectionSel(); bossRedRenderBossSel(); }



        async function bossRedRenderBossSel() {

            if (bossRedAdminSection !== '深海') return;

            const data = await bossRedLoad();

            const bosses = Object.keys(data['深海'] || {});

            const wrap = document.getElementById('bossRedBossSel');

            if (!wrap) return;

            wrap.innerHTML = bosses.map(b => `<button onclick="bossRedPickBoss('${b.replace(/'/g, "\\'")}')" style="padding:5px 10px;border:none;border-radius:6px;cursor:pointer;font-size:0.78rem;${bossRedAdminBoss === b ? 'background:linear-gradient(135deg,#4caf50,#2e7d32);color:#fff;' : 'background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.7);'}">${b}</button>`).join('') || '<span style="color:rgba(255,255,255,0.4);font-size:0.75rem;">暂无Boss，请在下方添加</span>';

        }



        function bossRedPickBoss(b) { bossRedAdminBoss = b; bossRedRenderBossSel(); }



        async function bossRedAddBoss() {

            const name = (document.getElementById('bossRedBossName').value || '').trim();

            if (!name) { bossRedAdminStatus('请输入Boss名', 'error'); return; }

            const data = await bossRedLoad();

            if (!data['深海'][name]) data['深海'][name] = {};

            await bossRedSave(data);

            bossRedAdminBoss = name;

            const bn = document.getElementById('bossRedBossName'); if (bn) bn.value = '';

            bossRedRenderBossSel();

            bossRedAdminStatus('已添加/确认Boss：' + name, 'success');

        }



        async function bossRedSaveEntry() {
            if (typeof window.__recordFeatureUse === 'function') window.__recordFeatureUse('Boss减伤计算');

            const wave = parseInt((document.getElementById('bossRedWave').value || ''), 10);

            const info = (document.getElementById('bossRedInfo').value || '');

            if (!wave || wave <= 0) { bossRedAdminStatus('请输入有效波次', 'error'); return; }

            if (bossRedAdminSection === '深海' && !bossRedAdminBoss) { bossRedAdminStatus('请先选择/添加Boss', 'error'); return; }

            const data = await bossRedLoad();

            const target = bossRedAdminSection === '深海' ? (data['深海'][bossRedAdminBoss] || (data['深海'][bossRedAdminBoss] = {})) : data[bossRedAdminSection];

            if (info.trim() === '') { delete target[String(wave)]; }

            else { target[String(wave)] = { info: info }; }

            await bossRedSave(data);

            bossRedAdminStatus('已保存 ' + bossRedAdminSection + (bossRedAdminBoss ? ('·' + bossRedAdminBoss) : '') + ' ' + wave + '波', 'success');

            if (window.renderBossRed) renderBossRed();

        }



        async function bossRedDeleteEntry() {

            const wave = parseInt((document.getElementById('bossRedWave').value || ''), 10);

            if (!wave) { bossRedAdminStatus('请输入要删除的波次', 'error'); return; }

            const data = await bossRedLoad();

            const target = bossRedAdminSection === '深海' ? (data['深海'][bossRedAdminBoss] || {}) : data[bossRedAdminSection];

            delete target[String(wave)];

            await bossRedSave(data);

            bossRedAdminStatus('已删除 ' + wave + '波', 'success');

            if (window.renderBossRed) renderBossRed();

        }



        async function bossRedReload() { if (window.renderBossRed) await renderBossRed(); bossRedAdminStatus('已刷新', 'success'); }

        // ===== 批量导入 / 导出（文本格式，方便批量编辑）=====
        // 文本格式说明：
        //   # 板块名            → 切换板块（寒冰/暗月/漩涡/深海）
        //   @ Boss名            → 仅深海使用，切换 Boss
        //   10波 | 信息...      → 一条数据（也支持 "10 | 信息" / "10波: 信息" / "10=信息"）
        //   信息内多行：续行以两个空格或 Tab 开头，会拼到上一条信息里
        //   空行 / 以 // 开头的行 → 忽略
        function bossRedToText(data) {
            const lines = [];
            lines.push('// TFJL Boss减伤数据 —— 直接修改本文本后「导入」即可同步全网');
            lines.push('// 格式： # 板块   @ Boss(仅深海)   波次 | 信息');
            lines.push('// 信息想换行：下一行开头打两个空格');
            lines.push('');
            BOSS_RED_SECTIONS.forEach(sec => {
                lines.push('# ' + sec);
                if (sec === '深海') {
                    const bosses = Object.keys(data['深海'] || {});
                    if (!bosses.length) { lines.push('// （暂无Boss，可写： @ 南门 ）'); lines.push(''); return; }
                    bosses.forEach(b => {
                        lines.push('@ ' + b);
                        const m = data['深海'][b] || {};
                        Object.keys(m).map(Number).filter(n => !isNaN(n)).sort((a, x) => a - x).forEach(w => {
                            const info = ((m[String(w)] || {}).info || '');
                            lines.push(w + '波 | ' + info.split('\n')[0]);
                            info.split('\n').slice(1).forEach(l => lines.push('  ' + l));
                        });
                        lines.push('');
                    });
                } else {
                    const m = data[sec] || {};
                    const ws = Object.keys(m).map(Number).filter(n => !isNaN(n)).sort((a, x) => a - x);
                    if (!ws.length) lines.push('// （暂无数据，可写： 10波 | 减伤50% 血量2亿 ）');
                    ws.forEach(w => {
                        const info = ((m[String(w)] || {}).info || '');
                        lines.push(w + '波 | ' + info.split('\n')[0]);
                        info.split('\n').slice(1).forEach(l => lines.push('  ' + l));
                    });
                    lines.push('');
                }
            });
            return lines.join('\n');
        }

        function bossRedParseText(text) {
            const out = { '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} };
            let sec = null, boss = null, last = null;
            let count = 0;
            const rawLines = String(text || '').replace(/\r\n/g, '\n').split('\n');
            for (let i = 0; i < rawLines.length; i++) {
                const raw = rawLines[i];
                const line = raw.trim();
                // 续行：原始行以两个空格或 Tab 开头，且已有上一条
                if (last && /^(\t| {2})/.test(raw) && line) { last.info += '\n' + line; continue; }
                if (!line || line.startsWith('//')) continue;
                if (line.startsWith('#')) {
                    const name = line.replace(/^#+\s*/, '').trim();
                    if (!BOSS_RED_SECTIONS.includes(name)) throw new Error('第' + (i + 1) + '行：未知板块「' + name + '」，只能是 ' + BOSS_RED_SECTIONS.join('/'));
                    sec = name; boss = null; last = null; continue;
                }
                if (line.startsWith('@')) {
                    const name = line.replace(/^@+\s*/, '').trim();
                    if (sec !== '深海') throw new Error('第' + (i + 1) + '行：@Boss 只能用在「深海」板块下');
                    if (!name) throw new Error('第' + (i + 1) + '行：Boss名为空');
                    boss = name; if (!out['深海'][boss]) out['深海'][boss] = {}; last = null; continue;
                }
                const m = line.match(/^(\d+)\s*波?\s*[|:：=]\s*([\s\S]*)$/);
                if (!m) throw new Error('第' + (i + 1) + '行无法识别：' + line.slice(0, 40) + '\n（正确写法： 10波 | 信息内容）');
                if (!sec) throw new Error('第' + (i + 1) + '行：还没写板块，请先写一行 # 寒冰');
                if (sec === '深海' && !boss) throw new Error('第' + (i + 1) + '行：深海需要先写一行 @ Boss名');
                const wave = String(parseInt(m[1], 10));
                const entry = { info: m[2].trim() };
                if (sec === '深海') out['深海'][boss][wave] = entry; else out[sec][wave] = entry;
                last = entry; count++;
            }
            return { data: out, count: count };
        }

        function bossRedCountEntries(data) {
            let n = 0;
            BOSS_RED_SECTIONS.forEach(s => {
                if (s === '深海') Object.keys(data['深海'] || {}).forEach(b => { n += Object.keys(data['深海'][b] || {}).length; });
                else n += Object.keys(data[s] || {}).length;
            });
            return n;
        }

        async function bossRedOpenIO() {
            const box = document.getElementById('bossRedIOBox');
            const ta = document.getElementById('bossRedIOText');
            if (!box || !ta) return;
            box.style.display = 'block';
            bossRedAdminStatus('⏳ 正在从云端读取…', 'loading');
            try {
                const data = await bossRedLoad();
                ta.value = bossRedToText(data);
                bossRedAdminStatus('✅ 已载入云端数据（' + bossRedCountEntries(data) + ' 条），可直接编辑后点「导入并同步」', 'success');
            } catch (e) {
                ta.value = bossRedToText({ '寒冰': {}, '暗月': {}, '漩涡': {}, '深海': {} });
                bossRedAdminStatus('⚠️ 云端读取失败，已给出空白模板', 'error');
            }
        }

        function bossRedCloseIO() { const b = document.getElementById('bossRedIOBox'); if (b) b.style.display = 'none'; }

        async function bossRedDownloadText() {
            try {
                const ta = document.getElementById('bossRedIOText');
                let txt = ta && ta.value.trim() ? ta.value : bossRedToText(await bossRedLoad());
                const blob = new Blob([txt], { type: 'text/plain;charset=utf-8' });
                const a = document.createElement('a');
                a.href = URL.createObjectURL(blob);
                a.download = 'Boss减伤_' + new Date().toISOString().slice(0, 10) + '.txt';
                document.body.appendChild(a); a.click(); document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(a.href), 3000);
                bossRedAdminStatus('✅ 已导出为文件', 'success');
            } catch (e) { bossRedAdminStatus('❌ 导出失败：' + (e.message || e), 'error'); }
        }

        function bossRedPickFile() { const f = document.getElementById('bossRedIOFile'); if (f) f.click(); }

        function bossRedOnFile(input) {
            const file = input && input.files && input.files[0];
            if (!file) return;
            const r = new FileReader();
            r.onload = function () {
                const box = document.getElementById('bossRedIOBox');
                const ta = document.getElementById('bossRedIOText');
                if (box) box.style.display = 'block';
                if (ta) ta.value = String(r.result || '');
                bossRedAdminStatus('📄 已读入文件，请核对后点「导入并同步」', 'success');
            };
            r.readAsText(file, 'utf-8');
            input.value = '';
        }

        async function bossRedImportText(mode) {
            const ta = document.getElementById('bossRedIOText');
            if (!ta) return;
            let parsed;
            try { parsed = bossRedParseText(ta.value); }
            catch (e) { bossRedAdminStatus('❌ 格式有误：' + (e.message || e), 'error'); return; }
            if (!parsed.count) { bossRedAdminStatus('❌ 没解析到任何数据，请检查内容', 'error'); return; }
            const isOverwrite = mode === 'overwrite';
            const tip = isOverwrite
                ? '【覆盖】将用文本内容完全替换云端数据（文本里没有的波次会被删除）。\n\n解析到 ' + parsed.count + ' 条，确定继续？'
                : '【合并】把文本内容写入云端，同名波次以文本为准，云端其它数据保留。\n\n解析到 ' + parsed.count + ' 条，确定继续？';
            if (!confirm(tip)) return;
            bossRedAdminStatus('⏳ 正在同步到云端…', 'loading');
            try {
                let finalData;
                if (isOverwrite) {
                    finalData = parsed.data;
                } else {
                    const cloud = await bossRedLoad();
                    finalData = cloud;
                    BOSS_RED_SECTIONS.forEach(s => {
                        if (s === '深海') {
                            Object.keys(parsed.data['深海'] || {}).forEach(b => {
                                if (!finalData['深海'][b]) finalData['深海'][b] = {};
                                Object.assign(finalData['深海'][b], parsed.data['深海'][b]);
                            });
                        } else {
                            finalData[s] = Object.assign({}, finalData[s] || {}, parsed.data[s] || {});
                        }
                    });
                }
                await bossRedSave(finalData);
                bossRedAdminStatus('✅ 已同步到云端，共 ' + bossRedCountEntries(finalData) + ' 条，所有用户刷新即可看到', 'success');
                if (window.renderBossRed) await renderBossRed();
                if (bossRedAdminSection === '深海') bossRedRenderBossSel();
            } catch (e) {
                bossRedAdminStatus('❌ 同步失败：' + (e.message || e) + '（需管理员Token）', 'error');
            }
        }


        window.bossRedOpenIO = bossRedOpenIO;
        window.bossRedCloseIO = bossRedCloseIO;
        window.bossRedDownloadText = bossRedDownloadText;
        window.bossRedPickFile = bossRedPickFile;
        window.bossRedOnFile = bossRedOnFile;
        window.bossRedImportText = bossRedImportText;
        window.bossRedToText = bossRedToText;
        window.bossRedParseText = bossRedParseText;



const WALL_BACKUP_GIST_KEY = 'wall_backup_gist_id';
        const WALL_BACKUP_DESC = 'TFJL 需求墙数据备份（私有）';

        function wallShowBackupStatus(msg, type) {
            const el = document.getElementById('wallBackupStatus');
            if (!el) return;
            const bg = type === 'success' ? 'rgba(74,222,128,0.2)' : type === 'error' ? 'rgba(239,68,68,0.2)' : 'rgba(255,255,255,0.1)';
            const fg = type === 'success' ? '#4ade80' : type === 'error' ? '#ef4444' : '#fff';
            el.innerHTML = `<div style="background:${bg};color:${fg};padding:10px;border-radius:6px;text-align:center;font-size:0.85rem;">${msg}</div>`;
            if (type !== 'loading') setTimeout(() => { if (el) el.innerHTML = ''; }, 5000);
        }

        // ===== 需求墙备份（方案 B 架构：每备份独立 Gist + 索引数组，根治 Gist 300 文件硬上限截断） =====
        // 🔴 铁律（2026-08-23）：GitHub Gist 每个 Gist 硬限 300 文件，超量 GET 返回 truncated 且 files 被截断，
        //    旧架构把全部备份堆进同一 Gist → 3~4 份即爆 300 → 列表只读回最新1份，旧备份"消失"且死循环清不掉。
        //    新架构：每份备份存独立小 Gist（主索引+该份 content，文件数少永不爆）；索引 Gist（room_index.json）
        //    的 wall_backup_index 字段只存轻量数组 [{id,ts,date,messageCount,scriptCount,fp}]（仅1文件不截断）。
        //    列表只读索引数组；还原/查看/导出/删除按 id 去对应 Gist 取；清理=DELETE 整份超龄 Gist。

        // 读索引数组（跨设备唯一真相源；不存在/损坏返回空数组）。
        // 🔴 必须带 token！Gist ID 复用的是「总表 Gist」，匿名 GET 走 60次/小时 公共限流，
        //    房间页面+备份页面共用这 Gist，一天刷新几次就触发 429 速率限制 → 索引读不出 → "暂无备份"。
        //    带 token 后走 5000次/小时 认证限流，问题消失。
        async function wallGetBackupIndex() {
            try {
                const token = getGistToken();
                const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                if (idxResp.status === 429) { console.warn('[备份索引] GitHub 速率限制 429，备份列表暂不可读，请稍后再试'); return []; }
                if (!idxResp.ok) return [];
                const idxData = await idxResp.json();
                const ri = idxData.files && idxData.files['room_index.json'];
                if (!ri || !ri.content) return [];
                const idx = JSON.parse(ri.content || '{}');
                return Array.isArray(idx.wall_backup_index) ? idx.wall_backup_index : [];
            } catch (e) { return []; }
        }
        // 写索引数组（带乐观重试：先读最新再合并写回，避免并发覆盖）
        async function wallSaveBackupIndex(arr, token) {
            if (!token) return false;
            try {
                const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                if (!idxResp.ok) return false;
                const idxData = await idxResp.json();
                const ri = idxData.files && idxData.files['room_index.json'];
                const idx = ri && ri.content ? JSON.parse(ri.content || '{}') : {};
                idx.wall_backup_index = arr;
                const r = await fetch(`https://api.github.com/gists/${GIST_ID}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: { 'room_index.json': { content: JSON.stringify(idx, null, 2) } } }) });
                return r.ok;
            } catch (e) { return false; }
        }
        // 创建一个新的「独立备份 Gist」（仅含该份数据），返回 {id}
        async function wallCreateBackupGist(token, ts) {
            const c = await fetch('https://api.github.com/gists', { method: 'POST', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ description: 'TFJL 需求墙数据备份 #' + ts, public: false, files: { 'backup_info.json': { content: JSON.stringify({ created: ts, type: 'wall_backup_piece' }, null, 2) } } }) });
            if (!c.ok) throw new Error('创建备份Gist失败 HTTP ' + c.status);
            const d = await c.json();
            return d.id;
        }
        // 兼容别名（旧代码有调用 wallGetOrCreateBackupGist 的地方改为用索引，这里保留避免断链）
        async function wallGetOrCreateBackupGist() { return ''; }

        async function wallResolveMessagesGistId() {
            const gistDeleted = localStorage.getItem('messages_gist_deleted') === 'true';
            let id = (!gistDeleted && MESSAGES_GIST_ID) ? MESSAGES_GIST_ID : (localStorage.getItem('messages_gist_id') || '');
            if (!gistDeleted) {
                let resolvedFromIndex = false;
                try {
                    const token = getGistToken();
                    const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                    if (idxResp.ok) { const idxData = await idxResp.json(); const ri = idxData.files && idxData.files['room_index.json']; if (ri && ri.content) { const idx = JSON.parse(ri.content); if (idx.messages) { id = idx.messages; localStorage.setItem('messages_gist_id', id); resolvedFromIndex = true; } } }
                } catch (e) {}
                // 自愈：索引/常量都失效 → 扫账号下最近创建的「需求墙消息」Gist
                if (!resolvedFromIndex && (!id || id === MESSAGES_GIST_ID)) {
                    try {
                        const token = getGistToken();
                        let best = null;
                        for (let pg = 1; pg <= 5; pg++) {
                            const r = await fetch(`https://api.github.com/gists?per_page=100&page=${pg}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                            if (!r.ok) break;
                            const gs = await r.json(); if (!Array.isArray(gs) || !gs.length) break;
                            for (const g of gs) { if ((g.description || '').includes('需求墙消息')) { if (!best || new Date(g.created_at).getTime() > new Date(best.created_at).getTime()) best = g; } }
                            if (gs.length < 100) break;
                        }
                        if (best) { id = best.id; localStorage.setItem('messages_gist_id', id); }
                    } catch (e) { console.warn('[消息Gist自愈] 失败:', e); }
                }
            }
            return id;
        }

        async function wallReadGistFile(gistId, fileName, token) {
            const resp = await fetch(`https://api.github.com/gists/${gistId}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
            if (!resp.ok) return null;
            const d = await resp.json(); const f = d.files && d.files[fileName]; if (!f) return null;
            let content = f.content || '';
            if (f.truncated) { const raw = await fetch(f.raw_url, { headers: { ...(token && { 'Authorization': `token ${token}` }) } }); if (raw.ok) content = await raw.text(); }
            return content;
        }

        async function wallFetchScriptsForBackup(token) {
            const out = [];
            try {
                let page = 1;
                while (page <= 5) {
                    const resp = await fetch(`https://api.github.com/gists?per_page=100&page=${page}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                    if (!resp.ok) break;
                    const gists = await resp.json();
                    if (gists.length === 0) break;
                    for (const g of gists) {
                        if (g.description && g.description.includes('脚本分享')) {
                            try {
                                const detail = await fetch(`https://api.github.com/gists/${g.id}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                                if (!detail.ok) continue;
                                const dd = await detail.json(); const names = Object.keys(dd.files || {}); if (!names.length) continue;
                                const fn = names[0]; let content = (dd.files[fn].content) || '';
                                if (dd.files[fn].truncated) { const raw = await fetch(dd.files[fn].raw_url, { headers: { 'Authorization': `token ${token}` } }); if (raw.ok) content = await raw.text(); }
                                const m = g.description.match(/脚本分享:\s*(.+)/); const realName = m ? m[1].trim() : fn;
                                out.push({ gistId: g.id, description: g.description, fileName: realName, backupFileName: fn, content });
                            } catch (e) {}
                        }
                    }
                    if (gists.length < 100) break;
                    page++;
                }
            } catch (e) {}
            return out;
        }

        // ===== 备份内容指纹（增量备份）：消息+资料+脚本内容任一变化指纹即变，无变化不重复备份 =====
        // 与 .github/scripts/wall-backup.mjs 保持同一公式（sha256 串联），网页/Actions 两边判定一致
        async function _wallSha256Hex(str) {
            try {
                if (window.crypto && window.crypto.subtle) {
                    const buf = await window.crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(str || '')));
                    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
                }
            } catch (e) {}
            let h = 0x811c9dc5;   // 兜底 FNV（仅判变化，非加密用途）
            const s = String(str || '');
            for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; }
            return 'fnv' + h.toString(16);
        }
        async function wallComputeBackupFingerprint(msgContent, profContent, scripts) {
            const msgH = await _wallSha256Hex(msgContent || '');
            const profH = await _wallSha256Hex(profContent || '');
            const parts = [];
            for (const s of (scripts || [])) parts.push(String(s.gistId || '') + ':' + (await _wallSha256Hex(s.content || '')));
            parts.sort();
            return await _wallSha256Hex('msg:' + msgH + '|prof:' + profH + '|scripts:' + parts.join(','));
        }

        // ===== 备份保留策略（纯函数，可单测）：从备份 Gist 全部文件名里挑出"超龄备份"的整套文件 =====
        // 安全规则：
        //  1) 只认 backup_wall_all_<13位时间戳>.json 作为备份主索引，最新 keepMin 份（默认3）【永不删】——
        //     数据长期无变化不新增备份时，也至少留 3 份可还原（防单份损坏无法恢复）；
        //  2) 其余超龄主索引的时间戳进"待删集合"，content_ 前缀且能严格解析出同一时间戳的分片/脚本文件一起删；
        //  3) 其它任何文件名（backup_info.json / backup_status.json 等）一概不碰。
        function wallSelectExpiredBackupFiles(names, nowMs, keepDays, keepMin) {
            const MIN_KEEP = Math.max(1, keepMin || 3);   // 至少保留的备份份数
            const MAIN_RE = /^backup_wall_all_(\d{13})\.json$/;
            const CONTENT_RE = /^(backup_wall_all_|content_)[A-Za-z0-9_.\-]*_(\d{13})(\.[A-Za-z0-9]+)?$/;
            const list = (names || []).filter(function (n) { return n && typeof n === 'string'; });
            const mains = [];
            for (const n of list) {
                const m = n.match(MAIN_RE);
                if (m) mains.push({ name: n, ts: parseInt(m[1], 10) });
            }
            if (!mains.length) return [];
            mains.sort(function (a, b) { return b.ts - a.ts; });   // 新→旧，[0] 最新
            const cutoff = nowMs - (keepDays || 10) * 86400 * 1000;
            const doomed = new Set();
            for (let i = MIN_KEEP; i < mains.length; i++) { if (mains[i].ts < cutoff) doomed.add(mains[i].ts); }
            if (!doomed.size) return [];
            const out = [];
            for (const n of list) {
                const mm = n.match(MAIN_RE);
                if (mm) { if (doomed.has(parseInt(mm[1], 10))) out.push(n); continue; }
                const cm = n.match(CONTENT_RE);
                if (cm && doomed.has(parseInt(cm[2], 10))) out.push(n);   // 贪婪匹配取"最后一组13位数字"=真实备份时间戳
            }
            return out;
        }

        // ===== 备份运行状态（可观测）：每次备份/跳过/清理后写入 backup_status.json =====
        // 网页端手动/自动备份与 GitHub Actions 定时备份写同一份状态文件，
        // 备份中心顶部"上次自动备份"栏读取它——有没有正常跑、有没有卡住一眼可见。
        // 备份运行状态写入索引 Gist（room_index.json 的 wall_backup_status 字段），跨设备/网页/App/Actions 统一可读
        async function wallWriteBackupStatus(st) {
            try {
                const token = getGistToken(); if (!token) return;
                const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                if (!idxResp.ok) return;
                const idxData = await idxResp.json();
                const ri = idxData.files && idxData.files['room_index.json'];
                const idx = ri && ri.content ? JSON.parse(ri.content || '{}') : {};
                idx.wall_backup_status = Object.assign({ ts: Date.now() }, st);
                await fetch(`https://api.github.com/gists/${GIST_ID}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: { 'room_index.json': { content: JSON.stringify(idx, null, 2) } } }) });
            } catch (e) { /* 状态写失败不影响备份本身 */ }
        }
        async function wallLoadAutoStatus() {
            const el = document.getElementById('wallAutoStatus');
            if (!el) return;
            try {
                const token = getGistToken();
                const resp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { Authorization: `token ${token}` }) } });
                if (!resp.ok) { el.innerHTML = ''; return; }
                const d = await resp.json();
                const ri = d.files && d.files['room_index.json'];
                let st = {};
                if (ri && ri.content) { try { st = (JSON.parse(ri.content) || {}).wall_backup_status || {}; } catch (e) {} }
                if (!st || !st.ts) { el.innerHTML = '<div style="color:rgba(255,255,255,0.45);font-size:0.75rem;">🤖 自动备份：还没有运行记录（配置后每天 04:00 由 GitHub Actions 自动跑）</div>'; return; }
                const t = st.ts ? new Date(st.ts).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '?';
                const from = st.mode === 'actions' ? '🤖 定时任务' : st.mode === 'web' ? '💻 网页端' : '未知来源';
                let line;
                if (st.ok === false) line = `<span style="color:#ef4444;">❌ ${from} ${t}：${escapeHtml(st.error || '失败')}</span>`;
                else if (st.result === 'skip') line = `<span style="color:#4ade80;">✅ ${from} ${t}：数据无变化，跳过备份${st.cleaned ? ' · 清理 ' + st.cleaned + ' 份超龄' : ''}</span>`;
                else line = `<span style="color:#4ade80;">✅ ${from} ${t}：完成备份（消息 ${st.messageCount ?? '?'} · 脚本 ${st.scriptCount ?? '?'}${st.cleaned ? ' · 清理 ' + st.cleaned + ' 份超龄' : ''}）</span>`;
                el.innerHTML = `<div style="background:rgba(78,205,196,0.08);border-left:3px solid #4ecdc4;border-radius:6px;padding:8px 10px;font-size:0.78rem;margin-bottom:8px;">🤖 上次自动备份：${line}</div>`;
            } catch (e) { el.innerHTML = ''; }
        }
        window.wallLoadAutoStatus = wallLoadAutoStatus;

        // ===== 孤儿残留检测（纯函数，可单测）：没有被任何现存主索引声明的 content_* 文件 =====
        // 历史遗留：旧版"删除备份"只删主索引不删关联文件，测试期多次备份/删除后 Gist 里积了大量
        // 无主 content_* 残留（恢复入口只认主索引，没主索引的 content 文件永远用不上，纯脏数据）。
        // 安全规则：任一主索引声明过的文件（消息分片/资料/脚本）一律保留；
        //           任一主索引 JSON 损坏解析失败 → 整体放弃（返回空，宁可不清也不误删）；
        //           只清 content_ 前缀且未被声明的；其它文件名（backup_status 等）一概不碰。
        function wallSelectOrphanBackupFiles(filesObj) {
            const MAIN_RE = /^backup_wall_all_\d{13}\.json$/;
            const names = Object.keys(filesObj || {});
            const declared = new Set();
            for (const n of names) {
                if (!MAIN_RE.test(n)) continue;
                let main;
                try { main = JSON.parse(filesObj[n]); } catch (e) { return []; }   // 主索引损坏 → 保守放弃
                if (!main || typeof main !== 'object') return [];
                const cf = main.files || {};
                (Array.isArray(cf.messages) ? cf.messages : (cf.messages ? [cf.messages] : [])).forEach(function (x) { declared.add(x); });
                if (cf.profiles) declared.add(cf.profiles);
                (main.scripts || []).forEach(function (s) { if (s && s.backupFile) declared.add(s.backupFile); });
            }
            const out = [];
            for (const n of names) {
                if (n.indexOf('content_') === 0 && !declared.has(n)) out.push(n);
            }
            return out;
        }

        // 清理超龄备份（方案 B）：按索引数组删除「超龄且超出保留份数」的整份 Gist（DELETE），并同步索引。
        // 返回 { deleted: 已删份数, kept: 保留份数 }。dryRun=true 只计数不删。
        async function wallCleanupOldBackups(keepDays, dryRun) {
            const token = getGistToken(); if (!token) throw new Error('无Token');
            let indexArr = await wallGetBackupIndex();
            if (!indexArr.length) return { deleted: 0, kept: 0 };
            const now = Date.now();
            const keepMs = (keepDays || 10) * 24 * 3600 * 1000;
            // 升序（旧在前）：先按 age 过滤超龄，再按"最少保留 keepMin 份"保护最新几份
            const sorted = indexArr.slice().sort(function (a, b) { return a.ts - b.ts; });
            const expired = sorted.filter(function (e) { return now - e.ts > keepMs; });
            const keepMin = 3;
            const removable = expired.slice(0, Math.max(0, expired.length - (sorted.length - Math.min(sorted.length, keepMin + (sorted.length - expired.length)))));
            // 简化：保留最新 keepMin 份不删；其余超龄的可删
            const keepIds = new Set(sorted.slice(sorted.length - keepMin).map(function (e) { return e.id; }));
            const toDelete = expired.filter(function (e) { return !keepIds.has(e.id); });
            if (dryRun) return { deleted: toDelete.length, kept: indexArr.length - toDelete.length };
            let deleted = 0;
            const remain = [];
            for (const e of indexArr) {
                if (toDelete.some(function (t) { return t.id === e.id; })) {
                    try { const dr = await fetch(`https://api.github.com/gists/${e.id}`, { method: 'DELETE', headers: { 'Authorization': `token ${token}` } }); if (dr.ok || dr.status === 404) deleted++; }
                    catch (err) { remain.push(e); }
                } else { remain.push(e); }
            }
            await wallSaveBackupIndex(remain, token);
            return { deleted: deleted, kept: remain.length };
        }
        async function wallPreviewCleanup() {
            try {
                wallShowBackupStatus('⏳ 正在扫描超龄备份（仅预览，不删除）...', 'loading');
                const r = await wallCleanupOldBackups(10, true);
                if (!r.deleted) { wallShowBackupStatus('✅ 很干净：无超龄备份（最少保留 3 份）', 'success'); return; }
                if (confirm(`🧹 预览发现 ${r.deleted} 份超龄备份（超过 ${10} 天且超出最少保留 3 份）。\n\n点「确定」立即清理（删除整份 Gist），点「取消」只看不删。`)) {
                    const done = await wallCleanupOldBackups(10, false);
                    wallShowBackupStatus(`✅ 已清理 ${done.deleted} 份超龄备份，保留 ${done.kept} 份`, 'success');
                    wallLoadBackupList();
                } else {
                    wallShowBackupStatus(`👁️ 预览：${r.deleted} 份超龄备份待清理（本次未删除）`, 'success');
                }
            } catch (e) { wallShowBackupStatus('❌ 清理预览失败：' + e.message, 'error'); }
        }

        // 列出账号下全部「脚本分享」Gist（不抓内容，轻量）：[{id, description, fileName}]
        // 供导入/还原时按「描述」匹配现有脚本——Gist 地址变了也能对上（列表扫描本来就按描述发现脚本）
        async function wallListScriptGists(token) {
            const out = [];
            try {
                let page = 1;
                while (page <= 5) {
                    const resp = await fetch(`https://api.github.com/gists?per_page=100&page=${page}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                    if (!resp.ok) break;
                    const gists = await resp.json();
                    if (!Array.isArray(gists) || gists.length === 0) break;
                    for (const g of gists) {
                        if (g.description && g.description.includes('脚本分享')) out.push({ id: g.id, description: g.description, fileName: Object.keys(g.files || {})[0] || '' });
                    }
                    if (gists.length < 100) break;
                    page++;
                }
            } catch (e) {}
            return out;
        }
        window.wallListScriptGists = wallListScriptGists;

        async function wallBackupAll() {
            wallShowBackupStatus('⏳ 正在备份需求墙全部数据...', 'loading');
            try {
                const token = getGistToken(); if (!token) throw new Error('无Token');
                const ts = Date.now();
                const files = {};
                wallShowBackupStatus('⏳ 备份消息...', 'loading');
                const msgGistId = await wallResolveMessagesGistId();
                let msgContent = null;
                if (msgGistId) msgContent = await wallReadGistFile(msgGistId, 'messages.json', token);
                // 消息分片：Gist 单文件 API 上限约 1MB，超过则按数组切片成多个 <1MB 文件，主索引只记文件名数组
                let msgFiles = null;
                if (msgContent) {
                    let allMsgs = [];
                    try { allMsgs = (JSON.parse(msgContent).messages) || []; } catch (e) {}
                    const bytes = (typeof TextEncoder !== 'undefined') ? new TextEncoder().encode(msgContent).length : msgContent.length * 2;
                    const CHUNK = 800000; // 单文件上限 800KB（留余量，远低于 Gist 1MB）
                    const n = bytes > CHUNK ? Math.max(1, Math.ceil(bytes / CHUNK)) : 1;
                    const per = Math.ceil(allMsgs.length / n);
                    msgFiles = [];
                    for (let i = 0; i < n; i++) {
                        const part = allMsgs.slice(i * per, (i + 1) * per);
                        const fn = `content_messages_${i}_${ts}.json`;
                        files[fn] = { content: JSON.stringify({ messages: part }, null, 2) };
                        msgFiles.push(fn);
                    }
                }
                wallShowBackupStatus('⏳ 备份个人资料...', 'loading');
                let profContent = null;
                if (msgGistId) profContent = await wallReadGistFile(msgGistId, 'profiles.json', token);
                if (profContent) files[`content_profiles_${ts}.json`] = { content: profContent };
                wallShowBackupStatus('⏳ 备份脚本内容...', 'loading');
                const scripts = await wallFetchScriptsForBackup(token);
                // ===== 增量判断：内容指纹与索引中最新一份备份一致 → 不重复建 Gist（但刷新 status） =====
                const fp = await wallComputeBackupFingerprint(msgContent, profContent, scripts);
                let indexArr = [];
                try { indexArr = await wallGetBackupIndex(); } catch (e) {}
                const lastEntry = indexArr.length ? indexArr[indexArr.length - 1] : null;
                if (lastEntry && lastEntry.fp && lastEntry.fp === fp) {
                    try { localStorage.setItem('wall_last_backup_ts', String(Date.now())); } catch (e) {}
                    let cleanedSkip = 0;
                    try { const csr = await wallCleanupOldBackups(10, false); cleanedSkip = csr.deleted || 0; } catch (e) {}
                    wallWriteBackupStatus({ mode: 'web', ok: true, result: 'skip', messageCount: msgContent ? (JSON.parse(msgContent).messages || []).length : 0, scriptCount: scripts.length, cleaned: cleanedSkip });
                    wallShowBackupStatus(`✅ 数据无变化，跳过备份（指纹一致）${cleanedSkip ? ' · 顺带清理了 ' + cleanedSkip + ' 份超龄备份' : ''}`, 'success');
                    wallLoadBackupList();
                    return;
                }
                const scriptsRef = [];
                for (const s of scripts) {
                    const safe = s.backupFileName.replace(/[^a-zA-Z0-9_\-.]/g, '_');
                    const ext = s.backupFileName.includes('.') ? s.backupFileName.split('.').pop() : 'js';
                    // 🔴 防撞名（2026-08-22 实测旧逻辑 69 脚本丢 15 个内容）：中文全洗成下划线后不同脚本能洗出同名文件互相覆盖，
                    //    追加 gistId（每脚本唯一）杜绝覆盖；还原/导入按引用定位不受文件名影响。
                    const bf = `content_script_${safe}_${s.gistId}_${ts}.${ext}`;
                    const scBytes = (typeof TextEncoder !== 'undefined') ? new TextEncoder().encode(s.content).length : s.content.length * 2;
                    if (scBytes > 900000) { console.warn('[备份] 脚本', safe, '约', (scBytes / 1024 / 1024).toFixed(1), 'MB，可能超 Gist 单文件限制'); }
                    files[bf] = { content: s.content };
                    scriptsRef.push({ gistId: s.gistId, description: s.description, fileName: s.fileName, backupFile: bf, bytes: scBytes });
                }
                const main = { timestamp: ts, date: new Date().toLocaleString('zh-CN'), type: 'wall_full_v1', fp: fp, messagesGistId: msgGistId, messageCount: msgContent ? (JSON.parse(msgContent).messages || []).length : 0, scriptCount: scripts.length, scripts: scriptsRef, files: { messages: msgFiles, profiles: profContent ? `content_profiles_${ts}.json` : null } };
                files[`backup_wall_all_${ts}.json`] = { content: JSON.stringify(main, null, 2) };
                // 🔴 方案 B：每份备份建独立 Gist（不再堆同一 Gist，根治 300 文件截断）
                const backupId = await wallCreateBackupGist(token, ts);
                const resp = await fetch(`https://api.github.com/gists/${backupId}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files }) });
                if (!resp.ok) throw new Error('保存备份失败');
                // 追加进索引数组（轻量，不触发截断）
                indexArr.push({ id: backupId, ts: ts, date: main.date, messageCount: main.messageCount, scriptCount: main.scriptCount, fp: fp });
                await wallSaveBackupIndex(indexArr, token);
                let cleanMsg = '';
                let cleanedN = 0;
                try { const cr = await wallCleanupOldBackups(10, false); cleanedN = cr.deleted || 0; if (cleanedN) cleanMsg = ` · 已自动清理 ${cleanedN} 份超龄备份`; } catch (e) { console.warn('[备份] 自动清理失败:', e); }
                wallWriteBackupStatus({ mode: 'web', ok: true, result: 'backup', messageCount: main.messageCount, scriptCount: main.scriptCount, cleaned: cleanedN });
                wallShowBackupStatus(`✅ 备份成功！消息:${main.messageCount} 脚本:${main.scriptCount}${cleanMsg}`, 'success');
                try { localStorage.setItem('wall_last_backup_ts', String(Date.now())); } catch (e) {}
                wallLoadBackupList();
            } catch (e) { wallShowBackupStatus(`❌ 备份失败：${e.message}`, 'error'); }
        }

        function wallToggleAutoBackup(on) { try { localStorage.setItem('wall_auto_backup', on ? '1' : '0'); } catch (e) {} }
        function wallCheckAutoBackup() {
            try {
                if (localStorage.getItem('wall_auto_backup') !== '1') return;
                const last = parseInt(localStorage.getItem('wall_last_backup_ts') || '0', 10);
                if (Date.now() - last > 24 * 3600 * 1000) { setTimeout(function () { try { wallBackupAll(); } catch (e) {} }, 8000); }
            } catch (e) {}
        }
        try { setInterval(wallCheckAutoBackup, 60 * 60 * 1000); wallCheckAutoBackup(); } catch (e) {}

        async function wallLoadBackupList() {
            const c = document.getElementById('wallBackupListContainer');
            if (!c) return;
            c.innerHTML = '<div style="color:rgba(255,255,255,0.5);text-align:center;padding:20px;">⏳ 加载中...</div>';
            try { if (typeof wallLoadAutoStatus === 'function') wallLoadAutoStatus(); } catch (e) {}
            try {
                // 🔴 方案 B：只读索引数组（轻量、不触发 300 截断），不再整 Gist 拉文件列表
                const indexArr = await wallGetBackupIndex();
                const all = indexArr.slice().sort(function (a, b) { return b.ts - a.ts; });
                if (!all.length) { c.innerHTML = '<div style="color:rgba(255,255,255,0.5);text-align:center;">暂无备份</div>'; return; }
                let html = `<div style="color:rgba(255,255,255,0.6);font-size:0.75rem;margin-bottom:8px;">📁 备份 ${all.length} 个</div>`;
                all.forEach(function (e) {
                    const id = e.id; const ts = e.ts;
                    const disp = ts ? new Date(ts).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '未知';
                    const info = `消息:${e.messageCount != null ? e.messageCount : '?'} 脚本:${e.scriptCount != null ? e.scriptCount : '?'}`;
                    html += `<div style="background:rgba(255,255,255,0.05);border-radius:6px;padding:8px 12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;">
                        <span><span style="color:#ffd700;">📦 全量</span><span style="color:rgba(255,255,255,0.5);font-size:0.75rem;margin-left:8px;">${disp} · ${info}</span></span>
                        <div style="display:flex;gap:4px;">
                            <button onclick="wallViewBackupDetail('${id}')" style="background:rgba(249,115,22,0.18);border:none;color:#fb923c;padding:4px 8px;border-radius:4px;cursor:pointer;font-size:0.75rem;">🔄还原</button>
                            <button onclick="wallExportBackup('${id}')" style="background:rgba(255,255,255,0.1);border:none;color:#4fc3f7;padding:4px 8px;border-radius:4px;cursor:pointer;font-size:0.75rem;">导出</button>
                            <button onclick="wallDeleteBackup('${id}')" style="background:rgba(239,68,68,0.2);border:none;color:#ef4444;padding:4px 8px;border-radius:4px;cursor:pointer;font-size:0.75rem;">删除</button>
                        </div></div>`;
                });
                c.innerHTML = html;
            } catch (e) { c.innerHTML = `<div style="color:#ef4444;text-align:center;">加载失败：${e.message}</div>`; }
        }

        async function wallGetBackupFile(backupId, fileName, token) {
            return await wallReadGistFile(backupId, fileName, token);
        }
        // 方案 B：从某个独立备份 Gist 读取其主索引（文件名 backup_wall_all_<ts>.json）
        async function wallGetBackupMain(backupId, token) {
            const resp = await fetch(`https://api.github.com/gists/${backupId}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
            if (!resp.ok) return null;
            const d = await resp.json();
            const mains = Object.keys(d.files || {}).filter(n => /^backup_wall_all_\d{13}\.json$/.test(n)).sort();
            if (!mains.length) return null;
            const mc = d.files[mains[mains.length - 1]].content;
            return mc ? JSON.parse(mc) : null;
        }

        async function wallRestoreBackup(id, merge) {
            const mEl = document.getElementById('wallBackupDetailModal'); if (mEl) mEl.remove();
            if (!confirm(`⏳ 确定从该备份还原需求墙吗？\n模式：${merge ? '合并（保留当前新消息，补回丢失的）' : '覆盖（用备份完全替换当前）'}\n\n⚠️ 这将影响全部用户的需求墙！`)) return;
            wallShowBackupStatus('⏳ 正在还原...', 'loading');
            try {
                const token = getGistToken(); if (!token) throw new Error('无Token');
                const main = await wallGetBackupMain(id, token);
                if (!main) throw new Error('备份主索引不存在');
                const cf = main.files || {};
                let msgStat = '';
                if (cf.messages && main.messagesGistId) {
                    wallShowBackupStatus('⏳ 还原消息...', 'loading');
                    // 兼容：分片备份时 cf.messages 为文件名数组，旧单文件时为字符串
                    const msgFileList = Array.isArray(cf.messages) ? cf.messages : (cf.messages ? [cf.messages] : []);
                    let bkMsgs = [];
                    for (const mf of msgFileList) {
                        const mc = await wallGetBackupFile(id, mf, token);
                        if (mc) { try { const arr = (JSON.parse(mc).messages) || []; bkMsgs = bkMsgs.concat(arr); } catch (e) {} }
                    }
                    if (bkMsgs.length) {
                        let finalMsgs;
                        if (merge) {
                            const seen = new Set((wallMessages || []).map(x => x.time + '_' + x.author + '_' + (x.content || '').substring(0, 30)));
                            finalMsgs = (wallMessages || []).slice();
                            let added = 0;
                            bkMsgs.forEach(x => { const k = x.time + '_' + x.author + '_' + (x.content || '').substring(0, 30); if (!seen.has(k)) { finalMsgs.push(x); seen.add(k); added++; } });
                            finalMsgs.sort((a, b) => b.time - a.time);
                            wallShowBackupStatus(`⏳ 合并：补回 ${added} 条，共 ${finalMsgs.length} 条...`, 'loading');
                        } else {
                            finalMsgs = bkMsgs.slice();
                        }
                        finalMsgs = finalMsgs.slice(0, MAX_MESSAGES);
                        const expN = wallCountExpiredMsgs(finalMsgs);
                        msgStat = `共 ${finalMsgs.length} 条` + (expN ? `（其中 ${expN} 条已过期不显示）` : '');
                        const resp = await fetch(`https://api.github.com/gists/${main.messagesGistId}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: { 'messages.json': { content: JSON.stringify({ messages: finalMsgs }, null, 2) } } }) });
                        if (!resp.ok) throw new Error('消息还原写入失败');
                    }
                }
                if (cf.profiles) {
                    wallShowBackupStatus('⏳ 还原个人资料...', 'loading');
                    const pc = await wallGetBackupFile(id, cf.profiles, token);
                    if (pc) { try { await fetch(`https://api.github.com/gists/${main.messagesGistId}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: { 'profiles.json': { content: pc } } }) }); } catch (e) {} }
                }
                if (main.scripts && main.scripts.length) {
                    wallShowBackupStatus('⏳ 还原脚本内容...', 'loading');
                    let _descMap = null;
                    const hdr = { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` };
                    for (const ref of main.scripts) {
                        const sc = await wallGetBackupFile(id, ref.backupFile, token);
                        if (!sc) continue;
                        const chk = await fetch(`https://api.github.com/gists/${ref.gistId}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                        if (chk.ok) {
                            await fetch(`https://api.github.com/gists/${ref.gistId}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ files: { [ref.fileName]: { content: sc } } }) });
                        } else {
                            // 原 Gist 已删/地址失效：先按描述匹配现有 Gist（防重复建），再没有才重建
                            if (!_descMap) { _descMap = {}; (await wallListScriptGists(token)).forEach(g => { _descMap[g.description] = g; }); }
                            const g = _descMap[ref.description];
                            if (g) await fetch(`https://api.github.com/gists/${g.id}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ files: { [g.fileName || ref.fileName]: { content: sc } } }) });
                            else await fetch('https://api.github.com/gists', { method: 'POST', headers: hdr, body: JSON.stringify({ description: ref.description, public: false, files: { [ref.fileName]: { content: sc } } }) });
                        }
                    }
                }
                wallShowBackupStatus('✅ 还原成功！' + (msgStat ? msgStat + ' · ' : '') + '建议刷新页面查看', 'success');
                if (typeof fetchMessages === 'function') fetchMessages();
            } catch (e) { wallShowBackupStatus(`❌ 还原失败：${e.message}`, 'error'); }
        }

        async function wallViewBackupDetail(id) {
            try {
                const token = getGistToken();
                const main = await wallGetBackupMain(id, token);
                const d = main || {};
                const html = `<div id="wallBackupDetailModal" style="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.8);z-index:99999;display:flex;justify-content:center;align-items:center;">
                    <div style="background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:12px;padding:20px;max-width:600px;width:90%;max-height:80vh;overflow-y:auto;">
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px;"><h3 style="color:#ffd700;margin:0;">📋 备份详情</h3><button onclick="document.getElementById('wallBackupDetailModal').remove()" style="background:none;border:none;color:#fff;font-size:1.5rem;cursor:pointer;">✕</button></div>
                        <div style="background:rgba(0,0,0,0.3);border-radius:8px;padding:12px;font-size:0.85rem;margin-bottom:12px;">
                            <div style="color:#4ade80;">时间：${d.date || ''}</div>
                            <div style="color:rgba(255,255,255,0.8);margin-top:6px;">消息数：${d.messageCount || 0}　脚本数：${d.scriptCount || 0}</div>
                            <div style="color:rgba(255,255,255,0.6);font-size:0.75rem;margin-top:4px;">消息Gist：${(d.messagesGistId || '').substring(0,12)}…</div>
                        </div>
                        <div style="display:flex;gap:10px;">
                            <button onclick="wallRestoreBackup('${id}', true)" style="background:linear-gradient(135deg,#4caf50,#2e7d32);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:0.82rem;">🔄 合并还原</button>
                            <button onclick="wallRestoreBackup('${id}', false)" style="background:linear-gradient(135deg,#f97316,#ea580c);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:0.82rem;">⚠️ 覆盖还原</button>
                            <button onclick="document.getElementById('wallBackupDetailModal').remove()" style="background:rgba(255,255,255,0.1);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;">关闭</button>
                        </div>
                    </div></div>`;
                document.body.insertAdjacentHTML('beforeend', html);
            } catch (e) { alert('查看失败：' + e.message); }
        }
        // 导出：打包全部真实内容（消息+个人资料+脚本内容）为一个自包含本地 json——
        // 不含任何"必须原 Gist 地址存在"的依赖，之后经「导入本地备份」可完整还原（按描述重新匹配地址）。
        async function wallExportBackup(id) {
            wallShowBackupStatus('⏳ 正在打包全部内容（消息+资料+脚本）...', 'loading');
            try {
                const token = getGistToken(); if (!token) throw new Error('无Token');
                const main = await wallGetBackupMain(id, token);
                if (!main) throw new Error('备份主索引不存在');
                const cf = main.files || {};
                // 消息（分片合并为完整数组）
                const msgFileList = Array.isArray(cf.messages) ? cf.messages : (cf.messages ? [cf.messages] : []);
                let messages = [];
                for (const mf of msgFileList) {
                    const mc = await wallGetBackupFile(id, mf, token);
                    if (mc) { try { messages = messages.concat((JSON.parse(mc).messages) || []); } catch (e) {} }
                }
                // 个人资料（原样字符串保留）
                let profiles = null;
                if (cf.profiles) profiles = await wallGetBackupFile(id, cf.profiles, token);
                // 脚本内容（含撞名修复前旧备份的已知局限：撞名文件只含最后写入的一份）
                const scripts = [];
                for (const ref of (main.scripts || [])) {
                    const sc = await wallGetBackupFile(id, ref.backupFile, token);
                    if (sc !== null) scripts.push({ description: ref.description, fileName: ref.fileName, gistId: ref.gistId, bytes: ref.bytes, content: sc });
                }
                const bundle = { __tfjl_wall_export__: 2, exportedAt: Date.now(), sourceBackup: id, sourceDate: main.date || '', messageCount: messages.length, scriptCount: scripts.length, messages, profiles, scripts };
                const dt = new Date(); const p2 = (n) => String(n).padStart(2, '0');
                const expN = wallCountExpiredMsgs(messages);
                const msgPart = `消息 ${messages.length} 条${expN ? `（其中 ${expN} 条已过期）` : ''}`;
                const dl = `wall-backup-full-${dt.getFullYear()}${p2(dt.getMonth() + 1)}${p2(dt.getDate())}-${p2(dt.getHours())}${p2(dt.getMinutes())}${p2(dt.getSeconds())}.json`;
                const text = JSON.stringify(bundle);
                const blob = new Blob([text], { type: 'application/json' });
                // 网页版保存：showSaveFilePicker 选位置 → 兜底默认下载
                const webSave = async () => {
                    if (window.showSaveFilePicker) {
                        try {
                            const handle = await window.showSaveFilePicker({ suggestedName: dl, types: [{ description: 'JSON 备份文件', accept: { 'application/json': ['.json'] } }] });
                            const w = await handle.createWritable(); await w.write(blob); await w.close();
                            wallShowBackupStatus(`✅ 已保存到您选择的位置（${msgPart} · 脚本 ${scripts.length} 个）`, 'success');
                            return;
                        } catch (e) { if (e && e.name === 'AbortError') { wallShowBackupStatus('已取消保存'); return; } }
                    }
                    const url = URL.createObjectURL(blob);
                    const a = document.createElement('a'); a.href = url; a.download = dl; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
                    wallShowBackupStatus(`✅ 已下载到默认下载目录（${msgPart} · 脚本 ${scripts.length} 个）：${dl}`, 'success');
                };
                // App：复用统一下载保存弹窗（与脚本下载同款：已配置目录卡片一键存 + 浏览文件夹自定义位置）
                const invokeFn = (window.__TAURI_INTERNALS__ && window.__TAURI_INTERNALS__.invoke) || (window.__TAURI__ && window.__TAURI__.core && window.__TAURI__.core.invoke);
                if (invokeFn && typeof _downloadScriptTauri === 'function') {
                    const saved = await _downloadScriptTauri(dl, text, {
                        title: '📥 保存需求墙备份',
                        onSaved: (p) => wallShowBackupStatus(`✅ 已保存：${p}（${msgPart} · 脚本 ${scripts.length} 个）`, 'success'),
                        fallback: () => { webSave(); }
                    });
                    if (saved) return;
                    wallShowBackupStatus('已取消保存');
                    return;
                }
                await webSave();
            } catch (e) { wallShowBackupStatus(`❌ 导出失败：${e.message}`, 'error'); }
        }

        // 导入本地全量备份：选文件 → 摘要确认 → 合并/覆盖写入。
        // 地址无关性：脚本按「描述」匹配现有 Gist（对上→原文件名覆盖写回；原 Gist 已删→自动重建）；
        // 消息写入"当前"消息 Gist（wallResolveMessagesGistId 经索引指针实时解析，不依赖备份里的旧 id）。
        function wallImportOnFile(input) {
            const f = input.files && input.files[0];
            try { input.value = ''; } catch (e) {}
            if (!f) return;
            const reader = new FileReader();
            reader.onload = () => {
                try {
                    const bundle = JSON.parse(reader.result);
                    if (!bundle || bundle.__tfjl_wall_export__ !== 2) { alert('不是有效的「需求墙全量备份」文件（缺 __tfjl_wall_export__ 标记）'); return; }
                    window.__wallImportBundle = bundle;
                    const mOld = document.getElementById('wallBackupDetailModal'); if (mOld) mOld.remove();
                    const expPre = wallCountExpiredMsgs(bundle.messages);
                    const html = `<div id="wallBackupDetailModal" style="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.8);z-index:99999;display:flex;justify-content:center;align-items:center;">
                        <div style="background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:12px;padding:20px;max-width:600px;width:90%;max-height:80vh;overflow-y:auto;">
                            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px;"><h3 style="color:#ffd700;margin:0;">📥 导入本地备份</h3><button onclick="document.getElementById('wallBackupDetailModal').remove()" style="background:none;border:none;color:#fff;font-size:1.5rem;cursor:pointer;">✕</button></div>
                            <div style="background:rgba(0,0,0,0.3);border-radius:8px;padding:12px;font-size:0.85rem;margin-bottom:12px;">
                                <div style="color:#4ade80;">来源备份时间：${escapeHtml(String(bundle.sourceDate || ''))}</div>
                                <div style="color:rgba(255,255,255,0.8);margin-top:6px;">消息 ${(bundle.messages || []).length} 条 · 脚本 ${(bundle.scripts || []).length} 个${bundle.profiles ? ' · 含个人资料' : ''}</div>
                                ${expPre ? `<div style="color:#ff9800;font-size:0.75rem;margin-top:4px;">⏳ 其中 ${expPre} 条消息已过期：数据照常写回，但需求墙不显示</div>` : ''}
                                <div style="color:rgba(255,255,255,0.55);font-size:0.75rem;margin-top:6px;">脚本按「描述」重新匹配：对得上→写回内容；原 Gist 已删→自动重建（脚本列表会重新发现，不依赖旧地址）。</div>
                            </div>
                            <div style="display:flex;gap:10px;flex-wrap:wrap;">
                                <button onclick="wallApplyImport(true)" style="background:linear-gradient(135deg,#4caf50,#2e7d32);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:0.82rem;">🔄 合并导入（保留现有，补缺失）</button>
                                <button onclick="wallApplyImport(false)" style="background:linear-gradient(135deg,#f97316,#ea580c);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:0.82rem;">⚠️ 覆盖导入（消息完全替换）</button>
                                <button onclick="document.getElementById('wallBackupDetailModal').remove()" style="background:rgba(255,255,255,0.1);color:white;border:none;padding:8px 14px;border-radius:6px;cursor:pointer;">取消</button>
                            </div>
                        </div></div>`;
                    document.body.insertAdjacentHTML('beforeend', html);
                } catch (e) { alert('读取失败：' + e.message); }
            };
            reader.readAsText(f, 'utf-8');
        }
        window.wallImportOnFile = wallImportOnFile;

        async function wallApplyImport(merge) {
            const bundle = window.__wallImportBundle;
            const mEl = document.getElementById('wallBackupDetailModal'); if (mEl) mEl.remove();
            if (!bundle) return;
            if (!confirm(`⏳ 确定导入该本地备份吗？\n模式：${merge ? '合并（保留当前新消息，补回缺失的）' : '覆盖（用备份完全替换消息）'}\n脚本：按描述匹配写回，缺失的自动重建\n\n⚠️ 这将影响全部用户的需求墙！`)) return;
            wallShowBackupStatus('⏳ 正在导入...', 'loading');
            try {
                const token = getGistToken(); if (!token) throw new Error('无Token');
                // 1) 消息 → 写入"当前"消息 Gist
                let msgStat = '';
                if (Array.isArray(bundle.messages) && bundle.messages.length) {
                    wallShowBackupStatus('⏳ 写入消息...', 'loading');
                    const msgGistId = await wallResolveMessagesGistId();
                    if (!msgGistId) throw new Error('找不到消息 Gist');
                    let finalMsgs;
                    if (merge) {
                        const seen = new Set((wallMessages || []).map(x => x.time + '_' + x.author + '_' + (x.content || '').substring(0, 30)));
                        finalMsgs = (wallMessages || []).slice();
                        let added = 0;
                        bundle.messages.forEach(x => { const k = x.time + '_' + x.author + '_' + (x.content || '').substring(0, 30); if (!seen.has(k)) { finalMsgs.push(x); seen.add(k); added++; } });
                        finalMsgs.sort((a, b) => b.time - a.time);
                        wallShowBackupStatus(`⏳ 合并：补回 ${added} 条，共 ${finalMsgs.length} 条...`, 'loading');
                    } else {
                        finalMsgs = bundle.messages.slice().sort((a, b) => b.time - a.time);
                    }
                    finalMsgs = finalMsgs.slice(0, MAX_MESSAGES);
                    const expN = wallCountExpiredMsgs(finalMsgs);
                    msgStat = `共 ${finalMsgs.length} 条` + (expN ? `（其中 ${expN} 条已过期不显示）` : '');
                    // 🔴 合并写入：messages.json 与 profiles.json 写同一个 Gist，合并成一次 PATCH（省一次 Gist 写）
                    const patchFiles = { 'messages.json': { content: JSON.stringify({ messages: finalMsgs }, null, 2) } };
                    if (bundle.profiles) patchFiles['profiles.json'] = { content: bundle.profiles };
                    const resp = await fetch(`https://api.github.com/gists/${msgGistId}`, { method: 'PATCH', headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` }, body: JSON.stringify({ files: patchFiles }) });
                    if (!resp.ok) throw new Error('消息写入失败');
                }
                // 3) 脚本：按描述匹配现有 Gist → 原文件名覆盖写回；没有 → 重建新 Gist
                let patched = 0, created = 0, skipped = 0;
                if (Array.isArray(bundle.scripts) && bundle.scripts.length) {
                    wallShowBackupStatus('⏳ 匹配脚本 Gist（按描述）...', 'loading');
                    const existing = await wallListScriptGists(token);
                    const byDesc = {}; existing.forEach(g => { byDesc[g.description] = g; });
                    const hdr = { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` };
                    for (const s of bundle.scripts) {
                        if (s.content == null) { skipped++; continue; }
                        const g = byDesc[s.description];
                        // 命中：用该 Gist 现有文件名覆盖（避免新增多余文件）；未命中：用备份里的原名重建
                        const fn = (g && g.fileName) || s.fileName || 'script.txt';
                        let okWrite = false;
                        if (g) {
                            const r = await fetch(`https://api.github.com/gists/${g.id}`, { method: 'PATCH', headers: hdr, body: JSON.stringify({ files: { [fn]: { content: s.content } } }) });
                            if (r.ok) { patched++; okWrite = true; }
                        }
                        if (!okWrite) {
                            const r2 = await fetch('https://api.github.com/gists', { method: 'POST', headers: hdr, body: JSON.stringify({ description: s.description || ('脚本分享: ' + fn), public: false, files: { [fn]: { content: s.content } } }) });
                            if (r2.ok) created++; else skipped++;
                        }
                    }
                }
                wallShowBackupStatus(`✅ 导入完成！消息${merge ? '合并' : '覆盖'}${msgStat ? '：' + msgStat : ''} · 脚本写回 ${patched} · 重建 ${created}${skipped ? ' · 跳过 ' + skipped : ''}，建议刷新页面`, 'success');
                if (typeof fetchMessages === 'function') fetchMessages();
            } catch (e) { wallShowBackupStatus(`❌ 导入失败：${e.message}`, 'error'); }
        }
        window.wallApplyImport = wallApplyImport;
        async function wallDeleteBackup(id) {
            try {
                const token = getGistToken(); if (!token) throw new Error('无Token');
                // 🔴 方案 B：每份备份是独立 Gist，删除=直接 DELETE 整份（含主索引+全部内容），并从索引数组移除
                if (!confirm(`⚠️ 确定删除该备份（整份 Gist）？\n不可恢复！`)) return;
                const dr = await fetch(`https://api.github.com/gists/${id}`, { method: 'DELETE', headers: { 'Authorization': `token ${token}` } });
                if (!dr.ok && dr.status !== 404) throw new Error('删除失败 HTTP ' + dr.status);
                let indexArr = await wallGetBackupIndex();
                indexArr = indexArr.filter(function (e) { return e.id !== id; });
                await wallSaveBackupIndex(indexArr, token);
                wallShowBackupStatus('✅ 已删除该备份', 'success');
                wallLoadBackupList();
            } catch (e) { wallShowBackupStatus(`❌ 删除失败：${e.message}`, 'error'); }
        }
        function wallAdminShowBackup() { const p = document.getElementById('adminPageWallBackup'); if (p) p.style.display = 'block'; const o = document.getElementById('adminPageWallGist'); if (o) o.style.display = 'none'; const adm = document.getElementById('adminMenuSection'); if (adm) adm.style.display = 'none'; try { const c = document.getElementById('wallAutoBackupChk'); if (c) c.checked = localStorage.getItem('wall_auto_backup') === '1'; } catch (e) {} wallLoadBackupList(); }

        // ==================== 需求墙 Gist 文件管理（孤儿扫描+清理，移植自拍卖精细管理）====================
        let _wallGistList = [];
        let _wallScriptUrls = new Set();
        let _wallAuctionsMap = new Map();
        // 构建 auctionId→拍卖 映射（和拍卖行 buildAuctionsMap 同源：总表 room_index.json → 各房间 chatrooms_*.json）
        async function wallBuildAuctionsMap(token) {
            _wallAuctionsMap = new Map();
            try {
                const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                if (!idxResp.ok) return;
                const idxData = await idxResp.json();
                if (!idxData.files || !idxData.files['room_index.json']) return;
                const index = JSON.parse(idxData.files['room_index.json'].content);
                const roomIds = Object.keys(index).filter(k => typeof index[k] === 'string' && index[k].length > 10 && k !== 'messagesGistId' && k !== 'messages');
                for (const roomId of roomIds) {
                    const roomGistId = index[roomId];
                    try {
                        const rResp = await fetch(`https://api.github.com/gists/${roomGistId}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                        if (!rResp.ok) continue;
                        const rData = await rResp.json();
                        const content = rData.files[`chatrooms_${roomId}.json`]?.content;
                        if (!content) continue;
                        const parsed = JSON.parse(content);
                        let auctions = [];
                        if (parsed.rooms && parsed.rooms[roomId]) auctions = parsed.rooms[roomId].auctions || [];
                        else if (parsed.auctions) auctions = parsed.auctions || [];
                        for (const a of auctions) _wallAuctionsMap.set(String(a.id), { ...a, _roomId: roomId });
                    } catch (e) { console.warn('读取房间拍卖失败:', roomId, e); }
                }
            } catch (e) { console.warn('构建拍卖映射失败:', e); }
        }
        async function wallLoadGistManager() {
            const c = document.getElementById('wallGistListContainer'); const cnt = document.getElementById('wallGistCount');
            const token = getGistToken();
            if (!token) { if (c) c.innerHTML = '<div style="color:#ff6b6b;text-align:center;padding:20px;">请先设置Token</div>'; return; }
            if (c) c.innerHTML = '<div style="color:#4ade80;text-align:center;padding:20px;">⏳ 扫描所有Gist...</div>';
            try {
                await wallBuildAuctionsMap(token);
                _wallGistList = []; let page = 1;
                while (page <= 5) {
                    const resp = await fetch(`https://api.github.com/gists?per_page=100&page=${page}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                    if (!resp.ok) break;
                    const gists = await resp.json(); if (gists.length === 0) break;
                    const target = gists.filter(g => g.description && (g.description.includes('脚本分享') || g.description.includes('需求墙消息') || g.description.includes('需求墙数据备份') || g.description.includes('拍卖图片') || g.description.includes('TFJL分享') || g.description.includes('TFJL项目')));
                    _wallGistList = _wallGistList.concat(target);
                    if (gists.length < 100) break; page++;
                }
                _wallScriptUrls = new Set();
                const msgId = await wallResolveMessagesGistId();
                if (msgId) {
                    const mc = await wallReadGistFile(msgId, 'messages.json', token);
                    if (mc) { try { const ms = (JSON.parse(mc).messages) || []; ms.forEach(x => { if (x.scriptUrl) _wallScriptUrls.add(x.scriptUrl); }); } catch (e) {} }
                }
                _wallGistList = _wallGistList.map(g => ({ ...g, _info: wallParseGistInfo(g, msgId) }));
                wallRenderGistList();
            } catch (e) { if (c) c.innerHTML = `<div style="color:#ff6b6b;text-align:center;padding:20px;">❌ ${e.message}</div>`; }
        }
        function wallParseGistInfo(gist, currentMsgId) {
            const info = { type: 'unknown', typeLabel: '⚪ 未知', typeColor: '#999', status: 'unknown', statusLabel: '⚪ 未知', statusColor: '#999', fileName: '', fileSize: 0, description: gist.description || '' };
            const files = Object.keys(gist.files || {}); if (files.length) { info.fileName = files[0]; info.fileSize = gist.files[files[0]].size || 0; }
            const desc = gist.description || '';
            // 🔴 s1.0.109：备份类最高优先级、且永不判孤儿。备份是有用数据（需求墙数据备份），
            // 不能因 description 里夹带「脚本分享/需求墙消息」等字样而误判成脚本/消息孤儿被误删。
            // 命中条件：description 含「需求墙数据备份」或「备份」字样即归为 backup，强制 active。
            if (desc.includes('需求墙数据备份') || desc.includes('备份')) {
                info.type = 'backup'; info.typeLabel = '💾 备份'; info.typeColor = '#a78bfa';
                info.status = 'active'; info.statusLabel = '🟢 备份'; info.statusColor = '#4caf50';
                return info;
            }
            if (desc.includes('脚本分享')) {
                info.type = 'script'; info.typeLabel = '📜 脚本'; info.typeColor = '#ff9800';
                const m = desc.match(/脚本分享:\s*(.+)/); if (m) info.fileName = m[1].trim();
                let ref = false; for (const u of _wallScriptUrls) { if (u.includes(gist.id) || u.includes(encodeURIComponent(info.fileName))) { ref = true; break; } }
                if (ref) { info.status = 'active'; info.statusLabel = '🟢 被引用'; info.statusColor = '#4caf50'; } else { info.status = 'orphan'; info.statusLabel = '🔴 孤儿'; info.statusColor = '#ff6b6b'; }
            } else if (desc.includes('需求墙消息')) {
                info.type = 'message'; info.typeLabel = '📢 消息'; info.typeColor = '#2196f3';
                if (currentMsgId && gist.id === currentMsgId) { info.status = 'current'; info.statusLabel = '🟢 当前使用'; info.statusColor = '#4caf50'; } else { info.status = 'orphan'; info.statusLabel = '🔴 孤儿'; info.statusColor = '#ff6b6b'; }
            } else if (desc.includes('拍卖图片')) {
                info.type = 'image'; info.typeLabel = '🖼️ 图片'; info.typeColor = '#9c27b0';
                const dm = desc.match(/拍卖图片:\s*(\S+)\s*\(房间:\s*(\S+)\)/);
                if (dm) { info.auctionId = dm[1]; info.roomId = dm[2]; }
                const auction = info.auctionId && _wallAuctionsMap.get(String(info.auctionId));
                if (!auction) { info.status = 'orphan'; info.statusLabel = '🔴 孤儿'; info.statusColor = '#ff6b6b'; }
                else {
                    const now = Date.now();
                    const ended = auction.status === 'ended' || (auction.endTime && now >= auction.endTime);
                    if (ended) { info.status = 'ended'; info.statusLabel = '🟡 已结束'; info.statusColor = '#ffb300'; }
                    else { info.status = 'active'; info.statusLabel = '🟢 在售'; info.statusColor = '#4caf50'; }
                }
            } else if (desc.includes('TFJL分享') || desc.includes('TFJL项目')) {
                // 🎫/📦 分享类 Gist（阵容分享 / 项目分享）：无引用概念，永不判孤儿（防止误删）。
                // 过期判定：description 尾部「有效N天」+ gist 创建时间估算；没写天数=永久（旧分享兜底）。
                const isProj = desc.includes('TFJL项目');
                info.type = isProj ? 'projshare' : 'lineup';
                info.typeLabel = isProj ? '📦 项目分享' : '🎫 阵容分享';
                info.typeColor = isProj ? '#ab47bc' : '#00bcd4';
                const cm = desc.match(isProj ? /TFJL项目\s+(\S+)/ : /TFJL分享\s+(\S+)/);
                if (cm) info.shareCode = cm[1];
                // 名称解析：剥离「前缀短码 / 尾部有效期 / 作者+日期段」，项目名内含「·」（无空格）不受影响
                let nm = desc.replace(/^TFJL(?:分享|项目)\s+\S+\s·\s/, '');
                nm = nm.replace(/\s·\s(有效\d+天|永久)(\s·\s加密)?$/, '');
                if (/\d{4}-\d{2}-\d{2}/.test(nm)) nm = nm.replace(/\s·\s\S+\s\d{4}-\d{2}-\d{2}$/, '');
                else nm = nm.split(' · ')[0];
                info.shareName = nm.trim();
                const dm = desc.match(/有效(\d+)天/);
                if (dm) {
                    info.days = parseInt(dm[1], 10);
                    const expAt = new Date(gist.created).getTime() + info.days * 86400000;
                    if (Date.now() > expAt) { info.status = 'expired'; info.statusLabel = '⏰ 已过期可清理'; info.statusColor = '#ff6b6b'; info.expired = true; }
                    else { info.status = 'active'; info.statusLabel = '🟢 分享中·剩' + Math.max(1, Math.ceil((expAt - Date.now()) / 86400000)) + '天'; info.statusColor = '#4caf50'; }
                } else { info.status = 'active'; info.statusLabel = '🟢 分享中·永久'; info.statusColor = '#4caf50'; }
                info.encLock = desc.includes('加密');
            }
            return info;
        }
        function wallRenderGistList() {
            const c = document.getElementById('wallGistListContainer'); const cnt = document.getElementById('wallGistCount');
            if (!c) return;
            const typeF = document.getElementById('wallGistTypeFilter'); const statusF = document.getElementById('wallGistStatusFilter');
            let filtered = _wallGistList;
            if (typeF && typeF.value !== 'all') filtered = filtered.filter(g => g._info.type === typeF.value);
            if (statusF && statusF.value !== 'all') filtered = filtered.filter(g => g._info.status === statusF.value);
            const stats = { script: 0, message: 0, image: 0, backup: 0, lineup: 0, projshare: 0, orphan: 0, active: 0, ended: 0, expired: 0 };
            for (const g of _wallGistList) {
                const t = g._info.type, s = g._info.status;
                if (t === 'script') stats.script++; else if (t === 'message') stats.message++; else if (t === 'image') stats.image++; else if (t === 'backup') stats.backup++; else if (t === 'lineup') stats.lineup++; else if (t === 'projshare') stats.projshare++;
                if (s === 'orphan') stats.orphan++; else if (s === 'expired') stats.expired++; else if (s === 'ended') stats.ended++; else if (s === 'active' || s === 'current') stats.active++;
            }
            if (cnt) cnt.textContent = `(脚本${stats.script} 消息${stats.message} 图片${stats.image} 备份${stats.backup} 阵容${stats.lineup} 项目${stats.projshare} | 孤儿${stats.orphan} 在用${stats.active} 已结束${stats.ended} 过期${stats.expired} | 显示${filtered.length})`;
            // 下拉选项带数量（数量太多数不过来，选择分类时直接看到每类条数）
            if (typeF) {
                const tCounts = { all: _wallGistList.length, script: stats.script, message: stats.message, backup: stats.backup, image: stats.image, lineup: stats.lineup, projshare: stats.projshare };
                const tLabels = { all: '全部类型', script: '📜 脚本', message: '📢 消息', backup: '💾 备份', image: '🖼️ 图片', lineup: '🎫 阵容分享', projshare: '📦 项目分享' };
                Array.from(typeF.options).forEach(o => { const k = o.value; if (tCounts[k] !== undefined) o.textContent = `${tLabels[k]} (${tCounts[k]})`; });
            }
            if (statusF) {
                const sCounts = { all: _wallGistList.length, orphan: stats.orphan, active: stats.active, current: _wallGistList.filter(g => g._info.status === 'current').length, ended: stats.ended, expired: stats.expired };
                const sLabels = { all: '全部状态', orphan: '🔴 孤儿', active: '🟢 被引用/在售', current: '🟢 当前使用', ended: '🟡 已结束', expired: '⏰ 已过期' };
                Array.from(statusF.options).forEach(o => { const k = o.value; if (sCounts[k] !== undefined) o.textContent = `${sLabels[k]} (${sCounts[k]})`; });
            }
            if (!filtered.length) { c.innerHTML = '<div style="color:rgba(255,255,255,0.5);text-align:center;padding:20px;">无符合条件的Gist</div>'; return; }
            const order = { orphan: 0, expired: 1, unknown: 2, active: 3, current: 4, ended: 5 };
            filtered.sort((a, b) => order[a._info.status] - order[b._info.status]);
            let html = '';
            for (const g of filtered) {
                const i = g._info; const sizeKB = (i.fileSize / 1024).toFixed(1);
                const date = new Date(g.created).toLocaleDateString('zh-CN');
                const shareBadge = (i.type === 'lineup' || i.type === 'projshare') ?
                    `<span style="color:#ffd700;font-size:0.75rem;font-family:monospace;background:rgba(255,215,0,0.12);border:1px solid rgba(255,215,0,0.35);border-radius:4px;padding:1px 6px;">${i.shareCode || ''}</span>` +
                    (i.shareName ? `<span style="color:rgba(255,255,255,0.75);font-size:0.78rem;">${i.shareName}</span>` : '') +
                    (i.encLock ? '<span style="font-size:0.75rem;" title="加密分享">🔒</span>' : '') : '';
                html += `<div style="background:rgba(0,0,0,0.2);border-radius:8px;padding:10px;margin-bottom:8px;border-left:3px solid ${i.statusColor};">
                    <div style="display:flex;align-items:center;gap:10px;">
                        <input type="checkbox" class="wall-gist-checkbox" data-gist-id="${g.id}" style="flex-shrink:0;">
                        <div style="flex:1;min-width:0;">
                            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:4px;">
                                <span style="color:${i.typeColor};font-weight:bold;font-size:0.8rem;">${i.typeLabel}</span>
                                <span style="color:${i.statusColor};font-weight:bold;font-size:0.85rem;">${i.statusLabel}</span>
                                <span style="color:rgba(255,255,255,0.4);font-size:0.7rem;">${date}</span>
                                <span style="color:rgba(255,255,255,0.4);font-size:0.7rem;">${sizeKB}KB</span>
                                ${shareBadge}
                            </div>
                            <div style="color:rgba(255,255,255,0.3);font-size:0.7rem;font-family:monospace;">ID: ${g.id.substring(0,12)}… | ${(i.description || '').substring(0,40)}</div>
                        </div>
                        <a href="https://gist.github.com/${g.id}" target="_blank" style="color:#4ade80;font-size:0.75rem;flex-shrink:0;">查看</a>
                    </div></div>`;
            }
            c.innerHTML = html;
        }
        function wallFilterGistList() { wallRenderGistList(); }
        function wallSelectOrphanGists() {
            document.querySelectorAll('.wall-gist-checkbox').forEach(cb => {
                const g = _wallGistList.find(x => x.id === cb.dataset.gistId);
                cb.checked = !!(g && (g._info.status === 'orphan' || g._info.status === 'expired'));
            });
        }
        async function wallDeleteSelectedGists() {
            const cbs = document.querySelectorAll('.wall-gist-checkbox:checked');
            if (!cbs.length) { alert('请先选择要删除的Gist'); return; }
            const ids = Array.from(cbs).map(cb => cb.dataset.gistId);
            if (!confirm(`⚠️ 将删除 ${ids.length} 个选中的Gist，删除后无法恢复！\n\n建议仅删除标记为「🔴 孤儿」或「⏰ 已过期」的Gist（阵容/项目分享不会被判孤儿，可放心按过期清理）。`)) return;
            const token = getGistToken(); if (!token) { alert('请先设置Token'); return; }
            let ok = 0, fail = 0;
            for (let k = 0; k < ids.length; k++) {
                try { const r = await fetch(`https://api.github.com/gists/${ids[k]}`, { method: 'DELETE', headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } }); if (r.ok) ok++; else fail++; } catch (e) { fail++; }
                if (k < ids.length - 1) await new Promise(r => setTimeout(r, 300));
            }
            wallShowGistStatus(`✅ 删除完成：成功 ${ok}，失败 ${fail}`);
            await wallLoadGistManager();
        }
        function wallShowGistStatus(msg) { const el = document.getElementById('wallGistStatus'); if (el) { el.innerHTML = `<div style="color:#ffa500;font-size:0.85rem;text-align:center;padding:10px;">${msg}</div>`; setTimeout(() => { if (el) el.innerHTML = ''; }, 5000); } }
        function wallAdminShowGist() { const p = document.getElementById('adminPageWallGist'); if (p) p.style.display = 'block'; const o = document.getElementById('adminPageWallBackup'); if (o) o.style.display = 'none'; const adm = document.getElementById('adminMenuSection'); if (adm) adm.style.display = 'none'; }

        window.wallBackupAll = wallBackupAll;
        window.wallLoadBackupList = wallLoadBackupList;
        window.wallViewBackupDetail = wallViewBackupDetail;
        window.wallExportBackup = wallExportBackup;
        window.wallDeleteBackup = wallDeleteBackup;
        window.wallRestoreBackup = wallRestoreBackup;
        window.wallAdminShowBackup = wallAdminShowBackup;
        window.wallLoadGistManager = wallLoadGistManager;
        window.wallFilterGistList = wallFilterGistList;
        window.wallSelectOrphanGists = wallSelectOrphanGists;
        window.wallDeleteSelectedGists = wallDeleteSelectedGists;
        window.wallAdminShowGist = wallAdminShowGist;

        // 仅管理员可见还原按钮：URL 带 ?admin=1 或 localStorage.tfjl_admin=1 时才显示
        function showAdminRestoreBtnIfAllowed() {
            try {
                const allowed = (new URLSearchParams(location.search).get('admin') === '1') || (localStorage.getItem('tfjl_admin') === '1');
                const btn = document.getElementById('msgRestoreBtn');
                if (btn) btn.style.display = allowed ? '' : 'none';
            } catch (e) {}
        }


        function updateMsgRefreshBtn() {
            const btn = document.getElementById('msgRefreshBtn');
            if (btn) btn.textContent = '⏳' + msgRefreshCountdown;
        }

        function startMsgCountdown() {
            if (msgCountdownInterval) clearInterval(msgCountdownInterval);
            msgRefreshCountdown = 30;
            updateMsgRefreshBtn();
            msgCountdownInterval = setInterval(() => {
                const wallEl = document.getElementById('messageWall');
                const isOpen = messageWallOpen || (wallEl && wallEl.style.display !== 'none');
                if (!isOpen) return;
                msgRefreshCountdown--;
                updateMsgRefreshBtn();
                if (msgRefreshCountdown <= 0) {
                    msgRefreshCountdown = 30;
                    fetchMessages();
                }
            }, 1000);
        }
        const MAX_SCRIPT_SIZE = 10 * 1024 * 1024;
        const SCRIPT_EXPIRE_DAYS = 10;
        
        // 开门即检：打开需求墙前若未设置昵称，先弹窗设置；已设置则放行。
        // 返回是否允许进入：取消设置（ensureNickname 返回 null）则不允许 → 墙不打开
        async function ensureWallNickBeforeOpen() {
            const hasSet = localStorage.getItem('TFJL_HasSetNick') === 'true';
            const existing = localStorage.getItem('TFJL_UserName');
            if (hasSet && existing) return true;
            const nick = await ensureNickname();
            return !!nick;
        }

        // 🔴 2026-08-31 修复「红点点了还在」：把当前消息列表全部标记已读并持久化。
        // 开墙/关墙都调一次（双保险）；红点右键也调（逃生门，详见 messageWallToggle contextmenu）。
        // 残留根因组合：①开墙时 ensureWallNickBeforeOpen 取消 → return 已读没标 ②localStorage 写入
        // 静默失败(try吞错) 重启后集合回旧值 ③本地IndexedDB旧缓存指纹与远端不一致混入合并列表。
        function _wallMarkAllRead() {
            try {
                wallMessages.forEach(m => wallReadKeys.add(_wallMsgKey(m)));
                localStorage.setItem('TFJL_WallReadKeys', JSON.stringify([...wallReadKeys]));
            } catch (e) {}
        }
        window._wallMarkAllRead = _wallMarkAllRead;

        async function toggleMessageWall() {
            const wall = document.getElementById('messageWall');
            const toggle = document.getElementById('messageWallToggle');
            const min = document.getElementById('messageWallMin');
            const chatToggle = document.getElementById('chatRoomToggle');

            if (messageWallOpen) {
                wall.style.display = 'none';
                min.style.display = 'flex';
                // 需求墙最小化时，拍卖行按钮右移
                if (chatToggle) chatToggle.style.left = '160px';
                messageWallOpen = false;
                _wallMarkAllRead();       // 关墙=看完：双保险再标记一次已读（防开墙时标记失败残留红点）
                updateWallAttention();   // 关闭后重新评估未读提醒
            } else {
                const ok = await ensureWallNickBeforeOpen();
                if (!ok) return; // 强制必须设昵称：取消设置则不开墙，保持入口按钮
                wall.style.display = 'flex';
                min.style.display = 'none';
                toggle.style.display = 'none';
                // 需求墙打开时，拍卖行按钮回到原位置
                if (chatToggle) chatToggle.style.left = '68px';
                messageWallOpen = true;
                updateWallAttention();   // 打开即清除未读提醒(墙已开, 先隐藏红点)
                await fetchMessages();   // 先拉取最新消息, 避免竞态
                // 打开墙 = 标记(最新)所有消息为已读(加入指纹集合并持久化), 必须基于 fetch 后的最新列表
                _wallMarkAllRead();
                updateWallAttention();   // 重新评估, 确保新拉到的消息也标记为已读
                initMessageWallDrag();
                // 打开需求墙时，按本地记忆决定是否同时弹出右侧贡献排行榜
                // （默认开启；用户若曾关闭，则下次开墙也保持关闭——本地记忆，他人默认开启）
                const rp = document.getElementById('reputationPanel');
                const repOpen = localStorage.getItem('TFJL_RepPanelOpen');
                const repShouldOpen = (repOpen === null) ? true : (repOpen === '1');
                if (rp) {
                    rp.style.display = repShouldOpen ? 'flex' : 'none';
                    if (repShouldOpen) { renderReputation(); if (window.syncReputationToWall) window.syncReputationToWall(); }
                }
                // 打开需求墙埋点（记录功能使用频次）
                if (typeof window.__recordFeatureUse === 'function') window.__recordFeatureUse('打开需求墙');
                // 按本地记忆决定是否启动自动滚动（默认开启）
                syncWallScrollBtn();   // 先同步滚动状态到 wallScrollUserPaused + 按钮图标
                const autoScroll = localStorage.getItem('TFJL_WallAutoScroll');
                const shouldScroll = (autoScroll === null) ? true : (autoScroll === '1');
                if (shouldScroll) startMessageScroll(); else pauseMessageScroll();
            }
        }

        // 🔴 2026-08-31 逃生门：右键「📢 需求墙」按钮 = 一键标记全部已读（清红点）。
        // 红点残留的任何根因（标记失败/缓存指纹漂移/昵称弹窗取消没开成墙）都能靠它消掉。
        (function _initWallReadCtx() {
            const bind = function () {
                const t = document.getElementById('messageWallToggle');
                if (!t || t.dataset.readCtx) return;
                t.dataset.readCtx = '1';
                t.title = '左键：需求墙　右键：全部标记已读（清红点）';
                t.addEventListener('contextmenu', function (e) {
                    e.preventDefault();
                    const doMark = function () { _wallMarkAllRead(); updateWallAttention(); };
                    // 消息还没拉过（启动即右键）→ 先拉最新再标，否则标了个寂寞下次又亮
                    if (wallMessages.length === 0 && typeof fetchMessages === 'function') {
                        fetchMessages().then(doMark).catch(doMark);
                    } else doMark();
                    if (typeof showToast === 'function') showToast('✅ 已把当前消息全部标记为已读');
                });
            };
            bind();
            if (document.readyState !== 'complete') document.addEventListener('DOMContentLoaded', bind);
        })();
        window.toggleMessageWall = toggleMessageWall;

        // 未读提醒防抖：被动触发(fetch/升级检查)时延迟评估, 避免刚刷新/升级就立刻闪红点, 给用户缓冲
        let _wallAttnTimer = null;
        // 🔴 2026-08-29 增强：双击刷新/强制刷新后 30 秒内彻底抑制红点(即便有未读也不闪), 30秒后才真评估
        // sessionStorage 在 reload 时保留, perfect reload 抑制标记
        function scheduleWallAttention(delayMs) {
            if (_wallAttnTimer) clearTimeout(_wallAttnTimer);
            _wallAttnTimer = setTimeout(() => {
                _wallAttnTimer = null;
                // 检查 reload 抑制标记
                try {
                    const ts = parseInt(localStorage.getItem('TFJL_ReloadRedDotSuppress') || '0', 10);
                    if (ts && (Date.now() - ts) < 60000) {
                        // 60秒内: 强制清空红点(用户刚刷新过, 给他缓冲, 不立刻闪)
                        const dot = document.getElementById('wallUnreadDot');
                        const toggle = document.getElementById('messageWallToggle');
                        if (dot) { dot.style.display = 'none'; dot.textContent = ''; }
                        if (toggle) toggle.classList.remove('wall-attention');
                        flashTray(false);
                        return;
                    }
                } catch (e) {}
                updateWallAttention();
            }, delayMs || 3000);
        }
        // 未读提醒：墙关闭状态下，若自上次打开后出现了新留言 → 图标 QQ 式闪动 + 红点(未读数)；打开墙即清除
        function updateWallAttention() {
            const toggle = document.getElementById('messageWallToggle');
            const dot = document.getElementById('wallUnreadDot');
            if (!toggle) return;
            if (messageWallOpen) {
                toggle.classList.remove('wall-attention');
                if (dot) dot.style.display = 'none';
                flashTray(false);   // 墙已开 → 停托盘闪动
                return;
            }
            const newCount = wallMessages.filter(m => !wallReadKeys.has(_wallMsgKey(m))).length;
            if (newCount > 0) {
                toggle.classList.add('wall-attention');
                if (dot) { dot.style.display = 'block'; dot.textContent = newCount > 99 ? '99+' : String(newCount); }
                flashTray(true);    // 有未读新消息 → 托盘图标闪动提醒
            } else {
                toggle.classList.remove('wall-attention');
                if (dot) { dot.style.display = 'none'; dot.textContent = ''; }
                flashTray(false);   // 无未读 → 停闪动
            }
        }

        function closeMessageWall() {
            const wall = document.getElementById('messageWall');
            const toggle = document.getElementById('messageWallToggle');
            const chatToggle = document.getElementById('chatRoomToggle');
            wall.style.display = 'none';
            toggle.style.display = 'flex';
            if (chatToggle) chatToggle.style.left = '68px';
            messageWallOpen = false;
            const rp = document.getElementById('reputationPanel');
            if (rp) {
                // 关闭墙时记住声望榜当前是否开着，下次开墙保持一致
                try { localStorage.setItem('TFJL_RepPanelOpen', (rp.style.display === 'flex') ? '1' : '0'); } catch (e) {}
                rp.style.display = 'none'; // 墙关闭时收起贴附的声望榜
            }
            updateWallAttention();
        }
        
        function toggleMessageWallSize() {
            const wall = document.getElementById('messageWall');
            const min = document.getElementById('messageWallToggle');
            const chatToggle = document.getElementById('chatRoomToggle');
            wall.style.display = 'none';
            min.style.display = 'flex';
            if (chatToggle) chatToggle.style.left = '160px';
            messageWallOpen = false;
            const rp = document.getElementById('reputationPanel'); if (rp) rp.style.display = 'none';
        }
        
        async function expandMessageWall() {
            await ensureWallNickBeforeOpen();
            const wall = document.getElementById('messageWall');
            const min = document.getElementById('messageWallMin');
            const toggle = document.getElementById('messageWallToggle');
            const chatToggle = document.getElementById('chatRoomToggle');
            wall.style.display = 'flex';
            min.style.display = 'none';
            toggle.style.display = 'none';
            if (chatToggle) chatToggle.style.left = '68px';
            messageWallOpen = true;
            initMessageWallDrag();
            // 展开需求墙时也默认弹出右侧贡献排行榜
            const rp = document.getElementById('reputationPanel');
            if (rp) { rp.style.display = 'flex'; renderReputation(); if (window.syncReputationToWall) window.syncReputationToWall(); }
        }
        
        function initMessageWallDrag() {
        }
        
        async function fetchMessages() {
            try {
                const token = getGistToken();
                
                // ★ 权威指针：消息Gist ID 优先取索引 room_index.messages（免部署即可迁移Gist），其次硬编码常量
                // ★ 防丢A：本地 IndexedDB 兜底——内存为空时先显示本地缓存，后台再拉远程
                if (wallMessages.length === 0) {
                    try {
                        const dbCache = await loadWallFromDB();
                        if (dbCache && dbCache.length) { wallMessages = dbCache; renderMessages(); scheduleWallAttention(3500); console.log('[消息] 本地缓存兜底显示', dbCache.length, '条'); }
                    } catch (e) {}
                }

                const gistDeleted = localStorage.getItem('messages_gist_deleted') === 'true';
                let messagesGistId = (!gistDeleted && MESSAGES_GIST_ID) ? MESSAGES_GIST_ID : (localStorage.getItem('messages_gist_id') || '');
                // 若未确认删除，从索引拿最新 ID（防止硬编码的旧 Gist 被删后卡死、消息全空）
                if (!gistDeleted) {
                    try {
                        const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': `token ${token}` }) } });
                        if (idxResp.ok) {
                            const idxData = await idxResp.json();
                            const ri = idxData.files && idxData.files['room_index.json'];
                            if (ri && ri.content) {
                                const idx = JSON.parse(ri.content);
                                if (idx.messages) { messagesGistId = idx.messages; localStorage.setItem('messages_gist_id', messagesGistId); }
                            }
                        }
                    } catch (e) { console.warn('[消息] 索引解析失败，用硬编码兜底:', e); }
                }

                // ★ 根治 Actions 备份 404：把当前确定的消息 Gist ID 写回总表 room_index.json.messages
                if (token && messagesGistId && !gistDeleted) {
                    try {
                        const idxResp = await fetch(`https://api.github.com/gists/${GIST_ID}`, { headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` } });
                        if (idxResp.ok) {
                            const idxData = await idxResp.json();
                            const ri = idxData.files && idxData.files['room_index.json'];
                            if (ri && ri.content) {
                                let idxObj = JSON.parse(ri.content);
                                if (idxObj.messages !== messagesGistId) {
                                    idxObj.messages = messagesGistId;
                                    await fetch(`https://api.github.com/gists/${GIST_ID}`, {
                                        method: 'PATCH',
                                        headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': `token ${token}` },
                                        body: JSON.stringify({ files: { 'room_index.json': { content: JSON.stringify(idxObj, null, 2) } } })
                                    });
                                    console.log('[消息] 已写回总表 messages 指针:', messagesGistId);
                                }
                            }
                        }
                    } catch (e) { console.warn('[消息] 写回总表 messages 指针失败:', e); }
                }

                // 如果都没有，从索引文件获取
                if (!messagesGistId) {
                    try {
                        const indexUrl = `https://api.github.com/gists/${GIST_ID}`;
                        const indexResponse = await fetch(indexUrl, {
                            headers: {
                                'Accept': 'application/vnd.github.v3+json',
                                ...(token && { 'Authorization': `token ${token}` })
                            }
                        });
                        
                        if (indexResponse.ok) {
                            const data = await indexResponse.json();
                            if (data.files && data.files['room_index.json'] && data.files['room_index.json'].content) {
                                try {
                                    const indexData = JSON.parse(data.files['room_index.json'].content);
                                    if (indexData['messages']) {
                                        messagesGistId = indexData['messages'];
                                        localStorage.setItem('messages_gist_id', messagesGistId);
                                    }
                                } catch (e) { console.warn('解析索引文件失败:', e); }
                            }
                        }
                    } catch (e) { console.warn('获取索引文件失败:', e); }
                }
                
                if (messagesGistId) {
                    // 从独立 Gist 加载
                    const response = await fetch(`https://api.github.com/gists/${messagesGistId}`, {
                        headers: {
                            'Accept': 'application/vnd.github.v3+json',
                            ...(token && { 'Authorization': `token ${token}` })
                        }
                    });
                    
                    if (response.ok) {
                        const data = await response.json();
                        if (data.files && data.files['messages.json']) {
                            const fileData = data.files['messages.json'];
                            let content = fileData.content;
                            
                            // ★ 处理 truncated：如果内容被截断，使用 raw_url 获取完整内容
                            // 这是消息丢失的常见原因！GitHub API 会截断大文件
                            if (fileData.truncated || !content) {
                                try {
                                    const rawResponse = await fetch(fileData.raw_url, {
                                        headers: {
                                            ...(token && { 'Authorization': `token ${token}` })
                                        }
                                    });
                                    if (rawResponse.ok) {
                                        content = await rawResponse.text();
                                    } else {
                                        console.warn('raw_url 获取失败，状态码:', rawResponse.status);
                                    }
                                } catch (e) { console.warn('raw_url 获取失败:', e); }
                            }
                            
                            if (content) {
                                try {
                                    const parsed = JSON.parse(content);
                                    const fetchedMessages = parsed.messages || [];
                                    
                                    // ★ 关键修复：不要清空已有本地消息，而是合并
                                    // 防止用户刚发的消息因为网络延迟被覆盖
                                    if (wallMessages.length > 0) {
                                        // 使用和 saveMessagesToGist 相同的唯一ID逻辑合并
                                        function getMsgId(m) {
                                            const cs = (m.content || '').substring(0, 30);
                                            return m.time + '_' + m.author + '_' + cs;
                                        }
                                        const fetchedIds = new Set(fetchedMessages.map(getMsgId));
                                        const merged = [...fetchedMessages];
                                        wallMessages.forEach(m => {
                                            if (!fetchedIds.has(getMsgId(m))) merged.push(m);
                                        });
                                        merged.sort((a, b) => b.time - a.time);
                                        wallMessages = merged;
                                    } else {
                                        wallMessages = fetchedMessages;
                                    }
                                    
                                    await saveWallToDB(wallMessages);
                                    renderMessages();
                                    scheduleWallAttention(3500);   // 拉取后延迟评估红点, 避免刚刷新/升级就闪红点
                                    console.log('[消息加载] 成功加载', wallMessages.length, '条消息');
                                    return;
                                } catch (e) { console.warn('解析消息 JSON 失败:', e); }
                            }
                        }
                    } else if (response.status === 404) {
                        // Gist已被删除，标记为失效，允许后续重建
                        console.warn('[消息加载] 消息Gist已删除(404)，标记为失效');
                        localStorage.setItem('messages_gist_deleted', 'true');
                        localStorage.removeItem('messages_gist_id');
                    } else if (response.status === 403) {
                        // 403可能是限流或权限问题，不标记删除
                        console.warn('[消息加载] 消息Gist访问被拒(403)');
                    }
                }
                
                // 如果加载失败，不要清空已有消息，保持原来的消息
                if (wallMessages.length === 0) {
                    wallMessages = [];
                    renderMessages();
                }
            } catch (error) {
                console.warn('获取消息失败:', error);
                const scroller = document.getElementById('messageScroller');
                if (scroller) {
                    scroller.innerHTML = '<div style="color:rgba(255,255,255,0.5);font-size:0.85rem;text-align:center;padding:20px;">暂无消息，快来发布第一条吧！</div>';
                }
            }
        }
        
        // ===================== 分享 / 声望系统 =====================
        // 设计：声望完全由需求墙消息客户端聚合得出（分享者=消息作者），
        // 被复制/被赞计数挂在消息对象上，复用现有 saveMessagesToGist 合并机制持久化，
        // 不引入新 Gist、不引入余额存储，避免并发覆盖与作弊放大。
        const SHARE_REP = 10, COPY_REP = 2, LIKE_REP = 3; // 声望权重（可调）
        const REP_TITLES = [
            { min: 0, name: '萌新' },
            { min: 30, name: '分享先锋' },
            { min: 100, name: '阵容匠人' },
            { min: 300, name: '塔防贤者' },
            { min: 800, name: '宗师' },
            { min: 2000, name: '传说' }
        ];
        function msgAuthor(m) { return m.author || m.nickname || '匿名用户'; }
        function msgTime(m) { return m.time || m.timestamp || 0; }
        function msgContent(m) { return m.content || m.text || ''; }
        function isShareMsg(m) { return !!(m.isShare || m.scriptUrl || m.shareType); }
        // 安全主键：base64(id|time|author)，避免特殊字符破坏 onclick
        function wallMsgKey(m) { return btoa(unescape(encodeURIComponent((m.id || '') + '|' + msgTime(m) + '|' + msgAuthor(m)))); }
        function findWallMsg(b64) {
            try {
                const s = decodeURIComponent(escape(atob(b64)));
                const p = s.split('|'); const id = p[0], t = Number(p[1]), a = p.slice(2).join('|');
                for (const m of wallMessages) { if ((m.id && m.id === id) || (msgTime(m) === t && msgAuthor(m) === a)) return m; }
            } catch (e) {}
            return null;
        }
        function myDeviceId() {
            let d = localStorage.getItem('tfjl_device_id');
            if (!d) { d = 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); localStorage.setItem('tfjl_device_id', d); }
            return d;
        }
        function getMyVote(key) { try { return (JSON.parse(localStorage.getItem('tfjl_share_votes') || '{}'))[key]; } catch (e) { return null; } }
        function setMyVote(key, v) {
            try { const o = JSON.parse(localStorage.getItem('tfjl_share_votes') || '{}'); if (v) o[key] = v; else delete o[key]; localStorage.setItem('tfjl_share_votes', JSON.stringify(o)); } catch (e) {}
        }
        function showFloatToast(msg, bg) {
            const t = document.createElement('div');
            t.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);padding:10px 22px;border-radius:8px;z-index:99999;font-size:0.9rem;box-shadow:0 4px 20px rgba(0,0,0,0.4);animation:fadeInOut 2.4s ease-in-out;color:#1a1a2e;font-weight:bold;';
            t.style.background = bg || 'rgba(74,222,128,0.9)';
            t.textContent = msg; document.body.appendChild(t); setTimeout(() => t.remove(), 2400);
        }
        let _repSaveTimer = null;
        function saveWallDebounced() {
            if (_repSaveTimer) return;
            _repSaveTimer = setTimeout(() => { _repSaveTimer = null; saveMessagesToGist().catch(() => {}); }, 2500);
        }
        // 复制分享内容（站内复制按钮 = 可捕获的"被下载"事件，owner 加声望）
        // 取回脚本明文：公开 raw 优先，失败回退 Gist API（支持私有 Gist）
        async function fetchScriptPlainText(url) {
            let content = null;
            try { const resp = await fetch(url); if (resp.ok) content = await resp.text(); } catch (e) {}
            if (content === null) {
                const token = getGistToken();
                const gistMatch = url.match(/gist\.githubusercontent\.com\/[^/]+\/([a-f0-9]+)/i) || url.match(/gist\.github\.com\/[^/]+\/([a-f0-9]+)/i);
                if (gistMatch && token) {
                    try {
                        const apiResp = await fetch(`https://api.github.com/gists/${gistMatch[1]}`, {
                            headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` }
                        });
                        if (apiResp.ok) {
                            const gistData = await apiResp.json();
                            const fileName = decodeURIComponent((url.split('/').pop() || '').split('?')[0]);
                            let c = null;
                            for (const f of Object.values(gistData.files)) { if (f.filename === fileName || url.includes(f.filename)) { c = f.content; break; } }
                            if (c === null && gistData.files) c = Object.values(gistData.files)[0].content;
                            content = c;
                        }
                    } catch (e) { console.warn('API方式获取Gist失败:', e); }
                }
            }
            if (content === null) throw new Error('获取文件失败，可能需要登录或文件不存在');
            return content;
        }
        async function onShareCopy(b64) {
            const m = findWallMsg(b64); if (!m) return;
            let text;
            if (m.scriptUrl) {
                // 只复制脚本内容本身（不复制链接）；加密的先要密码解密再拷明文
                try {
                    let raw = await fetchScriptPlainText(m.scriptUrl);
                    if (m.isEncrypted) {
                        const pwd = await askDecryptPasswordAsync('该分享已加密，请输入密码以复制明文：');
                        if (!pwd) { showFloatToast('🔒 需密码才能复制明文', 'rgba(255,193,7,0.9)'); return; }
                        const dec = await decryptContent(raw, pwd);
                        if (dec === null) { alert('❌ 解密失败，可能是密码不正确或文件已损坏'); return; }
                        raw = dec;
                    }
                    text = raw;
                } catch (e) {
                    text = msgContent(m) + (m.scriptUrl ? '\n' + m.scriptUrl : ''); // 网络失败才回退带链接
                }
            } else {
                text = msgContent(m);
            }
            try { await navigator.clipboard.writeText(text); } catch (e) {
                const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select();
                try { document.execCommand('copy'); } catch (_) {} ta.remove();
            }
            const me = localStorage.getItem('TFJL_UserName') || '';
            const owner = msgAuthor(m);
            const day = new Date().toISOString().slice(0, 10);
            const key = myDeviceId() + '|' + b64 + '|' + day;
            let log = []; try { log = JSON.parse(localStorage.getItem('tfjl_copy_log') || '[]'); } catch (e) {}
            if (!log.includes(key) && owner.toLowerCase() !== me.toLowerCase()) {
                log.push(key); if (log.length > 200) log = log.slice(-200);
                localStorage.setItem('tfjl_copy_log', JSON.stringify(log));
                m.copyCount = (m.copyCount || 0) + 1;
                saveWallDebounced(); renderMessages();
                showFloatToast('📋 已复制内容，感谢支持「' + owner + '」的分享！', 'rgba(79,195,247,0.9)');
            } else {
                showFloatToast('📋 已复制内容', 'rgba(79,195,247,0.9)');
            }
        }
        async function onShareLike(b64) {
            const m = findWallMsg(b64); if (!m) return;
            const cur = getMyVote(b64);
            if (cur === 'like') { m.likes = (m.likes || 0) - 1; setMyVote(b64, null); }
            else { if (cur === 'dislike') m.dislikes = (m.dislikes || 0) - 1; m.likes = (m.likes || 0) + 1; setMyVote(b64, 'like'); }
            saveWallDebounced(); renderMessages();
        }
        async function onShareDislike(b64) {
            const m = findWallMsg(b64); if (!m) return;
            const cur = getMyVote(b64);
            if (cur === 'dislike') { m.dislikes = (m.dislikes || 0) - 1; setMyVote(b64, null); }
            else { if (cur === 'like') m.likes = (m.likes || 0) - 1; m.dislikes = (m.dislikes || 0) + 1; setMyVote(b64, 'dislike'); }
            saveWallDebounced(); renderMessages();
        }
        function renderShareActions(m, b64) {
            const myVote = getMyVote(b64);
            const likeCls = myVote === 'like' ? 'color:#ffd700;' : 'color:#4fc3f7;';
            const disCls = myVote === 'dislike' ? 'color:#ff6b6b;' : 'color:rgba(255,255,255,0.5);';
            const copyLabel = m.isEncrypted ? '📋 复制明文' : '📋 复制';
            const copyTitle = m.isEncrypted ? '该分享已加密，点击输入密码后复制明文' : '复制分享内容（主人将获得声望）';
            // 项目分享：卡片内容区只提供「智能导入」，此处隐藏通用"复制"按钮（不允许复制项目 JSON 全文）
            const copyBtn = (m.shareType === 'project')
                ? ''
                : `<a href="javascript:void(0)" onclick="onShareCopy('${b64}')" title="${copyTitle}" style="color:#4fc3f7;text-decoration:none;cursor:pointer;background:rgba(79,195,247,0.12);padding:3px 10px;border-radius:5px;">${copyLabel}</a>`;
            return `<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:8px;font-size:0.78rem;align-items:center;">
                ${copyBtn}
                <a href="javascript:void(0)" onclick="onShareLike('${b64}')" style="${likeCls}text-decoration:none;cursor:pointer;background:rgba(255,215,0,0.1);padding:3px 10px;border-radius:5px;">👍 ${m.likes || 0}</a>
                <a href="javascript:void(0)" onclick="onShareDislike('${b64}')" style="${disCls}text-decoration:none;cursor:pointer;background:rgba(255,107,107,0.1);padding:3px 10px;border-radius:5px;">👎 ${m.dislikes || 0}</a>
                <span style="color:rgba(255,255,255,0.4);">📥 被复制 ${m.copyCount || 0}</span>
                <span style="color:rgba(255,215,0,0.7);">🏅 声望 +${SHARE_REP + (m.copyCount || 0) * COPY_REP + (m.likes || 0) * LIKE_REP}</span>
            </div>`;
        }
        // 剥离任何可见文本里的 GitHub 下载地址（需求墙/公告都不引导用户去 GitHub 扒内容）
        function stripGithubUrls(text) {
            return (text || '').replace(/https?:\/\/(raw\.)?githubusercontent\.com\S+/gi, '')
                                  .replace(/https?:\/\/gist\.github\.com\S+/gi, '')
                                  .replace(/https?:\/\/github\.com\S+/gi, '');
        }
        // 取分享消息在全局脚本下载统计中的下载次数（下载按钮 recordDownload 写入 counterData.script_downloads，按文件名索引）
        function _globalDlForMsg(m) {
            if (!m.scriptUrl || !counterData || !counterData.script_downloads) return 0;
            let last;
            try { const u = new URL(m.scriptUrl); last = u.pathname.split('/').pop(); }
            catch (e) { last = m.scriptUrl.split('/').pop(); }
            if (!last || last === 'raw') return 0;
            last = decodeURIComponent(last);
            return counterData.script_downloads[last] || 0;
        }
        // 聚合所有分享者为声望榜（客户端计算，零存储）
        function computeReputation() {
            const ANON = ['匿名用户', '匿名', 'anonymous', ''];
            const map = {};
            for (const m of wallMessages) {
                if (!isShareMsg(m)) continue;
                const a = msgAuthor(m); if (!a) continue;
                if (ANON.includes(a) || a.toLowerCase() === '匿名用户') continue; // 排除无昵称的匿名用户
                if (!map[a]) map[a] = { rep: 0, shares: 0, copies: 0, likes: 0, previews: 0, downloads: 0, firstShare: msgTime(m) };
                const e = map[a];
                // 下载 = 站内复制（用户视角的“下载”）+ 实际下载按钮次数（含下载到老马）；复制与下载同义，合并计为下载
                e.downloads += (m.copyCount || 0) + _globalDlForMsg(m);
                e.shares++; e.copies += (m.copyCount || 0); e.likes += (m.likes || 0); e.previews += (m.previewCount || 0);
                e.firstShare = Math.min(e.firstShare, msgTime(m));
            }
            for (const a in map) { const e = map[a]; e.rep = e.shares * SHARE_REP + e.copies * COPY_REP + e.likes * LIKE_REP; }
            return map;
        }
        function getTitle(rep) {
            let t = REP_TITLES[0], idx = 0;
            for (let i = 0; i < REP_TITLES.length; i++) { if (rep >= REP_TITLES[i].min) { t = REP_TITLES[i]; idx = i; } }
            const next = REP_TITLES[idx + 1];
            let progress = 1, nextRep = 0;
            if (next) { nextRep = next.min; progress = Math.max(0, Math.min(1, (rep - t.min) / (nextRep - t.min))); }
            return { name: t.name, nextName: next ? next.name : null, nextRep, progress };
        }
        // 成就徽章定义（全部基于 wallMessages 客户端聚合，零新增存储）
        const BADGE_DEFS = [
            { id: 'first', icon: '🌱', name: '初来乍到', desc: '发布第 1 个分享', test: e => e.shares >= 1 },
            { id: 'sharer', icon: '📣', name: '分享达人', desc: '累计分享 ≥ 10 个', test: e => e.shares >= 10 },
            { id: 'copied', icon: '📋', name: '被复制破百', desc: '作品被复制 ≥ 100 次', test: e => e.copies >= 100 },
            { id: 'master', icon: '💎', name: '声望宗师', desc: '声望 ≥ 800', test: e => e.rep >= 800 },
            { id: 'week1', icon: '👑', name: '周榜第一', desc: '近 7 天声望榜第一', test: (e, ctx) => ctx && ctx.isWeekTop1 },
            { id: 'streak', icon: '🔥', name: '连续分享7天', desc: '分享跨越 ≥ 7 个不同日期', test: e => e.activeDays >= 7 },
            { id: 'allstar', icon: '🏆', name: '十项全能', desc: '集齐以上所有徽章', test: (e, ctx) => ctx && ctx.earnedCount >= 6 }
        ];
        // 计算某个昵称获得的徽章；repMap 可选（外部已算则复用）
        function computeBadges(nick, repMap) {
            const map = repMap || computeReputation();
            const e = map[nick] || { rep: 0, shares: 0, copies: 0, likes: 0, previews: 0, firstShare: 0, activeDays: 0 };
            // 连续分享天数：求该昵称所有分享消息的去重日期数（跨天即累计）
            if (!e.activeDays) {
                const days = new Set();
                for (const m of wallMessages) { if (isShareMsg(m) && msgAuthor(m) === nick) { const d = new Date(msgTime(m)); days.add(d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate()); } }
                e.activeDays = days.size;
            }
            // 周榜第一判定
            const w = Date.now() - 7 * 864e5;
            const weekArr = Object.keys(map).map(n => ({ nick: n, rep: (map[n].firstShare >= w ? map[n].rep : -1) })).sort((a, b) => b.rep - a.rep);
            const isWeekTop1 = weekArr.length > 0 && weekArr[0].nick === nick && weekArr[0].rep >= 0;
            const ctx = { isWeekTop1, earnedCount: 0 };
            const badges = BADGE_DEFS.map(b => { const ok = !!b.test(e, ctx); return { ...b, earned: ok }; });
            ctx.earnedCount = badges.filter(b => b.earned).length;
            // 十项全能依赖 earnedCount，需二次计算
            const allstar = badges.find(b => b.id === 'allstar');
            if (allstar) allstar.earned = ctx.earnedCount >= 6;
            return { badges, earnedCount: ctx.earnedCount, total: BADGE_DEFS.length };
        }
        // 渲染徽章墙 HTML（earned 高亮，未得灰显+条件）
        function renderBadgesHtml(nick, repMap) {
            const { badges, earnedCount, total } = computeBadges(nick, repMap);
            const items = badges.map(b =>
                `<div title="${escapeHtml(b.desc)}" style="display:flex;flex-direction:column;align-items:center;gap:2px;padding:8px 6px;border-radius:9px;background:${b.earned ? 'rgba(255,215,0,0.14)' : 'rgba(255,255,255,0.04)'};border:1px solid ${b.earned ? 'rgba(255,215,0,0.5)' : 'rgba(255,255,255,0.08)'};flex:1;min-width:62px;opacity:${b.earned ? '1' : '0.55'};">
                    <span style="font-size:1.5rem;filter:${b.earned ? 'none' : 'grayscale(1)'};">${b.icon}</span>
                    <span style="font-size:0.68rem;color:${b.earned ? '#ffd700' : 'rgba(255,255,255,0.5)'};font-weight:${b.earned ? 'bold' : 'normal'};text-align:center;line-height:1.1;">${escapeHtml(b.name)}</span>
                </div>`).join('');
            return `<div style="margin-bottom:10px;">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
                    <span style="color:rgba(255,255,255,0.7);font-size:0.78rem;">🎖 成就徽章</span>
                    <span style="color:#ffd700;font-size:0.78rem;font-weight:bold;">${earnedCount}/${total}</span>
                </div>
                <div style="display:flex;flex-wrap:wrap;gap:6px;">${items}</div>
            </div>`;
        }
        // 在线实时"声望上涨"浮条：对比上次看到的自己声望
        function checkReputationGain() {
            const me = localStorage.getItem('TFJL_UserName') || '';
            if (!me) return;
            const repMap = computeReputation();
            const rep = repMap[me] ? repMap[me].rep : 0;
            const last = Number(localStorage.getItem('tfjl_my_rep_last') || '0');
            if (rep > last && last > 0) showFloatToast('🎉 你的声望 +' + (rep - last) + '！当前 ' + rep, 'rgba(255,215,0,0.92)');
            localStorage.setItem('tfjl_my_rep_last', String(rep));
        }
        // 贡献排行榜面板
        let _repTab = 'rep';
        function toggleReputationPanel() {
            const p = document.getElementById('reputationPanel');
            if (!p) return;
            const willOpen = (p.style.display !== 'flex');
            p.style.display = willOpen ? 'flex' : 'none';
            // 记住声望榜开关状态（本地，他人默认开启）
            try { localStorage.setItem('TFJL_RepPanelOpen', willOpen ? '1' : '0'); } catch (e) {}
            if (willOpen) { if (typeof window.__recordFeatureUse === 'function') window.__recordFeatureUse('声望查询'); renderReputation(); if (window.syncReputationToWall) window.syncReputationToWall(); }
        }
        // 需求墙自动滚动开关（本地记忆；默认开启，关闭后一直关闭，可自由切换）
        function toggleWallAutoScroll() {
            const btn = document.getElementById('wallScrollToggleBtn');
            const cur = localStorage.getItem('TFJL_WallAutoScroll');
            const on = !((cur === null) ? true : (cur === '1'));   // 翻转
            wallScrollUserPaused = !on;   // 记录用户主动暂停状态
            try { localStorage.setItem('TFJL_WallAutoScroll', on ? '1' : '0'); } catch (e) {}
            if (btn) { btn.textContent = on ? '🔄' : '⏸'; btn.style.color = on ? '#4fc3f7' : '#94a3b8'; btn.title = on ? '自动滚动：开（点击停止）' : '自动滚动：停（点击恢复）'; }
            if (on) startMessageScroll(); else pauseMessageScroll();
        }
        // 打开墙时同步滚动按钮图标/状态到本地记忆状态
        function syncWallScrollBtn() {
            const btn = document.getElementById('wallScrollToggleBtn');
            const cur = localStorage.getItem('TFJL_WallAutoScroll');
            const on = (cur === null) ? true : (cur === '1');
            wallScrollUserPaused = !on;
            if (!btn) return;
            btn.textContent = on ? '🔄' : '⏸';
            btn.style.color = on ? '#4fc3f7' : '#94a3b8';
            btn.title = on ? '自动滚动：开（点击停止）' : '自动滚动：停（点击恢复）';
        }
        function setRepTab(tab) {
            _repTab = tab;
            document.querySelectorAll('.rep-tab').forEach(el => { el.classList.toggle('active', el.getAttribute('data-tab') === tab); });
            renderReputation();
        }
        function renderReputation() {
            const repMap = computeReputation();
            const arr = Object.keys(repMap).map(n => ({ nick: n, ...repMap[n] }));
            let list = [];
            if (_repTab === 'rep') list = arr.slice().sort((a, b) => b.rep - a.rep);
            else if (_repTab === 'share') list = arr.slice().sort((a, b) => b.shares - a.shares);
            else if (_repTab === 'copy') list = arr.slice().sort((a, b) => b.copies - a.copies);
            else if (_repTab === 'like') list = arr.slice().sort((a, b) => b.likes - a.likes);
            else if (_repTab === 'preview') list = arr.slice().sort((a, b) => b.previews - a.previews);
            else if (_repTab === 'download') list = arr.slice().sort((a, b) => b.downloads - a.downloads);
            else if (_repTab === 'week') { const w = Date.now() - 7 * 864e5; list = arr.filter(a => a.firstShare >= w).sort((a, b) => b.rep - a.rep); }
            else if (_repTab === 'newcomer') { const w = Date.now() - 7 * 864e5; list = arr.filter(a => a.firstShare >= w).sort((a, b) => b.shares - a.shares); }
            else if (_repTab === 'badge') {
                // 徽章榜：按已得徽章数降序，再按声望
                const repMapB = repMap;
                list = arr.map(a => { const bd = computeBadges(a.nick, repMapB); return { ...a, _badges: bd.badges, _earned: bd.earnedCount }; })
                          .sort((a, b) => b._earned - a._earned || b.rep - a.rep);
            }
            const top = list.slice(0, 30);
            const medal = i => i === 0 ? '👑' : i === 1 ? '🥈' : i === 2 ? '🥉' : (i + 1) + '.';
            const valOf = a => _repTab === 'share' ? a.shares + ' 分享' : _repTab === 'copy' ? a.copies + ' 被复制' : _repTab === 'like' ? a.likes + ' 赞' : _repTab === 'preview' ? a.previews + ' 预览' : _repTab === 'download' ? a.downloads + ' 下载' : a.rep + ' 声望';
            const el = document.getElementById('reputationList');
            if (!el) return;
            if (_repTab === 'badge') {
                el.innerHTML = top.length ? top.map((a, i) =>
                    `<div onclick="openContributionCard('${encodeURIComponent(a.nick)}')" style="padding:8px 9px;border-radius:7px;cursor:pointer;${i < 3 ? 'background:rgba(255,215,0,0.12);' : ''};margin-bottom:5px;">
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                            <span>${medal(i)} <span style="color:#ffd700;">${escapeHtml(a.nick)}</span></span>
                            <span style="color:#ffd700;font-size:0.78rem;font-weight:bold;">🎖 ${a._earned}/${BADGE_DEFS.length}</span>
                        </div>
                        <div style="display:flex;gap:3px;flex-wrap:wrap;">${a._badges.map(b => `<span title="${escapeHtml(b.desc)}" style="font-size:1.05rem;filter:${b.earned ? 'none' : 'grayscale(1)'};opacity:${b.earned ? '1' : '0.4'};">${b.icon}</span>`).join('')}</div>
                    </div>`).join('') : '<div style="color:rgba(255,255,255,0.5);text-align:center;padding:24px;">暂无分享数据，去需求墙分享第一个脚本吧！</div>';
                return;
            }
            el.innerHTML = top.length ? top.map((a, i) =>
                `<div onclick="openContributionCard('${encodeURIComponent(a.nick)}')" style="display:flex;justify-content:space-between;align-items:center;padding:7px 9px;border-radius:7px;cursor:pointer;${i < 3 ? 'background:rgba(255,215,0,0.12);' : ''}">
                    <span>${medal(i)} <span style="color:#ffd700;">${escapeHtml(a.nick)}</span> <span style="color:rgba(255,255,255,0.5);font-size:0.7rem;">[${getTitle(a.rep).name}]</span></span>
                    <span style="color:#4ecdc4;font-size:0.8rem;">${valOf(a)}</span>
                </div>`).join('') : '<div style="color:rgba(255,255,255,0.5);text-align:center;padding:24px;">暂无分享数据，去需求墙分享第一个脚本吧！</div>';
        }
        // 个人贡献主页（点昵称打开）
        // 去掉所有 http(s) 链接，只保留用户发出的纯文本（用于个人主页展示分享内容）
        function stripAllUrls(t) { return (t || '').replace(/https?:\/\/\S+/gi, '').replace(/[ \t]*\n[ \t]*/g, '\n').replace(/\n{2,}/g, '\n').trim(); }
        let _contribData = null;
        function _normNick(n) { return (n || '').trim().toLowerCase(); }
        // ====== 全网个人资料（心情/说明，支持公开/仅自己）======
        // 本机兜底：localStorage（key=规范化昵称），用于本人即时查看与离线
        function getProfile(nick) {
            try {
                const norm = localStorage.getItem('tfjl_profile_' + _normNick(nick));
                const raw = localStorage.getItem('tfjl_profile_' + nick);
                const s = norm || raw || 'null';
                const o = JSON.parse(s) || {};
                return { mood: o.mood || '', bio: o.bio || '', visibility: o.visibility || 'public' };
            } catch (e) { return { mood: '', bio: '', visibility: 'public' }; }
        }
        function setLocalProfile(nick, mood, bio, visibility) {
            try { localStorage.setItem('tfjl_profile_' + _normNick(nick), JSON.stringify({ mood: mood || '', bio: bio || '', visibility: visibility || 'public' })); } catch (e) {}
        }
        // 云端 profiles 存储：复用「用户可写」的需求墙 Gist（MESSAGES_GIST_ID），独立文件 profiles.json（不影响 messages.json）
        const PROFILES_GIST_ID = MESSAGES_GIST_ID;
        const PROFILES_FILE = 'profiles.json';
        async function fetchProfilesGist() {
            try {
                const token = getGistToken();
                const resp = await fetch('https://api.github.com/gists/' + PROFILES_GIST_ID, {
                    headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': 'token ' + token }) }
                });
                if (!resp.ok) return {};
                const data = await resp.json();
                const f = data.files && data.files[PROFILES_FILE];
                if (!f || !f.content) return {};
                return JSON.parse(f.content) || {};
            } catch (e) { return {}; }
        }
        async function saveProfileToGist(normNick, payload) {
            try {
                const token = getGistToken();
                if (!token) return;
                // 先读云端现有，合并后写回（防多人并发覆盖）
                let current = {};
                try {
                    const r = await fetch('https://api.github.com/gists/' + PROFILES_GIST_ID, {
                        headers: { 'Accept': 'application/vnd.github.v3+json', ...(token && { 'Authorization': 'token ' + token }) }
                    });
                    if (r.ok) { const d = await r.json(); const f = d.files && d.files[PROFILES_FILE]; if (f && f.content) current = JSON.parse(f.content) || {}; }
                } catch (e) {}
                current[normNick] = payload;
                const content = JSON.stringify(current);
                const bodyObj = {}; bodyObj[PROFILES_FILE] = { content: content };
                const resp = await fetch('https://api.github.com/gists/' + PROFILES_GIST_ID, {
                    method: 'PATCH',
                    headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', ...(token && { 'Authorization': 'token ' + token }) },
                    body: JSON.stringify({ files: bodyObj })
                });
                if (!resp.ok) console.warn('[资料] 云端保存失败', resp.status);
            } catch (e) { console.warn('[资料] 云端保存异常', e); }
        }
        // 保存资料：本机 + 云端（公开存明文；仅自己只存标记不存明文）
        async function saveProfile(nick, mood, bio, visibility) {
            const vis = visibility === 'private' ? 'private' : 'public';
            setLocalProfile(nick, mood, bio, vis);
            const norm = _normNick(nick);
            if (vis === 'public') {
                await saveProfileToGist(norm, { mood: mood || '', bio: bio || '', visibility: 'public', updatedAt: Date.now() });
            } else {
                // 仅自己：云端不存明文，只留标记；本机保留明文供自己查看
                await saveProfileToGist(norm, { visibility: 'private', updatedAt: Date.now() });
            }
        }
        window.saveProfile = saveProfile;
        // 复制某条分享的内容
        function contribCopyContent(i) {
            const item = _contribData && _contribData.shares[i]; if (!item) return;
            const text = item.content || '';
            try { navigator.clipboard.writeText(text); } catch (e) { const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (_) {} ta.remove(); }
            showFloatToast('📋 已复制内容', 'rgba(79,195,247,0.9)');
        }
        // 下载该用户全部脚本
        async function contribDownloadAll() {
            if (!_contribData) return;
            const scripts = _contribData.shares.filter(s => s.scriptUrl);
            if (!scripts.length) { showFloatToast('该用户暂无可下载的脚本'); return; }
            showFloatToast('📥 正在下载全部脚本（' + scripts.length + '）', 'rgba(79,195,247,0.9)');
            for (const s of scripts) { try { await downloadScript(s.scriptUrl, s.isEncrypted, s.passwordHash); } catch (e) {} }
        }
        // 渲染个性资料（心情/说明）自己可编辑；他人异步从云端拉取
        async function renderContribProfile(nick) {
            const wrap = document.getElementById('contribProfileEdit'); if (!wrap) return;
            wrap.dataset.editing = '0';
            const me = localStorage.getItem('TFJL_UserName') || '';
            const isSelf = me && me.toLowerCase() === nick.toLowerCase();
            const editBtn = isSelf ? `<button onclick="contribToggleEditProfile()" style="background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);color:#fff;border-radius:5px;padding:3px 10px;font-size:0.72rem;cursor:pointer;margin-left:auto;">✏️ 编辑</button>` : '';
            const header = `<div style="display:flex;align-items:center;margin-bottom:6px;"><span style="color:rgba(255,255,255,0.6);font-size:0.78rem;">💬 个性资料</span>${editBtn}</div>`;
            if (isSelf) {
                // 本人：直接读本机
                const p = getProfile(nick);
                const has = p.mood || p.bio;
                const visTag = p.visibility === 'private' ? '🔒 仅自己' : '🌐 公开';
                const body = has
                    ? `<div style="color:#ffd700;font-size:0.95rem;margin-bottom:4px;">💭 ${escapeHtml(p.mood)}</div>` + (p.bio ? `<div style="color:rgba(255,255,255,0.75);font-size:0.8rem;line-height:1.4;">${escapeHtml(p.bio)}</div>` : '') + `<div style="color:rgba(255,255,255,0.4);font-size:0.68rem;margin-top:4px;">${visTag}</div>`
                    : `<div style="color:rgba(255,255,255,0.4);font-size:0.78rem;">（点「编辑」设置你的心情 / 个人说明）</div>`;
                wrap.innerHTML = header + body;
                return;
            }
            // 他人：异步拉云端
            wrap.innerHTML = header + `<div style="color:rgba(255,255,255,0.4);font-size:0.78rem;">加载中…</div>`;
            try {
                const all = await fetchProfilesGist();
                const p = all[_normNick(nick)] || {};
                if (p.visibility === 'public' && (p.mood || p.bio)) {
                    wrap.innerHTML = header + `<div style="color:#ffd700;font-size:0.95rem;margin-bottom:4px;">💭 ${escapeHtml(p.mood)}</div>` + (p.bio ? `<div style="color:rgba(255,255,255,0.75);font-size:0.8rem;line-height:1.4;">${escapeHtml(p.bio)}</div>` : '') + `<div style="color:rgba(255,255,255,0.4);font-size:0.68rem;margin-top:4px;">🌐 公开</div>`;
                } else {
                    wrap.innerHTML = header + `<div style="color:rgba(255,255,255,0.4);font-size:0.78rem;">（该用户未公开个性资料）</div>`;
                }
            } catch (e) {
                wrap.innerHTML = header + `<div style="color:rgba(255,255,255,0.4);font-size:0.78rem;">（资料加载失败）</div>`;
            }
        }
        function contribToggleEditProfile() {
            const nick = _contribData ? _contribData.nick : '';
            const wrap = document.getElementById('contribProfileEdit'); if (!wrap) return;
            const p = getProfile(nick);
            if (wrap.dataset.editing === '1') {
                const mood = document.getElementById('contribMoodInput').value.trim();
                const bio = document.getElementById('contribBioInput').value.trim();
                const visRadio = document.querySelector('input[name="contribVis"]:checked');
                const vis = (visRadio && visRadio.value) || 'public';
                saveProfile(nick, mood, bio, vis);
                wrap.dataset.editing = '0'; renderContribProfile(nick);
                showFloatToast('✅ 已保存（' + (vis === 'private' ? '仅自己可见' : '全网公开') + '）', 'rgba(255,215,0,0.9)');
            } else {
                wrap.dataset.editing = '1';
                const vis = p.visibility === 'private' ? 'private' : 'public';
                wrap.innerHTML = `
                    <div style="display:flex;align-items:center;margin-bottom:6px;"><span style="color:rgba(255,255,255,0.6);font-size:0.78rem;">💬 个性资料</span><button onclick="contribToggleEditProfile()" style="background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);color:#fff;border-radius:5px;padding:3px 10px;font-size:0.72rem;cursor:pointer;margin-left:auto;">✏️ 编辑</button></div>
                    <input id="contribMoodInput" placeholder="心情（一句话，最多30字）" value="${escapeHtml(p.mood)}" maxlength="30" style="width:100%;background:rgba(255,255,255,0.1);border:1px solid rgba(255,215,0,0.4);border-radius:6px;padding:6px 10px;color:#ffd700;font-size:0.82rem;outline:none;margin-bottom:6px;">
                    <textarea id="contribBioInput" placeholder="个人说明（最多120字）" maxlength="120" rows="2" style="width:100%;background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);border-radius:6px;padding:6px 10px;color:#fff;font-size:0.8rem;outline:none;resize:vertical;">${escapeHtml(p.bio)}</textarea>
                    <div style="display:flex;gap:12px;align-items:center;margin:6px 0;">
                        <label style="color:rgba(255,255,255,0.7);font-size:0.74rem;cursor:pointer;"><input type="radio" name="contribVis" value="public" ${vis === 'public' ? 'checked' : ''}> 🌐 公开</label>
                        <label style="color:rgba(255,255,255,0.7);font-size:0.74rem;cursor:pointer;"><input type="radio" name="contribVis" value="private" ${vis === 'private' ? 'checked' : ''}> 🔒 仅自己</label>
                    </div>
                    <button onclick="contribToggleEditProfile()" style="margin-top:2px;background:linear-gradient(135deg,#ffd700,#ff6b6b);color:#1a1a2e;border:none;padding:5px 16px;border-radius:5px;font-size:0.8rem;cursor:pointer;font-weight:bold;">💾 保存</button>`;
            }
        }
        window.contribCopyContent = contribCopyContent;
        window.contribDownloadAll = contribDownloadAll;
        window.contribToggleEditProfile = contribToggleEditProfile;
        window.renderContribProfile = renderContribProfile;

        // ========== 右上角个人中心：点开即本人贡献主页（可编辑个性资料） ==========
        function openMyProfile() {
            const nick = localStorage.getItem('TFJL_UserName') || '匿名用户';
            if (typeof openContributionCard === 'function') openContributionCard(encodeURIComponent(nick));
            else if (window.openContributionCard) window.openContributionCard(encodeURIComponent(nick));
            else alert('个人资料功能尚未就绪');
        }
        window.openMyProfile = openMyProfile;

        // 同步右上角个人中心昵称标签
        function refreshProfileLabel() {
            const el = document.getElementById('profileNickLabel');
            if (!el) return;
            const nick = localStorage.getItem('TFJL_UserName') || '游客';
            el.textContent = nick;
        }
        window.refreshProfileLabel = refreshProfileLabel;

        // ========== 登录打卡记录（本地 localStorage + 公共 Gist 跨设备汇总） ==========
        // 每次成功进入主界面记录一次：{ nick, ts }
        function recordLoginEvent() {
            if (typeof window.__recordFeatureUse === 'function') window.__recordFeatureUse('登录打卡');
            try {
                const nick = localStorage.getItem('TFJL_UserName') || '匿名用户';
                const ts = Date.now();
                let log = [];
                try { log = JSON.parse(localStorage.getItem('TFJL_LoginLog') || '[]'); } catch (e) { log = []; }
                if (!Array.isArray(log)) log = [];
                // 同昵称 60 秒内只记一笔：刷新页面/新版本强刷/关闭马上重开都会重新加载页面各触发一次，
                // 属于同一次使用被重复计数（曾出现同分钟 2 笔）；真正隔 60 秒以上的再次打开照常记录
                const lastLocal = log.length ? log[log.length - 1] : null;
                if (lastLocal && lastLocal.nick === nick && (ts - (lastLocal.ts || 0)) < 60000) return;
                log.push({ nick, ts });
                if (log.length > 5000) log = log.slice(-5000); // 防无限制增长
                localStorage.setItem('TFJL_LoginLog', JSON.stringify(log));
            } catch (e) { /* 忽略存储异常 */ }
            // 异步汇总到公共 Gist（跨设备），失败静默忽略，不阻塞登录
            if (typeof pushLoginEventToGist === 'function') pushLoginEventToGist();
        }
        window.recordLoginEvent = recordLoginEvent;

        // ---- 公共 Gist 汇总：登录打卡记录写入固定的公共 Gist（id 已写死，不再运行时动态创建） ----
        let _loginGistId = '';                       // 运行时缓存（兼容旧逻辑，实际直接用常量）
        const LOGIN_GIST_FILENAME = 'login-log.json';
        const LOGIN_INDEX_FILENAME = 'login_index.json';
        const LOGIN_INDEX_GIST_ID = GIST_ID;         // 复用 INDEX gist 登记 loginGistId（兜底用）
        // ⚠️ 写死固定 ID：登录打卡汇总公共 Gist（首次部署后自动创建，已确认存在且有人打卡；
        //    用户已在 GitHub 后台可见，固定后不再运行时动态创建，避免多设备竞态/依赖 INDEX gist）
        const LOGIN_GIST_ID = '51e7030023fa57de40aaf59bc48e9969';

        async function getLoginGistId() {
            // 直接使用固定 Gist ID（GitHub 后台 gyq-svip 账号可见：描述「TFJL 登录打卡汇总(跨设备)」）
            return LOGIN_GIST_ID;
        }

        async function createLoginGist() {
            const token = getGistToken();
            if (!token) return '';
            try {
                const resp = await fetch('https://api.github.com/gists', {
                    method: 'POST',
                    headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': 'token ' + token },
                    body: JSON.stringify({ description: 'TFJL 登录打卡汇总(跨设备)', public: true, files: { [LOGIN_GIST_FILENAME]: { content: '[]' } } })
                });
                if (!resp.ok) return '';
                const data = await resp.json();
                _loginGistId = data.id;
                localStorage.setItem('TFJL_LOGIN_GIST_ID', _loginGistId);
                // 把 id 登记进 INDEX gist，供其他设备发现（共享同一份汇总）
                try {
                    await fetch('https://api.github.com/gists/' + LOGIN_INDEX_GIST_ID, {
                        method: 'PATCH',
                        headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': 'token ' + token },
                        body: JSON.stringify({ files: { [LOGIN_INDEX_FILENAME]: { content: JSON.stringify({ loginGistId: _loginGistId, createdAt: Date.now() }) } } })
                    });
                } catch (e) { /* 登记失败不影响本机写入 */ }
                return _loginGistId;
            } catch (e) { return ''; }
        }

        // 读取汇总日志（公共 Gist 优先；Gist 不可用则回退本地 localStorage）
        // ⚠️ GET 也必须带 Authorization：token 在手但请求头没带 = 按未认证 60次/h(按IP)限流，
        //    2026-08-22 教训：曾因此经常被限流→静默回退本机缓存，面板只剩自己的记录
        let _loginLogSource = 'local', _loginLogError = ''; // 'gist'=公共汇总 | 'local'=本机缓存（供面板顶部展示）
        async function fetchLoginLog() {
            const id = await getLoginGistId();
            if (id) {
                try {
                    const h = { 'Accept': 'application/vnd.github.v3+json' };
                    const tk = getGistToken(); if (tk) h['Authorization'] = 'token ' + tk;
                    const r = await fetch('https://api.github.com/gists/' + id, { headers: h });
                    if (r.ok) {
                        const data = await r.json();
                        const f = data.files && data.files[LOGIN_GIST_FILENAME];
                        if (f && typeof f.content === 'string') {
                            const arr = JSON.parse(f.content);
                            if (Array.isArray(arr)) { _loginLogSource = 'gist'; _loginLogError = ''; return arr; }
                        }
                        _loginLogError = 'Gist 缺少 ' + LOGIN_GIST_FILENAME;
                    } else {
                        _loginLogError = 'HTTP ' + r.status;
                    }
                } catch (e) { _loginLogError = (e && e.message) || String(e); }
            } else { _loginLogError = '无 Gist ID'; }
            // 回退：本地
            _loginLogSource = 'local';
            try { const l = JSON.parse(localStorage.getItem('TFJL_LoginLog') || '[]'); if (Array.isArray(l)) return l; } catch (e) {}
            return [];
        }
        window.fetchLoginLog = fetchLoginLog;

        async function pushLoginEventToGist() {
            try {
                // 🔴 登录打卡远程开关：默认关（每人每天仅打卡一次）；面板显式开启后才每次打卡
                let loginPunchOn = false;
                try { const lpCfg = await getRoomIndexConfig(); if (typeof lpCfg.loginPunchEnabled === 'boolean') loginPunchOn = lpCfg.loginPunchEnabled; } catch (e) {}
                if (!loginPunchOn) {
                    const todayStr = new Date().toISOString().slice(0, 10);
                    if (localStorage.getItem('__loginPunchedDate') === todayStr) return; // 今天已打过，跳过
                }
                const id = await getLoginGistId();
                if (!id) return;
                const token = getGistToken();
                if (!token) return;
                // 读现有（GET 同样带 token，避免未认证 60次/h 限流）
                const r = await fetch('https://api.github.com/gists/' + id, { headers: { 'Accept': 'application/vnd.github.v3+json', ...(token ? { 'Authorization': 'token ' + token } : {}) } });
                if (!r.ok) return;
                const data = await r.json();
                let arr = [];
                const f = data.files && data.files[LOGIN_GIST_FILENAME];
                if (f && f.content) { try { arr = JSON.parse(f.content) || []; } catch (e) { arr = []; } }
                if (!Array.isArray(arr)) arr = [];
                // Gist 层同样 60 秒去重：本机记录被清过/多设备同昵称同分钟各开一次时，
                // 只让第一笔进汇总，避免同分钟双写
                const myNick = localStorage.getItem('TFJL_UserName') || '匿名用户';
                const lastGist = arr.length ? arr[arr.length - 1] : null;
                if (lastGist && lastGist.nick === myNick && (Date.now() - (lastGist.ts || 0)) < 60000) return;
                arr.push({ nick: myNick, ts: Date.now() });
                if (arr.length > 20000) arr = arr.slice(-20000);
                // 打卡成功：记录今天已打（供远程开关关闭时去重）
                try { localStorage.setItem('__loginPunchedDate', new Date().toISOString().slice(0, 10)); } catch (e) {}
                await fetch('https://api.github.com/gists/' + id, {
                    method: 'PATCH',
                    headers: { 'Accept': 'application/vnd.github.v3+json', 'Content-Type': 'application/json', 'Authorization': 'token ' + token },
                    body: JSON.stringify({ files: { [LOGIN_GIST_FILENAME]: { content: JSON.stringify(arr) } } })
                });
            } catch (e) { /* 忽略 */ }
        }
        window.pushLoginEventToGist = pushLoginEventToGist;
        window.recordLoginEvent = recordLoginEvent;

        // 管理员面板「登录打卡」：公共 Gist 汇总 + 4 视图（📅热力图 / ✅今日签到 / 🕒动态 / 📊总表）
        let _loginTab = 'heat';                        // 当前 Tab
        let _loginSort = { key: 'total', desc: true }; // 总表排序
        let _lastLoginLog = [];                        // 缓存本次拉取，切 Tab 不重复请求
        let _loginOpenDays = {};                       // 动态页已展开的日期（默认全折叠，点开看当日明细）
        async function adminLoadLoginStats() {
            const box = document.getElementById('adminLoginStatsContent');
            if (box) box.innerHTML = '<div style="color:rgba(255,255,255,0.5);text-align:center;min-height:280px;display:flex;align-items:center;justify-content:center;">正在从公共 Gist 汇总…</div>';
            try { _lastLoginLog = await fetchLoginLog(); } catch (e) { _lastLoginLog = []; }
            _renderLoginStats();
        }
        window.adminLoadLoginStats = adminLoadLoginStats;
        window.__setLoginTab = function (t) { _loginTab = t; _renderLoginStats(); };
        window.__sortLoginTable = function (k) {
            if (_loginSort.key === k) _loginSort.desc = !_loginSort.desc;
            else { _loginSort.key = k; _loginSort.desc = true; }
            _loginTab = 'table'; _renderLoginStats();
        };
        window.__toggleLoginDay = function (k) {
            if (_loginOpenDays[k]) delete _loginOpenDays[k]; else _loginOpenDays[k] = 1;
            _renderLoginStats();
        };
        function _renderLoginStats() {
            const box = document.getElementById('adminLoginStatsContent');
            if (box) box.innerHTML = adminBuildLoginStatsHTML(_lastLoginLog);
        }

        function adminBuildLoginStatsHTML(log) {
            log = (Array.isArray(log) ? log : []).filter(r => r && isFinite(r.ts));
            const p2 = (n) => String(n).padStart(2, '0');
            const fmt = (ts) => { const d = new Date(ts); return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate()) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds()); };
            const dayKey = (ts) => fmt(ts).slice(0, 10);
            const rel = (ts) => {
                const s = Math.floor((Date.now() - ts) / 1000);
                if (s < 60) return '刚刚';
                if (s < 3600) return Math.floor(s / 60) + '分钟前';
                if (s < 86400) return Math.floor(s / 3600) + '小时前';
                if (s < 86400 * 2) return '昨天';
                if (s < 86400 * 30) return Math.floor(s / 86400) + '天前';
                return fmt(ts).slice(0, 10);
            };
            const todayKey = dayKey(Date.now());
            const now = Date.now();

            // ---- 按昵称聚合 ----
            const byNick = {};
            for (const r of log) {
                const n = r.nick || '匿名用户';
                if (!byNick[n]) byNick[n] = { count: 0, first: r.ts, last: r.ts, daily: {} };
                const s = byNick[n];
                s.count++;
                if (r.ts < s.first) s.first = r.ts;
                if (r.ts > s.last) s.last = r.ts;
                const d = dayKey(r.ts);
                if (!s.daily[d]) s.daily[d] = [];
                s.daily[d].push(r.ts);
            }
            // 连续打卡天数（今天没打则从昨天起算）
            const streak = (daily) => {
                let s = 0; const dt = new Date(); dt.setHours(0, 0, 0, 0);
                const k = (dt2) => dt2.getFullYear() + '-' + p2(dt2.getMonth() + 1) + '-' + p2(dt2.getDate());
                if (!daily[k(dt)]) dt.setDate(dt.getDate() - 1);
                while (daily[k(dt)]) { s++; dt.setDate(dt.getDate() - 1); }
                return s;
            };
            const dayStartMs = (k) => new Date(k + 'T00:00:00').getTime();
            const stats = Object.keys(byNick).map(n => {
                const s = byNick[n];
                let w7 = 0, w30 = 0;
                for (const k of Object.keys(s.daily)) {
                    if (dayStartMs(k) >= now - 7 * 864e5) w7 += s.daily[k].length;
                    if (dayStartMs(k) >= now - 30 * 864e5) w30 += s.daily[k].length;
                }
                const t = s.daily[todayKey] || [];
                return { nick: n, total: s.count, first: s.first, last: s.last, daily: s.daily, w7, w30, today: t.length, todayFirst: t.length ? Math.min.apply(null, t) : 0, streak: streak(s.daily) };
            }).sort((a, b) => b.total - a.total);

            // ---- 顶部（固定不滚动）：数据源徽标 + 刷新 + Tab 栏 ----
            const srcGist = _loginLogSource === 'gist';
            let head = `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">
                <span style="font-size:0.85rem;${srcGist ? 'color:#a5d6a7;' : 'color:#ffab91;'}">${srcGist
                ? '🌐 公共汇总 · ' + log.length + ' 条 · ' + stats.length + ' 人'
                : '⚠️ 拉取失败' + (_loginLogError ? '（' + escapeHtml(_loginLogError) + '）' : '') + '，显示本机缓存 ' + log.length + ' 条'}</span>
                <button onclick="adminLoadLoginStats()" style="padding:2px 10px;font-size:0.78rem;border:1px solid rgba(255,215,0,0.4);background:rgba(255,215,0,0.1);color:#ffd700;border-radius:10px;cursor:pointer;">🔄 重试</button>
                <span style="font-size:0.75rem;color:rgba(255,255,255,0.45);">${log.length ? '最近登录 ' + rel(Math.max.apply(null, log.map(r => r.ts))) : ''}</span>
            </div>`;

            // ---- Tab 栏 ----
            const TABS = [['heat', '📅 热力图'], ['today', '✅ 今日签到'], ['feed', '🕒 动态'], ['table', '📊 总表']];
            head += `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px;">` + TABS.map(t =>
                `<span onclick="__setLoginTab('${t[0]}')" style="padding:5px 12px;border-radius:14px;cursor:pointer;font-size:0.8rem;${_loginTab === t[0]
                ? 'background:linear-gradient(90deg,#ffd700,#ff9800);color:#1a1a2e;font-weight:600;'
                : 'background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.7);'}">${t[1]}</span>`).join('') + `</div>`;

            let html = '';
            if (stats.length === 0) {
                html += `<div style="color:rgba(255,255,255,0.5);text-align:center;padding:20px;">暂无登录记录</div>`;
            } else if (_loginTab === 'heat') {
                // ---- 近 28 天打卡热力图（GitHub 贡献图风格：颜色越绿=当天登录越多） ----
                const DAYS = 28;
                const start = new Date(); start.setHours(0, 0, 0, 0); start.setDate(start.getDate() - (DAYS - 1));
                const startTs = start.getTime();
                const keyOf = (dt) => dt.getFullYear() + '-' + p2(dt.getMonth() + 1) + '-' + p2(dt.getDate());
                const lvl = (c) => c <= 0 ? 'rgba(255,255,255,0.07)' : c === 1 ? '#0e4429' : c === 2 ? '#006d32' : c === 3 ? '#26a641' : '#39d353';
                let axis = `<div></div>`;
                for (let i = 0; i < DAYS; i++) {
                    const dt = new Date(startTs + i * 864e5);
                    const lab = (i === DAYS - 1) ? '今' : (i % 7 === 0 ? (dt.getMonth() + 1) + '/' + dt.getDate() : '');
                    axis += `<div style="font-size:0.6rem;color:rgba(255,255,255,0.4);text-align:center;">${lab}</div>`;
                }
                html += `<div style="background:rgba(255,255,255,0.04);border:1px solid rgba(165,214,117,0.25);border-radius:10px;padding:10px 12px;">
                    <div style="color:#a5d6a7;font-size:0.9rem;margin-bottom:8px;">📅 近 ${DAYS} 天打卡热力图</div>
                    <div style="overflow-x:auto;"><div style="display:grid;grid-template-columns:76px repeat(${DAYS},1fr);gap:3px;align-items:center;min-width:540px;">`;
                for (const st of stats) {
                    html += `<div style="font-size:0.75rem;color:rgba(255,255,255,0.85);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escapeHtml(st.nick)}">${escapeHtml(st.nick)}</div>`;
                    for (let i = 0; i < DAYS; i++) {
                        const k = keyOf(new Date(startTs + i * 864e5));
                        const c = (st.daily[k] || []).length;
                        html += `<div title="${k}${c ? ' · ' + c + '次' : ''}" style="height:15px;border-radius:3px;background:${lvl(c)};"></div>`;
                    }
                }
                html += `</div><div style="display:grid;grid-template-columns:76px repeat(${DAYS},1fr);gap:3px;margin-top:4px;min-width:540px;">${axis}</div></div>`;
                const sk = stats.filter(s => s.streak > 0).sort((a, b) => b.streak - a.streak);
                html += `<div style="margin-top:10px;font-size:0.8rem;color:#c5cae9;">🔥 连续打卡：${sk.length ? sk.map(s => escapeHtml(s.nick) + ' ' + s.streak + '天').join(' · ') : '暂无'}</div></div>`;
            } else if (_loginTab === 'today') {
                // ---- 今日签到卡 + 未签到名单 ----
                const ins = stats.filter(s => s.today > 0).sort((a, b) => a.todayFirst - b.todayFirst);
                const outs = stats.filter(s => s.today === 0);
                html += `<div style="font-size:0.9rem;color:#ffd700;margin-bottom:8px;">✅ 今日（${todayKey}）已签到 <strong>${ins.length}</strong> 人</div>`;
                if (!ins.length) {
                    html += `<div style="color:rgba(255,255,255,0.45);font-size:0.82rem;margin-bottom:10px;">今天还没有人登录</div>`;
                } else {
                    html += `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(118px,1fr));gap:8px;margin-bottom:12px;">`;
                    for (const s of ins) html += `<div style="background:rgba(165,214,117,0.08);border:1px solid rgba(165,214,117,0.3);border-radius:10px;padding:8px 10px;">
                        <div style="font-size:0.85rem;color:#e8f5e9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escapeHtml(s.nick)}">${escapeHtml(s.nick)}</div>
                        <div style="font-size:0.78rem;color:#80deea;margin:3px 0;">✓ ${fmt(s.todayFirst).slice(11, 16)}</div>
                        <div style="font-size:0.72rem;color:rgba(255,255,255,0.55);">连续 ${s.streak} 天 · 今日 ${s.today} 次</div></div>`;
                    html += `</div>`;
                }
                html += `<div style="font-size:0.82rem;color:rgba(255,255,255,0.6);">😴 今日未签到：${outs.length ? outs.map(s => escapeHtml(s.nick) + '<span style="color:rgba(255,255,255,0.4);">（上次 ' + rel(s.last) + '）</span>').join(' · ') : '无（全员到齐 🎉）'}</div>`;
            } else if (_loginTab === 'feed') {
                // ---- 最近登录动态：按天手风琴（默认全折叠；点日期行展开当日"几点几分·谁"明细） ----
                // 🔴 修复：原 slice(0,60) 在活跃时段一天就有几十次登录，60 条只够覆盖今天+昨天，
                // 更早记录被截断 → 用户看到"最多到昨天"。改为「最近 14 天」过滤（兜底取最近 200 条）。
                const _cutoff = Date.now() - 14 * 864e5;
                let recent = log.filter(r => (r.ts || 0) >= _cutoff).sort((a, b) => b.ts - a.ts);
                if (recent.length === 0) recent = log.slice().sort((a, b) => b.ts - a.ts).slice(0, 200);
                const days = []; const dayMap = {};
                for (const r of recent) {
                    const k = dayKey(r.ts);
                    if (!dayMap[k]) { dayMap[k] = []; days.push(k); }
                    dayMap[k].push(r);
                }
                const yKey = dayKey(now - 864e5);
                const wd = ['日', '一', '二', '三', '四', '五', '六'];
                html += `<div style="font-size:0.9rem;color:#4dd0e1;margin-bottom:8px;">🕒 最近登录动态（最新 ${recent.length} 条 · 点日期展开/收起）</div>`;
                for (const k of days) {
                    const list = dayMap[k];
                    const nicks = [...new Set(list.map(r => r.nick || '匿名用户'))];
                    const open = !!_loginOpenDays[k];
                    const d = new Date(k + 'T00:00:00');
                    const label = k === todayKey ? '今天' : (k === yKey ? '昨天' : k.slice(5).replace('-', '/') + ' 周' + wd[d.getDay()]);
                    html += `<div style="margin-bottom:6px;border:1px solid rgba(77,208,225,${open ? '0.35' : '0.15'});border-radius:10px;overflow:hidden;">
                        <div onclick="__toggleLoginDay('${k}')" style="display:flex;align-items:center;gap:8px;padding:7px 10px;cursor:pointer;background:rgba(77,208,225,${open ? '0.12' : '0.05'});flex-wrap:wrap;">
                            <span style="color:#4dd0e1;font-size:0.8rem;">${open ? '▾' : '▸'}</span>
                            <span style="font-size:0.85rem;color:#e0f7fa;font-weight:600;">${label}</span>
                            <span style="font-size:0.75rem;color:rgba(255,255,255,0.5);">${nicks.length} 人 · ${list.length} 次</span>
                            ${nicks.map(n => `<span style="font-size:0.72rem;color:rgba(255,255,255,0.6);background:rgba(255,255,255,0.06);border-radius:8px;padding:1px 7px;">${escapeHtml(n)}</span>`).join('')}
                        </div>`;
                    if (open) {
                        // 明细按人合并：每人一行（昵称+次数），该人当日各时间点做成小徽章流式排列，占不下自动换行
                        const byN = {};
                        for (const r of list) {
                            const n = r.nick || '匿名用户';
                            if (!byN[n]) byN[n] = [];
                            byN[n].push(r.ts);
                        }
                        const order = Object.keys(byN).sort((a, b) => byN[b].length - byN[a].length || Math.min.apply(null, byN[a]) - Math.min.apply(null, byN[b]));
                        html += `<div style="padding:6px 10px;">`;
                        for (const n of order) {
                            const ts = byN[n].slice().sort((a, b) => a - b);
                            // 名字固定宽度左列 + 徽章显示区右列（各行起点对齐；徽章排不下自动换行）
                            html += `<div style="display:flex;align-items:flex-start;gap:8px;margin:4px 0 7px;">
                                <span style="flex:0 0 96px;max-width:96px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:0.8rem;color:#e0f7fa;padding-top:2px;" title="${escapeHtml(n)} ${ts.length}次">${escapeHtml(n)} <span style="color:rgba(255,255,255,0.45);">${ts.length}次</span></span>
                                <span style="flex:1;display:flex;flex-wrap:wrap;gap:4px;">${ts.map(t => `<span style="font-size:0.75rem;color:#80deea;background:rgba(128,222,234,0.1);border:1px solid rgba(128,222,234,0.25);border-radius:8px;padding:1px 6px;white-space:nowrap;">${fmt(t).slice(11, 16)}</span>`).join('')}</span>
                            </div>`;
                        }
                        html += `</div>`;
                    }
                    html += `</div>`;
                }
            } else {
                // ---- 指标总表（点列头排序） ----
                const COLS = [['nick', '昵称'], ['today', '今日'], ['streak', '连续'], ['w7', '近7天'], ['w30', '近30天'], ['total', '累计'], ['last', '最后在线']];
                const rows = stats.slice().sort((a, b) => {
                    const va = a[_loginSort.key], vb = b[_loginSort.key];
                    const c = (typeof va === 'string') ? va.localeCompare(vb, 'zh') : ((va || 0) - (vb || 0));
                    return _loginSort.desc ? -c : c;
                });
                html += `<div style="font-size:0.9rem;color:#ffd700;margin-bottom:8px;">📊 登录指标总表（点列头排序）</div>
                <div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.8rem;">
                <tr>${COLS.map(c => `<th onclick="__sortLoginTable('${c[0]}')" style="padding:6px 8px;text-align:${c[0] === 'nick' ? 'left' : 'center'};color:#ffd700;cursor:pointer;border-bottom:1px solid rgba(255,215,0,0.3);white-space:nowrap;">${c[1]}${_loginSort.key === c[0] ? (_loginSort.desc ? ' ▼' : ' ▲') : ''}</th>`).join('')}</tr>`;
                for (const s of rows) html += `<tr>
                    <td style="padding:5px 8px;border-bottom:1px solid rgba(255,255,255,0.06);">${escapeHtml(s.nick)}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);">${s.today ? '<span style="color:#a5d6a7;">✓ ' + s.today + '次</span>' : '<span style="color:rgba(255,255,255,0.3);">✗</span>'}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);">${s.streak ? '🔥' + s.streak + '天' : '-'}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);">${s.w7}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);">${s.w30}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);color:#a5d6a7;">${s.total}</td>
                    <td style="padding:5px 8px;text-align:center;border-bottom:1px solid rgba(255,255,255,0.06);color:#80deea;">${rel(s.last)}</td></tr>`;
                html += `</table></div>`;
            }
            // 整体固定高度（四个 Tab 统一，杜绝窗口忽大忽小）：顶部徽标+Tab 固定，内容区内部滚动（可拖动/滚轮）
            return `<div style="display:flex;flex-direction:column;height:min(62vh,480px);min-height:280px;">
                ${head}
                <div style="flex:1;overflow-y:auto;overscroll-behavior:contain;padding:6px 6px 4px 0;">${html}</div>
            </div>`;
        }
        window.adminBuildLoginStatsHTML = adminBuildLoginStatsHTML;
        function openContributionCard(nickEnc) {
            const nick = decodeURIComponent(nickEnc);
            const repMap = computeReputation();
            const e = repMap[nick] || { rep: 0, shares: 0, copies: 0, likes: 0, downloads: 0, firstShare: 0 };
            const t = getTitle(e.rep);
            const allShares = wallMessages.filter(m => isShareMsg(m) && msgAuthor(m) === nick);
            window._contribData = { nick, shares: allShares.map(m => ({ content: stripAllUrls(msgContent(m)), scriptUrl: m.scriptUrl || '', isEncrypted: !!m.isEncrypted, passwordHash: m.passwordHash || '', copyCount: m.copyCount || 0, likes: m.likes || 0 })) };
            const scriptCount = allShares.filter(m => m.scriptUrl).length;
            const pct = Math.round(t.progress * 100);
            const shareItems = allShares.map((m, i) => {
                const c = stripAllUrls(msgContent(m));
                const dlBtn = m.scriptUrl ? `<a href="javascript:void(0)" onclick="downloadScript('${m.scriptUrl}'${m.isEncrypted ? `,true,'${(m.passwordHash || '').replace(/'/g, "\\'")}'` : ',false,\'\''})" style="color:#4fc3f7;text-decoration:none;cursor:pointer;background:rgba(79,195,247,0.1);padding:2px 8px;border-radius:5px;font-size:0.72rem;">📥</a>` : '';
                const dlCnt = (m.copyCount || 0) + _globalDlForMsg(m);
                return `<div style="padding:7px 9px;border-radius:6px;background:rgba(255,255,255,0.04);margin-bottom:6px;font-size:0.76rem;color:#fff;word-break:break-all;line-height:1.4;">
                    <div style="margin-bottom:4px;">${escapeHtml(c) || '（分享脚本）'}</div>
                    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                        <a href="javascript:void(0)" onclick="contribCopyContent(${i})" style="color:#4fc3f7;text-decoration:none;cursor:pointer;background:rgba(79,195,247,0.1);padding:2px 8px;border-radius:5px;font-size:0.72rem;">📋 复制</a>
                        ${dlBtn}
                        <span style="color:rgba(255,215,0,0.6);font-size:0.7rem;">📥 ${dlCnt}</span>
                        <span style="color:rgba(255,107,107,0.6);font-size:0.7rem;">👍 ${m.likes || 0}</span>
                    </div>
                </div>`;
            }).join('');
            const sharesHtml = allShares.length ? `
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
                    <span style="color:rgba(255,255,255,0.6);font-size:0.78rem;">全部分享（${allShares.length}）</span>
                    ${scriptCount ? `<a href="javascript:void(0)" onclick="contribDownloadAll()" style="color:#4fc3f7;text-decoration:none;cursor:pointer;background:rgba(79,195,247,0.12);padding:3px 10px;border-radius:5px;font-size:0.74rem;">📥 下载全部脚本 (${scriptCount})</a>` : ''}
                </div>
                <div style="max-height:260px;overflow-y:auto;margin-bottom:10px;">${shareItems}</div>
            ` : '<div style="color:rgba(255,255,255,0.5);font-size:0.78rem;margin-bottom:10px;">还没有分享记录</div>';
            const body = document.getElementById('contributionCardBody');
            if (body) body.innerHTML = `
                <div style="text-align:center;margin-bottom:12px;">
                    <div style="color:#ffd700;font-size:1.3rem;font-weight:bold;">${escapeHtml(nick)}</div>
                    <div style="color:rgba(255,255,255,0.7);font-size:0.9rem;margin-top:2px;">🎖 ${t.name}</div>
                </div>
                ${renderBadgesHtml(nick, repMap)}
                <div style="background:rgba(255,255,255,0.06);border-radius:8px;padding:10px 12px;margin-bottom:10px;">
                    <div style="display:flex;justify-content:space-between;font-size:0.8rem;color:rgba(255,255,255,0.85);"><span>当前声望</span><span style="color:#ffd700;font-weight:bold;">${e.rep}</span></div>
                    ${t.nextName ? `<div style="margin-top:8px;height:7px;background:rgba(255,255,255,0.1);border-radius:4px;overflow:hidden;"><div style="width:${pct}%;height:100%;background:linear-gradient(90deg,#ffd700,#ff6b6b);"></div></div><div style="font-size:0.7rem;color:rgba(255,255,255,0.5);margin-top:4px;">距「${t.nextName}」还需 ${t.nextRep - e.rep} 声望</div>` : '<div style="font-size:0.75rem;color:rgba(255,215,0,0.7);margin-top:6px;">已达到最高头衔 🏆</div>'}
                </div>
                <div style="display:flex;gap:8px;margin-bottom:12px;">
                    <div style="flex:1;text-align:center;background:rgba(79,195,247,0.1);border-radius:8px;padding:8px 4px;"><div style="color:#4fc3f7;font-size:1.1rem;font-weight:bold;">${e.shares}</div><div style="font-size:0.68rem;color:rgba(255,255,255,0.6);">分享</div></div>
                    <div style="flex:1;text-align:center;background:rgba(255,215,0,0.1);border-radius:8px;padding:8px 4px;"><div style="color:#ffd700;font-size:1.1rem;font-weight:bold;">${e.copies}</div><div style="font-size:0.68rem;color:rgba(255,255,255,0.6);">被复制</div></div>
                    <div style="flex:1;text-align:center;background:rgba(255,193,7,0.1);border-radius:8px;padding:8px 4px;"><div style="color:#ffc107;font-size:1.1rem;font-weight:bold;">${e.downloads}</div><div style="font-size:0.68rem;color:rgba(255,255,255,0.6);">下载</div></div>
                    <div style="flex:1;text-align:center;background:rgba(255,107,107,0.1);border-radius:8px;padding:8px 4px;"><div style="color:#ff6b6b;font-size:1.1rem;font-weight:bold;">${e.likes}</div><div style="font-size:0.68rem;color:rgba(255,255,255,0.6);">获赞</div></div>
                </div>
                <div id="contribProfileEdit" style="background:rgba(255,255,255,0.04);border-radius:8px;padding:10px 12px;margin-bottom:12px;"></div>
                ${sharesHtml}`;
            const card = document.getElementById('contributionCard');
            if (card) card.style.display = 'flex';
            renderContribProfile(nick);
        }

        function bumpPreviewCount(url) {
            try {
                const m = wallMessages.find(x => x.scriptUrl && x.scriptUrl === url);
                if (m) { m.previewCount = (m.previewCount || 0) + 1; saveWallDebounced(); }
            } catch (e) {}
        }
        async function renderMessages() {
            const scroller = document.getElementById('messageScroller');
            if (!scroller) return;
            
            const now = Date.now();
            const nicknameInput = document.getElementById('messageNickname');
            const currentNickname = nicknameInput?.value.trim() || localStorage.getItem('TFJL_UserName') || '';
            const adminNicknames = ['gyq', 'GYQ', '龙行'];
            const isAdmin = adminNicknames.some(nick => currentNickname.toLowerCase() === nick.toLowerCase());
            
            // 过滤消息：默认永久保存，只有设置了expireMinutes的消息才过期
            const validMessages = wallMessages.filter(msg => {
                if (msg.expireMinutes && msg.expireMinutes > 0) {
                    const expireTime = msg.expireMinutes * 60 * 1000;
                    return (now - msg.time) < expireTime;
                }
                return true; // 没有设置过期时间的消息永久保存
            });

            if (validMessages.length === 0) {
                scroller.innerHTML = '<div style="color:rgba(255,255,255,0.5);font-size:0.85rem;text-align:center;padding:20px;">暂无消息，快来发布第一条吧！</div>';
                return;
            }
            
            const repMap = computeReputation();
            const html = validMessages.map((msg, index) => {
                const timeAgo = formatMessageTime(msg.time);
                let contentHtml = escapeHtml(msg.content);
                // 非分享消息：可见文本里若有 GitHub 地址一律剥离，不引导用户去 GitHub
                if (!msg.scriptUrl) contentHtml = stripGithubUrls(contentHtml);

                // 判断是否可以删除（发布者可删自己的，管理员可删所有）
                const isOwner = msg.author.toLowerCase() === currentNickname.toLowerCase();
                const canDelete = isOwner || isAdmin;
                
                // 过期标签
                const expireLabel = msg.expireMinutes ? `<span style="color:#ff9800;font-size:0.7rem;margin-left:5px;" title="${formatDuration(msg.expireMinutes)}后过期">⏱️${formatDuration(msg.expireMinutes)}</span>` : '';
                // 加密标签
                const encryptedLabel = msg.isEncrypted ? `<span style="color:#ce93d8;font-size:0.7rem;margin-left:5px;" title="密码保护">🔒</span>` : '';
                
                if (msg.scriptUrl) {
                    // 检查文件名是否是JSON备份文件
                    const urlFileName = msg.scriptUrl.split('/').pop() || '';
                    const isJsonFile = urlFileName.toLowerCase().endsWith('.json');
                    const isBackup = msg.shareType === 'backup' || msg.scriptUrl.includes('backup') || contentHtml.includes('备份') || contentHtml.includes('项目') || isJsonFile;
                    const encInfo2 = msg.isEncrypted ? `,true,'${(msg.passwordHash || '').replace(/'/g,"\\'")}'` : `,false,''`;
                    
                    if (msg.shareType === 'project') {
                        // 阵容项目分享：整项目 JSON，只允许「智能导入」，不允许预览/下载/复制/导入到老马
                        // （项目 JSON 直接智能导入最干净，避免下载后版本错乱或被外传）
                        contentHtml = contentHtml.replace(
                            msg.scriptUrl,
                            `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                                <a href="javascript:void(0)" onclick="importScriptToTxtFiles('${msg.scriptUrl}'${encInfo2})" style="color:#4caf50;text-decoration:underline;cursor:pointer;background:rgba(76,175,80,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📄 智能导入</a>
                            </div>`
                        );
                    } else if (isBackup) {
                        contentHtml = contentHtml.replace(
                            msg.scriptUrl,
                            `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                                <a href="javascript:void(0)" onclick="previewScriptFile('${msg.scriptUrl}'${encInfo2})" style="color:#e0e0e0;text-decoration:underline;cursor:pointer;background:rgba(224,224,224,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">👁️ 预览</a>
                                <a href="javascript:void(0)" onclick="downloadScript('${msg.scriptUrl}'${encInfo2})" style="color:#4fc3f7;text-decoration:underline;cursor:pointer;background:rgba(79,195,247,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📥 下载</a>
                                <a href="javascript:void(0)" onclick="importBackupFromWall('${msg.scriptUrl}'${encInfo2})" style="color:#ff9800;text-decoration:underline;cursor:pointer;background:rgba(255,152,0,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📦 导入备份</a>
                            </div>`
                        );
                    } else {
                        const urlFileName2 = msg.scriptUrl.split('/').pop() || 'script.txt';
                        const encInfo = msg.isEncrypted ? `,true,'${(msg.passwordHash || '').replace(/'/g,"\\'")}'` : `,false,''`;
                        contentHtml = contentHtml.replace(
                            msg.scriptUrl,
                            `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;">
                                <a href="javascript:void(0)" onclick="previewScriptFile('${msg.scriptUrl}'${encInfo})" style="color:#e0e0e0;text-decoration:underline;cursor:pointer;background:rgba(224,224,224,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">👁️ 预览</a>
                                <a href="javascript:void(0)" onclick="downloadScript('${msg.scriptUrl}'${encInfo})" style="color:#4fc3f7;text-decoration:underline;cursor:pointer;background:rgba(79,195,247,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📥 下载</a>
                                <a href="javascript:void(0)" onclick="importScriptToTxtFiles('${msg.scriptUrl}'${encInfo})" style="color:#4caf50;text-decoration:underline;cursor:pointer;background:rgba(76,175,80,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;">📄 智能导入</a>
                                <a href="javascript:void(0)" onclick="importToLaoMaFromWall('${msg.scriptUrl}','${urlFileName2.replace(/'/g,"\\'")}'${encInfo})" style="color:#ff9800;text-decoration:underline;cursor:pointer;background:rgba(255,152,0,0.1);padding:4px 10px;border-radius:5px;font-size:0.8rem;" id="laoLaoImportBtn_${index}">📁 导入到老马</a>
                            </div>`
                        );
                    }
                }
                
                const deleteBtn = canDelete ? `<a href="javascript:void(0)" onclick="deleteMessage(${index})" style="color:#ff6b6b;cursor:pointer;margin-left:10px;font-size:0.7rem;" title="${isOwner ? '删除我的消息' : '管理员删除'}">🗑️</a>` : '';
                
                // 分享类消息：附加 复制/赞/踩 操作条（声望系统）
                if (isShareMsg(msg)) {
                    const _b64 = wallMsgKey(msg);
                    contentHtml += renderShareActions(msg, _b64);
                }

                // 纯表情消息：放大渲染（更搞笑）
                const _raw = msg.content || '';
                const _isEmojiOnly = _raw.length > 0 && /^[\s\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{1F1E6}-\u{1F1FF}\u{200D}\u{20E3}\u{2049}\u{203C}\u{303D}\u{00A9}\u{00AE}]+$/u.test(_raw) && !/\p{L}/u.test(_raw);

                const _aRep = repMap[msgAuthor(msg)] ? repMap[msgAuthor(msg)].rep : 0;
                const _aTitle = getTitle(_aRep).name;
                // 取昵称首字做头像圆点
                const _avatar = (msgAuthor(msg) || '?').trim().charAt(0).toUpperCase();
                const _whoHtml = `<div onclick="openContributionCard('${encodeURIComponent(msgAuthor(msg))}')" title="查看 ${escapeHtml(msgAuthor(msg))} 的贡献主页" style="display:flex;align-items:center;gap:8px;cursor:pointer;">
                    <span style="flex-shrink:0;width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#ffd700,#ff6b6b);color:#1a1a2e;font-size:0.85rem;font-weight:bold;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,0.3);">${escapeHtml(_avatar)}</span>
                    <span style="color:#ffd700;font-weight:bold;font-size:0.9rem;text-decoration:underline;">${escapeHtml(msgAuthor(msg))}</span>
                    <span style="color:rgba(255,215,0,0.7);font-size:0.68rem;background:rgba(255,215,0,0.12);padding:1px 7px;border-radius:10px;">${_aTitle}</span>
                    <span style="margin-left:auto;color:rgba(255,255,255,0.4);font-size:0.68rem;display:flex;align-items:center;gap:4px;">${timeAgo}${expireLabel}${encryptedLabel}${deleteBtn}</span>
                </div>`;
                return `<div style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.07);border-radius:10px;padding:10px 12px 8px;font-size:0.85rem;">
                    <div style="margin-bottom:8px;">${_whoHtml}</div>
                    <div style="background:rgba(0,0,0,0.28);border-left:3px solid #ffd700;border-radius:6px;padding:9px 11px;color:#fff;line-height:1.6;font-size:0.86rem;word-break:break-word;" class="${_isEmojiOnly ? 'msgEmojiOnly' : ''}">${contentHtml}</div>
                </div>`;
            }).join('');
            
            scroller.innerHTML = html;
            startMessageScroll();
        }

        // 预览需求墙分享的脚本文件
        // isEncrypted: 是否加密, passwordHash: v2 PBKDF2 哈希(或旧 SHA-256/fnv) 用于验证密码
        async function previewScriptFile(url, isEncrypted = false, passwordHash = '') {
            bumpPreviewCount(url); // 预览榜计数（需求墙分享）
            // 加密文件先提示输入密码
            let decryptPassword = '';
            if (isEncrypted) {
                decryptPassword = await askDecryptPasswordAsync('该文件已加密，请输入密码或恢复密钥：');
                if (!decryptPassword) return;
            }

            try {
                // 从URL提取文件名
                let fileName = 'preview.txt';
                try {
                    const urlObj = new URL(url);
                    const pathParts = urlObj.pathname.split('/');
                    const lastPart = pathParts[pathParts.length - 1];
                    if (lastPart && lastPart !== 'raw' && lastPart.length > 0) {
                        fileName = decodeURIComponent(lastPart);
                    }
                } catch (e) {
                    const lastPart = url.split('/').pop();
                    if (lastPart && lastPart !== 'raw' && lastPart.length > 0) {
                        fileName = decodeURIComponent(lastPart);
                    }
                }

                // 获取文件内容
                let content = null;
                // 先尝试直接fetch（公开Gist的raw_url可直接访问）
                try {
                    const resp = await fetch(url);
                    if (resp.ok) {
                        content = await resp.text();
                    }
                } catch (e) {
                    // CORS或网络错误，尝试API方式
                }
                // 如果直接fetch失败，尝试通过Gist API获取（支持私有Gist）
                if (content === null) {
                    const token = getGistToken();
                    const gistMatch = url.match(/gist\.githubusercontent\.com\/[^/]+\/([a-f0-9]+)/i) || url.match(/gist\.github\.com\/[^/]+\/([a-f0-9]+)/i);
                    if (gistMatch && token) {
                        try {
                            const apiResp = await fetch(`https://api.github.com/gists/${gistMatch[1]}`, {
                                headers: { 'Accept': 'application/vnd.github.v3+json', 'Authorization': `token ${token}` }
                            });
                            if (apiResp.ok) {
                                const gistData = await apiResp.json();
                                // 找到匹配的文件
                                for (const f of Object.values(gistData.files)) {
                                    if (f.filename === fileName || url.includes(f.filename)) {
                                        content = f.content;
                                        break;
                                    }
                                }
                                // 如果没匹配到文件名，取第一个文件
                                if (content === null && gistData.files) {
                                    const firstFile = Object.values(gistData.files)[0];
                                    if (firstFile) content = firstFile.content;
                                }
                            }
                        } catch (e) {
                            console.warn('API方式获取Gist失败:', e);
                        }
                    }
                }
                if (content === null) {
                    throw new Error('获取文件失败，可能需要登录或文件不存在');
                }

                // 判断是否是JSON
                const isJson = fileName.toLowerCase().endsWith('.json');
                let displayContent = content;
                let lang = 'text';
                if (isJson) {
                    try {
                        displayContent = JSON.stringify(JSON.parse(content), null, 2);
                        lang = 'json';
                    } catch (e) {}
                }

                // 解密（如果文件被加密）
                if (isEncrypted && decryptPassword) {
                    const decrypted = await decryptContent(content, decryptPassword);
                    if (decrypted === null) {
                        alert('❌ 解密失败，可能是密码不正确或文件已损坏');
                        return;
                    }
                    content = decrypted;
                    displayContent = decrypted;
                    if (isJson) {
                        try {
                            displayContent = JSON.stringify(JSON.parse(decrypted), null, 2);
                        } catch (e) {}
                    }
                }

                // 复用统一脚本浮窗（可编辑，减伤栏与本地脚本完全一致；远程内容无本地 fileIndex，故不可保存/对比）
                openScriptNotebook({ name: fileName, content: displayContent, fileIndex: -1 });
            } catch (err) {
                console.error('预览文件失败:', err);
                alert('预览失败: ' + err.message);
            }
        }
        async function deleteMessage(index) {
            if (!confirm('确定要删除这条消息吗？')) return;

            const nicknameInput = document.getElementById('messageNickname');
            const currentNickname = nicknameInput?.value.trim() || localStorage.getItem('TFJL_UserName') || '';
            const adminNicknames = ['gyq', 'GYQ', '龙行'];
            const isAdmin = adminNicknames.some(nick => currentNickname.toLowerCase() === nick.toLowerCase());
            const msg = wallMessages[index];

            if (!msg) return;

            const isOwner = msg.author.toLowerCase() === currentNickname.toLowerCase();
            if (!isOwner && !isAdmin) {
                alert('你没有权限删除这条消息');
                return;
            }

            // 【关键安全】删除是强制保存（forceSave=true），会直接用本地数据覆盖远程
            // 所以删除前必须先从Gist加载完整消息，否则可能因本地消息不完整导致其他消息丢失
            if (wallMessages.length < 5) {
                try { await fetchMessages(); } catch (e) { console.warn('预加载消息失败:', e); }
            }

            // 删除关联的脚本Gist文件
            if (msg.scriptUrl) {
                try {
                    const token = getGistToken();
                    if (token) {
                        let gistId = null;
                        if (msg.scriptUrl.includes('gist.githubusercontent.com')) {
                            const match = msg.scriptUrl.match(/gist\.githubusercontent\.com\/[^\/]+\/([a-zA-Z0-9]+)/i);
                            if (match) gistId = match[1];
                        } else if (msg.scriptUrl.includes('gist.github.com') && !msg.scriptUrl.includes('api.github.com')) {
                            const match = msg.scriptUrl.match(/gist\.github\.com\/[^\/]+\/([a-zA-Z0-9]+)/i);
                            if (match) gistId = match[1];
                        } else if (msg.scriptUrl.includes('/gists/')) {
                            const match = msg.scriptUrl.match(/\/gists\/([a-zA-Z0-9]+)/i);
                            if (match) gistId = match[1];
                        }
                        if (gistId) {
                            const delResp = await fetch(`https://api.github.com/gists/${gistId}`, {
                                method: 'DELETE',
                                headers: { 'Authorization': `token ${token}` }
                            });
                            if (!delResp.ok) {
                                console.warn(`删除脚本Gist失败 (${delResp.status}): ${gistId}`);
                            }
                        } else {
                            console.warn(`无法从URL提取Gist ID: ${msg.scriptUrl}`);
                        }
                    }
                } catch (e) {
                    console.warn('删除关联脚本失败:', e);
                }
            }

            wallMessages.splice(index, 1);
            renderMessages();

            // 强制保存（带重试）：删除必须可靠同步到远程，否则会出现
            // "本地删了、其他客户端仍可见、导入失败"的脏状态（分享的 Gist 文件已删、记录却残留）
            let saved = false;
            let lastErr = null;
            for (let attempt = 1; attempt <= 3 && !saved; attempt++) {
                try {
                    await saveMessagesToGist(true); // 强制保存，跳过合并逻辑
                    saved = true;
                } catch (error) {
                    lastErr = error;
                    console.error(`删除消息保存失败(第${attempt}次):`, error);
                    if (attempt < 3) await new Promise(r => setTimeout(r, 800 * attempt));
                }
            }
            if (!saved) {
                console.error('删除消息最终失败:', lastErr);
                alert('⚠️ 删除未完全同步到服务器（可能网络波动或接口限流）。\n\n本地已移除，但其他客户端可能仍可见、导入可能失败。\n请稍后刷新页面重试删除，或等限流恢复。');
            }
        }
        
        function formatMessageTime(timestamp) {
            const now = Date.now();
            const diff = now - timestamp;
            const minutes = Math.floor(diff / 60000);
            const hours = Math.floor(diff / 3600000);
            const days = Math.floor(diff / 86400000);
            
            if (minutes < 1) return '刚刚';
            if (minutes < 60) return `${minutes}分钟前`;
            if (hours < 24) return `${hours}小时前`;
            return `${days}天前`;
        }
        
        function escapeHtml(text) {
            if (!text) return '';
            const s = String(text);
            return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
        }
        
        function startMessageScroll() {
            if (wallScrollUserPaused) return;   // 用户主动关了滚动，不启动
            if (messageScrollInterval) clearInterval(messageScrollInterval);
            
            const content = document.getElementById('messageWallContent');
            const scroller = document.getElementById('messageScroller');
            if (!content || !scroller) return;
            
            if (scroller.scrollHeight <= content.clientHeight) return;
            
            messageScrollInterval = setInterval(() => {
                content.scrollTop += 0.5;
                if (content.scrollTop >= scroller.scrollHeight - content.clientHeight) {
                    content.scrollTop = 0;
                }
            }, 50);
        }
        
        function pauseMessageScroll() {
            if (messageScrollInterval) {
                clearInterval(messageScrollInterval);
                messageScrollInterval = null;
            }
        }
        
        function resumeMessageScroll() {
            // 鼠标移出墙体时恢复滚动，但仅当用户没有主动关闭滚动
            if (wallScrollUserPaused) return;
            startMessageScroll();
        }
        
        async function downloadScript(url, isEncrypted = false, passwordHash = '') {
            // 加密文件先提示输入密码
            let decryptPassword = '';
            if (isEncrypted) {
                decryptPassword = await askDecryptPasswordAsync('该文件已加密，请输入密码或恢复密钥：');
                if (!decryptPassword) return;
            }

            let fileName = 'download.txt';
            try {
                const urlObj = new URL(url);
                const pathParts = urlObj.pathname.split('/');
                const lastPart = pathParts[pathParts.length - 1];
                if (lastPart && lastPart !== 'raw' && lastPart.length > 0) {
                    fileName = decodeURIComponent(lastPart);
                }
            } catch (e) {
                const lastPart = url.split('/').pop();
                if (lastPart && lastPart !== 'raw' && lastPart.length > 0) {
                    fileName = decodeURIComponent(lastPart);
                }
            }

            try {
                // 加载提示
                showToast('📥 正在下载 ' + fileName);

                // 记录下载
                await recordDownload(fileName);

                // 获取文件内容
                const response = await fetch(url);
                if (!response.ok) {
                    throw new Error(`获取文件失败: ${response.status}`);
                }
                let content = await response.text();

                // 解密（如果加密）
                if (isEncrypted && decryptPassword) {
                    const decrypted = await decryptContent(content, decryptPassword);
                    if (decrypted === null) {
                        alert('❌ 解密失败，可能密码不正确');
                        return;
                    }
                    content = decrypted;
                }

                const isTauri = !!(window.__TAURI__ || window.__TAURI_INTERNALS__);
                if (isTauri) {
                    await _downloadScriptTauri(fileName, content);
                    return;
                }

                // —— 网页版：原有流程 ——
                const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });

                if (window.showSaveFilePicker) {
                    try {
                        const handle = await window.showSaveFilePicker({
                            suggestedName: fileName,
                            types: [{
                                description: '文本文件',
                                accept: { 'text/plain': ['.txt', '.json', '.js', '.lua', '.py', '.sh'] }
                            }]
                        });
                        const writable = await handle.createWritable();
                        await writable.write(blob);
                        await writable.close();
                        showToast('✅ 已保存: ' + fileName);
                        return;
                    } catch (e) {
                        if (e.name === 'AbortError') { showToast('已取消下载'); return; }
                    }
                }

                // 传统浏览器下载
                const blobUrl = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = blobUrl;
                a.download = fileName;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(blobUrl);
                showToast('✅ 已下载: ' + fileName);
            } catch (error) {
                console.warn('下载失败，尝试直接打开:', error);
                showToast('⚠️ 下载失败，在新窗口打开');
                window.open(url, '_blank');
            }
        }

        // Tauri APP 原生下载：精美弹窗 → 老马目录（一键）或 自定义文件夹（浏览）
        // opts 可选：{ title: 弹窗标题, dirs: 目录卡片配置（null=不显示预置卡片，如备份保存）, onSaved(savePath), fallback(fileName, content) }
        async function _downloadScriptTauri(fileName, content, opts) {
            opts = opts || {};
            const invokeFn = window.__TAURI_INTERNALS__?.invoke || window.__TAURI__?.core?.invoke;
            if (!invokeFn) { _downloadScriptBlob(fileName, content); return; }

            const fileSizeKB = (content.length / 1024).toFixed(1);
            const dirLabels = (opts.dirs === null) ? null : (opts.dirs || {
                coop:       { label: '合作脚本', icon: '🤝' },
                activity:   { label: '活动',     icon: '🎉' },
                battle:     { label: '对战JSON', icon: '⚔️' },
                battleMax:  { label: '对战MAX',  icon: '📊' },
                screenshot: { label: '截图',     icon: '📸' },
                logs:       { label: '日志',     icon: '📋' },
                temp:       { label: '临时脚本', icon: '📝' }
            });

            return new Promise((resolve) => {
                // —— 构建老马目录卡片 ——
                let dirCardsHtml = '';
                let hasAnyDir = false;
                const dirSavePaths = {};
                if (dirLabels) for (const [key, info] of Object.entries(dirLabels)) {
                    const dirPath = (window.maDirs && window.maDirs[key]) || '';
                    if (!dirPath) continue;
                    hasAnyDir = true;
                    const savePath = dirPath.replace(/[\\/]+$/, '') + '\\' + fileName;
                    const cardId = 'saveCard_' + key;
                    dirSavePaths[cardId] = savePath;
                    dirCardsHtml += `
                <div id="${cardId}" class="save-dir-card"
                     style="cursor:pointer;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.15);border-radius:10px;padding:12px 16px;text-align:left;display:flex;align-items:center;gap:10px;transition:all 0.2s;">
                    <span style="font-size:1.3rem;">${info.icon}</span>
                    <div style="flex:1;min-width:0;">
                        <div style="color:#fff;font-size:0.85rem;">${info.label}</div>
                        <div style="color:rgba(255,255,255,0.35);font-size:0.68rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(savePath)}</div>
                    </div>
                </div>`;
                }

                const maSection = !dirLabels ? '' : (hasAnyDir ? `
                <div style="color:rgba(255,255,255,0.5);font-size:0.75rem;margin-bottom:8px;">📁 保存到老马目录（点击即保存）：</div>
                <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:12px;">${dirCardsHtml}</div>` : `
                <div style="color:rgba(255,255,255,0.3);font-size:0.8rem;text-align:center;margin-bottom:12px;padding:12px;background:rgba(255,152,0,0.08);border-radius:8px;">⚠️ 未配置老马目录，请先在APP本地设置中配置</div>`);

                const modal = document.createElement('div');
                modal.id = 'downloadSaveModal';
                modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);display:flex;align-items:center;justify-content:center;z-index:99999;';
                modal.innerHTML = `
            <div style="background:linear-gradient(135deg,#1a1a2e,#16213e);border:2px solid rgba(255,152,0,0.5);border-radius:16px;padding:24px;max-width:480px;width:90%;box-shadow:0 8px 32px rgba(0,0,0,0.5);max-height:85vh;overflow-y:auto;">
                <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:16px;">
                    <div>
                        <span style="color:#ff9800;font-size:1.1rem;font-weight:bold;">${escapeHtml(opts.title || '📥 保存脚本')}</span>
                        <div style="color:#fff;font-size:0.9rem;margin-top:4px;word-break:break-all;">${escapeHtml(fileName)}</div>
                        <div style="color:rgba(255,255,255,0.35);font-size:0.7rem;">${fileSizeKB} KB</div>
                    </div>
                    <span id="_dlClose" style="cursor:pointer;color:rgba(255,255,255,0.4);font-size:1.5rem;line-height:1;transition:color 0.2s;" onmouseover="this.style.color='#fff'" onmouseout="this.style.color='rgba(255,255,255,0.4)'">×</span>
                </div>
${maSection}
                <div style="display:flex;align-items:center;gap:10px;margin:14px 0;color:rgba(255,255,255,0.3);font-size:0.75rem;">
                    <div style="flex:1;height:1px;background:rgba(255,255,255,0.1);"></div>
                    或者保存到自定义文件夹
                    <div style="flex:1;height:1px;background:rgba(255,255,255,0.1);"></div>
                </div>

                <div id="_customSaveArea" style="background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);border-radius:10px;padding:14px;">
                    <div style="display:flex;align-items:center;gap:10px;">
                        <span style="font-size:1.2rem;">📂</span>
                        <button id="_pickCustomFolderBtn" style="background:linear-gradient(135deg,#2196f3,#1565c0);color:white;border:none;padding:7px 16px;border-radius:6px;cursor:pointer;font-size:0.8rem;white-space:nowrap;">浏览文件夹...</button>
                        <span id="_selectedFolderText" style="color:rgba(255,255,255,0.35);font-size:0.75rem;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">未选择</span>
                    </div>
                    <div id="_customPreview" style="display:none;margin-top:10px;padding-top:10px;border-top:1px solid rgba(255,255,255,0.08);">
                        <div style="color:#4caf50;font-size:0.75rem;margin-bottom:8px;word-break:break-all;" id="_customFullPath"></div>
                        <button id="_saveToCustomBtn" style="background:linear-gradient(135deg,#4caf50,#2e7d32);color:white;border:none;padding:9px 20px;border-radius:8px;cursor:pointer;font-size:0.85rem;width:100%;">✅ 保存到此处</button>
                    </div>
                </div>

                <button id="_cancelDownloadBtn" style="background:rgba(255,255,255,0.08);color:rgba(255,255,255,0.6);border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:10px;cursor:pointer;font-size:0.85rem;width:100%;margin-top:12px;transition:all 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.15)';this.style.color='#fff'" onmouseout="this.style.background='rgba(255,255,255,0.08)';this.style.color='rgba(255,255,255,0.6)'">取消</button>
            </div>`;

                document.body.appendChild(modal);

                // 点击遮罩关闭
                modal.onclick = function(e) { if (e.target === modal) { modal.remove(); resolve(false); } };

                let selectedCustomFolder = '';

                // Close / Cancel
                document.getElementById('_dlClose').onclick = () => { modal.remove(); resolve(false); };
                document.getElementById('_cancelDownloadBtn').onclick = () => { modal.remove(); resolve(false); };

                // Save helpers
                async function doSave(savePath) {
                    modal.remove();
                    try {
                        await invokeFn('write_text_file', { filePath: savePath, content: content });
                        if (typeof opts.onSaved === 'function') opts.onSaved(savePath);
                        else showToast('✅ 已保存: ' + fileName);
                        resolve(true);
                    } catch (e) {
                        console.warn('Tauri保存失败，降级到浏览器下载:', e);
                        if (typeof opts.fallback === 'function') opts.fallback(fileName, content);
                        else _downloadScriptBlob(fileName, content);
                        resolve(true);
                    }
                }

                // 老马目录卡片：hover + click
                for (const [cardId, savePath] of Object.entries(dirSavePaths)) {
                    const card = document.getElementById(cardId);
                    if (!card) continue;
                    card.addEventListener('mouseover', () => { card.style.background = 'rgba(255,152,0,0.15)'; card.style.borderColor = 'rgba(255,152,0,0.5)'; });
                    card.addEventListener('mouseout',  () => { card.style.background = 'rgba(255,255,255,0.06)'; card.style.borderColor = 'rgba(255,255,255,0.15)'; });
                    card.addEventListener('click', () => doSave(savePath));
                }

                // 自定义文件夹 — 浏览
                document.getElementById('_pickCustomFolderBtn').onclick = async () => {
                    try {
                        const folder = await invokeFn('open_directory_dialog');
                        if (!folder) return;
                        selectedCustomFolder = folder;
                        document.getElementById('_selectedFolderText').textContent = folder;
                        document.getElementById('_selectedFolderText').style.color = 'rgba(255,255,255,0.8)';
                        const fullPath = folder.replace(/[\\/]+$/, '') + '\\' + fileName;
                        document.getElementById('_customFullPath').textContent = fullPath;
                        document.getElementById('_customPreview').style.display = 'block';
                    } catch (e) {
                        console.warn('目录选择失败:', e);
                    }
                };

                // 自定义文件夹 — 确认保存
                document.getElementById('_saveToCustomBtn').onclick = () => {
                    if (!selectedCustomFolder) return;
                    const savePath = selectedCustomFolder.replace(/[\\/]+$/, '') + '\\' + fileName;
                    doSave(savePath);
                };
            });
        }

        // 浏览器传统 Blob 下载（含 Toast 反馈）
        function _downloadScriptBlob(fileName, content) {
            const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
            const blobUrl = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = blobUrl;
            a.download = fileName;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(blobUrl);
            showToast('✅ 已下载: ' + fileName);
        }

