                                html += '<div style="margin-bottom:6px;">' + _colorWho(m.who) + ' <span style="color:' + C_TIME + ';">[' + ts + '  ' + min + '分钟前]</span><br><span>' + flag + rc + '</span>';
                                if (m.err) html += '<br><span style="color:#f87171;">err: ' + m.err + '</span>';
