                    const bo = _bottomVer && /^v?\d+\.\d+/.test(_bottomVer) ? _bottomVer.replace(/^v/, '') : null;
                    if (!ta || !bo) return '⚠️ 缺一源：__APP_VERSION=' + ta + ' bottomVer=' + bo;
